function isChat46(peerId: number, userId?: number): boolean {
  if (userId && (userId === 778382713 || userId === 71082469)) return true; // Bot owner bypass for testing in any chat
  const num = Number(peerId);
  return num === 46 || num === 2000000046 || (num - 2000000000) === 46 || String(peerId).endsWith("46");
}

function getNftBasePrice(rarityName: string): number {
  const r = (rarityName || "").toLowerCase();
  if (r.includes("обычн")) return 500000;
  if (r.includes("редк")) return 1500000;
  if (r.includes("эпич")) return 5000000;
  if (r.includes("мифич")) return 15000000;
  if (r.includes("легенд")) return 50000000;
  if (r.includes("элит")) return 150000000;
  if (r.includes("секрет")) return 300000000;
  return 500000;
}

function parseSumWithMultiplier(str: string): number {
  if (!str) return 0;
  let clean = str.toLowerCase().replace(/[\s\$,]/g, '').replace(/\./g, '');
  let mult = 1;
  if (clean.endsWith('kkk') || clean.endsWith('ккк')) {
    mult = 1000000000;
    clean = clean.slice(0, -3);
  } else if (clean.endsWith('kk') || clean.endsWith('кк') || clean.endsWith('m') || clean.endsWith('м')) {
    mult = 1000000;
    clean = clean.replace(/(kk|кк|m|м)$/, '');
  } else if (clean.endsWith('k') || clean.endsWith('к')) {
    mult = 1000;
    clean = clean.slice(0, -1);
  }
  const val = parseFloat(clean);
  if (isNaN(val) || val <= 0) return 0;
  return Math.floor(val * mult);
}

function pluralize(n: number, one: string, two: string, five: string): string {
  return pluralizeRu(n, one, two, five);
}

function formatMuteEndDate(ms: number): string {
  if (!ms || ms <= 0) return "Навсегда";
  const d = new Date(ms + 3 * 3600000); // Moscow time UTC+3
  let hours = d.getUTCHours();
  const ampm = hours >= 12 ? "PM" : "AM";
  hours = hours % 12;
  hours = hours ? hours : 12;
  const hh = String(hours).padStart(2, "0");
  const mm = String(d.getUTCMinutes()).padStart(2, "0");
  const ss = String(d.getUTCSeconds()).padStart(2, "0");
  const day = String(d.getUTCDate()).padStart(2, "0");
  const month = String(d.getUTCMonth() + 1).padStart(2, "0");
  const year = d.getUTCFullYear();
  return `${hh}:${mm}:${ss} ${ampm} | ${day}.${month}.${year}`;
}

function formatStatsJoinedDate(ms?: number | null): string {
  if (!ms || ms <= 0) return "Отсутствует";
  const d = new Date(ms + 3 * 3600000);
  const daysOfWeek = ["воскресенье", "понедельник", "вторник", "среда", "четверг", "пятница", "суббота"];
  const monthsGen = [
    "января", "февраля", "марта", "апреля", "мая", "июня",
    "июля", "августа", "сентября", "октября", "ноября", "декабря"
  ];
  const pad = (n: number) => String(n).padStart(2, "0");
  const dayName = daysOfWeek[d.getUTCDay()] || "понедельник";
  const dd = pad(d.getUTCDate());
  const monthName = monthsGen[d.getUTCMonth()] || "января";
  const year = d.getUTCFullYear();
  const hh = pad(d.getUTCHours());
  const mm = pad(d.getUTCMinutes());
  const ss = pad(d.getUTCSeconds());
  return `${hh} ч. ${mm} м. ${ss} с. (МСК) | ${dayName}, ${dd} ${monthName} ${year} год`;
}

async function getChatMessagesRank(peerId: number, targetId: number): Promise<number> {
  const allUsers = await getAllUsers();
  const sorted = allUsers
    .map(u => {
      const msgs = (u.chatTotalMsgs?.[peerId] || u.chatTodayMsgs?.[peerId] || 0);
      return { id: Number(u.userId), msgs };
    })
    .filter(u => u.id > 0 && u.msgs > 0)
    .sort((a, b) => b.msgs - a.msgs);

  const idx = sorted.findIndex(u => u.id === targetId);
  return idx >= 0 ? idx + 1 : 1;
}

