function formatNumberDots(num: number | string): string {
  if (num === null || num === undefined) return "0";
  const n = typeof num === "string" ? parseFloat(num) : num;
  if (isNaN(n)) return "0";
  return n.toLocaleString("ru-RU").replace(/\s/g, ".");
}

function formatBanchatDate(ts?: number | string | null): { timeStr: string; dateStr: string } {
  if (!ts) return { timeStr: "00 ч. 00 м. 00 с.", dateStr: "Неизвестно" };
  const num = typeof ts === "string" ? parseInt(ts, 10) : ts;
  if (!num || isNaN(num) || num <= 0) return { timeStr: "00 ч. 00 м. 00 с.", dateStr: "Неизвестно" };
  const d = new Date(num + 3 * 3600000); // Moscow time UTC+3
  const daysOfWeek = ["воскресенье", "понедельник", "вторник", "среда", "четверг", "пятница", "суббота"];
  const monthsGen = [
    "января", "февраля", "марта", "апреля", "мая", "июня",
    "июля", "августа", "сентября", "октября", "ноября", "декабря"
  ];
  const pad = (n: number) => String(n).padStart(2, "0");
  const dayName = daysOfWeek[d.getUTCDay()] || "понедельник";
  const dd = pad(d.getUTCDate());
  const monthName = monthsGen[d.getUTCMonth()] || "января";
  const year = d.getUTCFullYear();
  const hh = pad(d.getUTCHours());
  const mm = pad(d.getUTCMinutes());
  const ss = pad(d.getUTCSeconds());
  return {
    timeStr: `${hh} ч. ${mm} м. ${ss} с.`,
    dateStr: `${dayName}, ${dd} ${monthName} ${year} года`
  };
}

function formatAuctionEndDate(endTimeMs: number): { timeRemainingStr: string, dateStr: string } {
  const now = Date.now();
  const diffSec = Math.max(0, Math.floor((endTimeMs - now) / 1000));
  
  const h = Math.floor(diffSec / 3600);
  const m = Math.floor((diffSec % 3600) / 60);
  const s = diffSec % 60;
  
  const hStr = String(h).padStart(2, "0");
  const mStr = String(m).padStart(2, "0");
  const sStr = String(s).padStart(2, "0");
  const timeRemainingStr = `${hStr} ч. ${mStr} м. ${sStr} с. (МСК)`;

  const d = new Date(endTimeMs + 3 * 3600 * 1000); // MSK timezone (UTC+3)
  const daysOfWeek = ["воскресенье", "понедельник", "вторник", "среда", "четверг", "пятница", "суббота"];
  const monthsGenitive = [
    "января", "февраля", "марта", "апреля", "мая", "июня",
    "июля", "августа", "сентября", "октября", "ноября", "декабря"
  ];
  
  const dayName = daysOfWeek[d.getUTCDay()];
  const dayNum = d.getUTCDate();
  const monthName = monthsGenitive[d.getUTCMonth()];
  const yearNum = d.getUTCFullYear();

  const dateStr = `${dayName}, ${dayNum} ${monthName}, ${yearNum} года`;

  return { timeRemainingStr, dateStr };
}

// Load Auction State on Boot
async function initNftAuctionState() {
  try {
    const doc = await firestoreDb.collection("system").doc("nft_auction").get();
    if (doc.exists) {
      const data = doc.data() as any;
      if (data && data.isActive && data.endTimeMs > Date.now()) {
        nftAuctionState = data;
        console.log("[NFT AUCTION] Restored active auction for", nftAuctionState.nftName);
      }
    }
  } catch (e) {}
}
setTimeout(() => { initNftAuctionState().catch(() => {}); }, 3000);

// Auction Ticker & Scheduler (10:00, 16:00, 22:00 MSK for 4 hours)
setInterval(async () => {
  try {
    const nowMs = Date.now();

    // Check if current auction ended
    if (nftAuctionState.isActive && nowMs >= nftAuctionState.endTimeMs) {
      nftAuctionState.isActive = false;
      const winnerId = nftAuctionState.highestBidderId;
      const winnerName = nftAuctionState.highestBidderName;
      const wonNftId = nftAuctionState.nftId;

      if (winnerId && winnerName) {
        const winnerUser = await getOrCreateUser(winnerId);
        winnerUser.nfts = winnerUser.nfts || {};
        winnerUser.nfts[wonNftId] = (winnerUser.nfts[wonNftId] || 0) + 1;
        await updateUser(winnerId, { nfts: winnerUser.nfts });

        const endText = `Аукцион NFT окончен. Победитель - [id${winnerId}|${winnerName}]`;
        await sendVkMessage(process.env.VK_TOKEN || "", 2000000046, endText);
      } else {
        const endText = `Аукцион NFT окончен. Ставок не было.`;
        await sendVkMessage(process.env.VK_TOKEN || "", 2000000046, endText);
      }

      await firestoreDb.collection("system").doc("nft_auction").set(nftAuctionState);
      return;
    }

    // Check if new auction should start
    if (!nftAuctionState.isActive) {
      const mskDate = new Date(nowMs + 3 * 3600 * 1000);
      const mskH = mskDate.getUTCHours();
      const mskM = mskDate.getUTCMinutes();

      // Check start windows: 10:00, 16:00, 22:00
      const isSlot = (mskH === 10 || mskH === 16 || mskH === 22) && mskM < 15;
      if (isSlot) {
        const sampleGift = await getRandomNftGiftInfo();
        const basePrice = getNftBasePrice(sampleGift.rarityName);

        nftAuctionState = {
          isActive: true,
          nftId: sampleGift.id,
          nftName: sampleGift.name,
          rarityName: sampleGift.rarityName,
          initialPrice: basePrice,
          currentBid: basePrice,
          highestBidderId: null,
          highestBidderName: null,
          startTimeMs: nowMs,
          endTimeMs: nowMs + 4 * 3600 * 1000
        };

        await firestoreDb.collection("system").doc("nft_auction").set(nftAuctionState);

        const announceText = `...::NFT AUCTION STARTED::...

` +
          `| NFT: ${sampleGift.name}
` +
          `| Первоначальная стоимость: ${formatNumberDots(basePrice)}$
` +
          `| Длительность: 4 часа`;
        await sendVkMessage(process.env.VK_TOKEN || "", 2000000046, announceText);
      }
    }
  } catch (e) {}
}, 15000);

