function buildSystemResponseData(sysKey: string, isOn: boolean, modId: number, modFullName: string) {
  const cfg = SYSTEM_CONFIGS[sysKey];
  const actionStr = isOn ? "включена" : "выключена";
  const modLabel = isOn ? "включил" : "выключил";
  
  // Specific wording for some systems as per user request
  let sysName = cfg.name;
  if (sysKey === "leave") sysName = "Исключение при выходе";
  if (sysKey === "invite") sysName = "Приглашение Модераторами";
  if (sysKey === "group") sysName = "Анти Группы";
  if (sysKey === "tegall") sysName = "Анти Тег Всех";
  if (sysKey === "antiad") sysName = "Анти Реклама";

  const text = `Система «${sysName}» была ${actionStr} ${formatModeratorMention(modId)}.`;
  
  const btnLabel = isOn ? "Выключить" : "Включить";
  const btnColor = isOn ? "negative" : "positive";
  const keyboard = {
    inline: true,
    buttons: [
      [
        { action: { type: "callback", label: btnLabel, payload: JSON.stringify({ cmd: `sys_toggle_${cfg.key}`, authorId: modId }) }, color: btnColor }
      ]
    ]
  };
  return { text, keyboard };
}

async function synthesizeEdgeChunk(text: string): Promise<Buffer> {
  const tts = new MsEdgeTTS();
  await tts.setMetadata("ru-RU-DmitryNeural", OUTPUT_FORMAT.AUDIO_24KHZ_48KBITRATE_MONO_MP3);
  const { audioStream } = tts.toStream(text);
  return new Promise<Buffer>((resolve, reject) => {
    const chunks: Buffer[] = [];
    const timeout = setTimeout(() => {
      reject(new Error("TTS timeout"));
    }, 7000);
    audioStream.on("data", (chunk: Buffer) => chunks.push(chunk));
    audioStream.on("end", () => {
      clearTimeout(timeout);
      resolve(Buffer.concat(chunks));
    });
    audioStream.on("error", (err: any) => {
      clearTimeout(timeout);
      reject(err);
    });
  });
}

function splitTextIntoSpeechChunks(text: string, maxLen = 220): string[] {
  const words = text.split(/\s+/);
  const chunks: string[] = [];
  let current = "";
  for (const w of words) {
    if ((current + " " + w).trim().length > maxLen && current.length > 0) {
      chunks.push(current.trim());
      current = w;
    } else {
      current = current ? current + " " + w : w;
    }
  }
  if (current.trim()) chunks.push(current.trim());
  return chunks;
}

async function generateRussianSpeechBuffer(text: string): Promise<Buffer> {
  const clean = text.slice(0, 800).trim();
  try {
    if (clean.length <= 220) {
      return await synthesizeEdgeChunk(clean);
    }
    const chunks = splitTextIntoSpeechChunks(clean, 220);
    const results = await Promise.all(chunks.slice(0, 4).map(c => synthesizeEdgeChunk(c)));
    return Buffer.concat(results);
  } catch (e) {
    // Fallback to fast Google Translate TTS in case of any timeout or network issue
    try {
      const chunks = splitTextIntoSpeechChunks(clean, 150);
      const googleResults = await Promise.all(chunks.slice(0, 6).map(async (chunk) => {
        const ttsUrl = `https://translate.google.com/translate_tts?ie=UTF-8&q=${encodeURIComponent(chunk)}&tl=ru&client=tw-ob`;
        const res = await axios.get(ttsUrl, {
          responseType: "arraybuffer",
          headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" },
          timeout: 4000
        });
        return Buffer.from(res.data);
      }));
      return Buffer.concat(googleResults);
    } catch (err) {
      const ttsUrl = `https://translate.google.com/translate_tts?ie=UTF-8&q=${encodeURIComponent(clean.slice(0, 200))}&tl=ru&client=tw-ob`;
      const ttsRes = await axios.get(ttsUrl, {
        responseType: "arraybuffer",
        headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" }
      });
      return Buffer.from(ttsRes.data);
    }
  }
}

const eventAnsweredMap = new LRUCache<string, boolean>({ max: 10000, ttl: 1000 * 60 });

async function sendVkToast(vkToken: string, eventId: string, userId: number, peerId: number, text: string) {
  if (!eventId) return;
  if (eventAnsweredMap.has(eventId)) return;
  eventAnsweredMap.set(eventId, true);
  return await importedSendVkToast(vkToken, eventId, userId, peerId, text);
}

async function answerVkEvent(vkToken: string, eventId: string, userId: number, peerId: number, eventData?: any) {
  if (!eventId) return;
  if (eventAnsweredMap.has(eventId)) return;
  eventAnsweredMap.set(eventId, true);
  return await importedAnswerVkEvent(vkToken, eventId, userId, peerId, eventData);
}

async function checkIsUserAllowedDm(targetUserId: number): Promise<boolean> {
  if (targetUserId <= 0) return true;
  try {
    const res = await axios.get("https://api.vk.com/method/messages.isMessagesFromGroupAllowed", {
      params: {
        access_token: VK_TOKEN,
        v: "5.131",
        group_id: 239281784,
        user_id: targetUserId
      },
      timeout: 3000
    });
    return res.data?.response?.is_allowed === 1;
  } catch (e) {
    return false;
  }
}

