const containsBadWord = (text: string) => {
  if (!text) return false;
  const rawLower = text.toLowerCase().replace(/[^а-яa-z0-9ё\s]/g, " ");
  const words = rawLower.split(/\s+/).filter(Boolean);

  const isWhitelisted = (token: string) => {
    return token.startsWith("модератор") || token.startsWith("модер") || token.startsWith("модераци") || token === "модера";
  };

  const filteredWords = words.filter(w => !isWhitelisted(w));
  if (filteredWords.length === 0) return false;

  for (const token of filteredWords) {
    if (EXTENDED_BAD_WORDS_SET.has(token)) return true;
    if (token.includes("говноед") || token.includes("говноед") || token.includes("govnoed") || token.includes("gavnoed")) return true;
  }

  const normalized = normalizeTextForBanCheck(filteredWords.join(" "));
  const rawCombined = filteredWords.join("");

  if (rawCombined.includes("говноед") || normalized.includes("говноед") || rawCombined.includes("govnoed")) return true;

  const allBad = [...badWordsList, ...dynamicBanWords].filter(w => !isWhitelisted(w.toLowerCase()));
  for (const w of allBad) {
    if (!w) continue;
    const wRaw = w.toLowerCase().replace(/[^а-яa-z0-9ё]/g, "");
    if (!wRaw || isWhitelisted(wRaw)) continue;
    const wNorm = normalizeTextForBanCheck(w);

    if (wRaw.length <= 4 || shortBadWords.has(wRaw) || shortBadWords.has(w.toLowerCase())) {
      for (const token of filteredWords) {
        if (token === wRaw || (token.startsWith(wRaw) && token.length <= wRaw.length + 2)) {
          return true;
        }
      }
    } else {
      if (rawCombined.includes(wRaw)) return true;
      if (wNorm && normalized.includes(wNorm)) return true;
    }
  }
  return false;
};

const maskBadWords = (text: string): string => {
  if (!text) return "";
  let result = text;
  const profanityList = [
    "хуесос", "хуисос", "пидорас", "пидор", "пидар", "ебаный", "ебанный", "ебаная", "ебаное", "ебаные",
    "ебать", "ебан", "ебуч", "ебло", "еблан", "еблище", "заебал", "выебал", "ебись", "ебал", "ёбну", "ебну",
    "бля", "блят", "бляд", "блядина", "блядь", "бляди", "блядство",
    "хуй", "хуи", "хуя", "хуе", "хуила", "хуёк", "хуек", "хуйня", "хуище", "хуем", "хую", "нахуй", "похуй", "дохуя", "нихуя", "хуевый",
    "пизд", "пизда", "пиздец", "пиздобол", "пиздит", "пиздить", "пизду", "пиздой", "пизденка", "пиздос", "распиздяй",
    "залуп", "залупа", "сука", "сучка", "сучара", "суки", "гондон", "гандон", "шлюх", "шлюха", "шлюхи", "мразь", "мрази", "мразота",
    "мудак", "мудило", "fuck", "bitch", "cunt", "dick", "pussy", "cock", "asshole", "bastard", "motherfucker"
  ];
  for (const prof of profanityList) {
    const reg = new RegExp(prof, "gi");
    result = result.replace(reg, (match) => "#".repeat(match.length));
  }
  return result;
};

function fmtD2(ts?: number | string | null): string {
  if (!ts) return "отсутствует";
  return formatMskDetailedDate(ts, "отсутствует");
}

async function buildAllBansReport(targetId: number): Promise<string> {
  const tUser = await getOrCreateUser(targetId);
  const targetMention = formatUserMention(targetId, "пользователя", "gen");

  const getModStr = async (mId?: number) => {
    if (!mId || mId <= 0) return "[id1|Администратор]";
    const mUser = await getOrCreateUser(mId);
    const mName = mUser.fullName || mUser.nick || (await fetchVkFullName(mId)) || "Администратор";
    return `${formatUserMention(mId, String(mName), "nom")}`;
  };

  const now = Date.now();
  if (tUser.gban && tUser.gbanExpiresAt && tUser.gbanExpiresAt > 0 && now > tUser.gbanExpiresAt) {
    await updateUser(targetId, { gban: false, gbanExpiresAt: 0 });
    tUser.gban = false;
  }

  if (tUser.blacklisted && tUser.blackExpiresAt && tUser.blackExpiresAt > 0 && now > tUser.blackExpiresAt) {
    await updateUser(targetId, { blacklisted: false, blackExpiresAt: 0 });
    tUser.blacklisted = false;
  }

  let gbanSection = "Нет";
  if (tUser.gban) {
    const gMod = await getModStr(tUser.gbanBy);
    gbanSection =
      `| Модератор — ${gMod}
` +
      `| Причина: ${tUser.gbanReason || "без причины"}
` +
      `| Дата выдачи: ${fmtD(tUser.gbanDate)}
` +
      `| Дата окончания: ${fmtD(tUser.gbanExpiresAt)}`;
  }

  let blackSection = "Нет";
  if (tUser.blacklisted) {
    const bMod = await getModStr(tUser.blackBy || tUser.blacklistedBy);
    blackSection =
      `| Модератор — ${bMod}
` +
      `| Причина: ${tUser.blackReason || tUser.blacklistedReason || "без причины"}
` +
      `| Дата выдачи: ${fmtD(tUser.blackDate || tUser.blacklistedDate)}
` +
      `| Дата окончания: ${fmtD(tUser.blackExpiresAt || tUser.blacklistedExpiresAt)}`;
  }

  // Chat & Grid Bans
  const chatBans = tUser.chatBans || {};
  const activeChatBans: { cId: string; info: any }[] = [];
  let chatBansChanged = false;
  for (const cId of Object.keys(chatBans)) {
    const bInfo = chatBans[cId];
    if (!bInfo) continue;
    if (bInfo.expiresAt && bInfo.expiresAt > 0 && now > bInfo.expiresAt) {
      delete chatBans[cId];
      chatBansChanged = true;
      continue;
    }
    activeChatBans.push({ cId, info: bInfo });
  }
  if (chatBansChanged) {
    await updateUser(targetId, { chatBans });
  }

  // Include bans from grids into activeChatBans for each chat in the grid
  try {
    const gridSnap = await firestoreDb.collection("grids").where("bans", "array-contains", targetId).get();
    for (const doc of gridSnap.docs) {
      const gData = doc.data();
      const chats = gData.chats || [];
      const detail = gData.banDetails?.[targetId] || {};
      for (const pid of chats) {
        const cIdStr = String(pid);
        if (!activeChatBans.some(b => b.cId === cIdStr)) {
          activeChatBans.push({
            cId: cIdStr,
            info: {
              by: detail.by,
              date: detail.date || gData.createdAt || Date.now(),
              reason: detail.reason || "без причины",
              expiresAt: 0
            }
          });
        }
      }
    }
  } catch (e) {
    console.error("Error querying grid bans in buildAllBansReport:", e);
  }

  let chatBansDetails = "Нет";
  if (activeChatBans.length > 0) {
    const lines: string[] = [];
    let idx = 1;
    for (const item of activeChatBans) {
      const cData = await getOrCreateChat(Number(item.cId));
      let chatTitle = cData.title || `Беседа #${item.cId}`;
      if (containsBadWord(chatTitle)) {
        chatTitle = "####";
      }
      const mStr = await getModStr(item.info.by);
      lines.push(
        `${idx}) ${chatTitle}
` +
        `| Модератор — ${mStr}
` +
        `| Причина: ${item.info.reason || "без причины"}
` +
        `| Дата выдачи: ${fmtD(item.info.date)}
` +
        `| Дата окончания: ${fmtD(item.info.expiresAt)}`
      );
      idx++;
    }
    chatBansDetails = lines.join("\n");
  }

  return `...::Все блокировки ${targetMention}::...

` +
    `| Активная глобальная блокировка во всех беседах:
` +
    `${gbanSection}

` +
    `| Активный чёрный список чат-менеджера:
` +
    `${blackSection}

` +
    `| Кол-во блокировок в беседах всего: ${activeChatBans.length}
` +
    `| Блокировки в беседах:

` +
    `${chatBansDetails}`;
}

const getRawArgText = (rawMessageText: string) => {
  if (!rawMessageText) return "";
  let trimmed = rawMessageText.trim();
  const match = trimmed.match(/^([\/+!\.,]?[\S]+)[\s]+([\s\S]*)$/);
  if (match && match[2]) {
    return match[2];
  }
  return "";
};


function pluralizeUsers(n: number): string {
  const abs = Math.abs(Math.floor(n));
  const mod10 = abs % 10;
  const mod100 = abs % 100;
  if (mod100 >= 11 && mod100 <= 19) return "пользователей";
  if (mod10 === 1) return "пользователь";
  if (mod10 >= 2 && mod10 <= 4) return "пользователя";
  return "пользователей";
}

function formatDateTimeWithDeclension(ts?: number | string | null): string {
  if (!ts) return "Неизвестно";
  const num = typeof ts === "string" ? parseInt(ts, 10) : ts;
  if (!num || isNaN(num) || num <= 0) return "Неизвестно";
  const d = new Date(num + 3 * 3600000); // Moscow time UTC+3
  const daysOfWeek = ["Воскресенье", "Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота"];
  const monthsGen = [
    "января", "февраля", "марта", "апреля", "мая", "июня",
    "июля", "августа", "сентября", "октября", "ноября", "декабря"
  ];
  const pad = (n: number) => String(n).padStart(2, "0");
  const dayName = daysOfWeek[d.getUTCDay()] || "Понедельник";
  const dd = pad(d.getUTCDate());
  const monthName = monthsGen[d.getUTCMonth()] || "января";
  const year = d.getUTCFullYear();
  const hh = pad(d.getUTCHours());
  const mm = pad(d.getUTCMinutes());
  const ss = pad(d.getUTCSeconds());
  return `${dayName}, ${dd} ${monthName} ${year} года в ${hh}:${mm}:${ss}`;
}

function formatMskDetailedDate(ms?: number | string | null, defaultText: string = "Навсегда"): string {
  if (!ms) return defaultText;
  const num = typeof ms === "string" ? parseInt(ms, 10) : ms;
  if (!num || isNaN(num) || num <= 0) return defaultText;
  
  const d = new Date(num + 3 * 3600000);
  
  const hh = d.getUTCHours();
  const mm = d.getUTCMinutes();
  const ss = d.getUTCSeconds();
  
  const day = d.getUTCDate();
  const month = d.getUTCMonth();
  const year = d.getUTCFullYear();
  const dayIdx = d.getUTCDay();
  
  const dayName = ["Воскресенье", "Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота"][dayIdx];
  const monthName = ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"][month];
  
  const pad = (n: number) => String(n).padStart(2, "0");
  
  return `${pad(hh)} ч. ${pad(mm)} м. ${pad(ss)} с. (МСК) | ${dayName}, ${day} ${monthName} ${year} года`;
}

const fmtD = (ms?: number) => formatMskDetailedDate(ms);

// ⚡ ULTRA-FAST MSK DATE ENGINE (Sub-microsecond resolution)
let cachedMskDateStr = "";
let cachedMskDateExpiry = 0;

const getMskDate = (ms: number = Date.now()) => {
  return new Date(ms + (new Date().getTimezoneOffset() * 60 * 1000) + (3 * 3600 * 1000));
};

const getMskDateStr = (ms: number = Date.now()) => {
  const now = Date.now();
  if (ms === now && now < cachedMskDateExpiry) return cachedMskDateStr;
  
  const d = getMskDate(ms);
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  const res = `${year}-${month}-${day}`;
  
  if (ms === now) {
    cachedMskDateStr = res;
    cachedMskDateExpiry = now + 1000;
  }
  return res;
};

const formatDateRstats = (ms?: number) => {
  if (!ms) ms = Date.now();
  const d = new Date(ms + (new Date().getTimezoneOffset() * 60 * 1000) + (3 * 3600 * 1000));
  const day = String(d.getDate()).padStart(2, "0");
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const year = d.getFullYear();
  const hours = String(d.getHours()).padStart(2, "0");
  const mins = String(d.getMinutes()).padStart(2, "0");
  return `${day}.${month}.${year} ${hours}:${mins}`;
};

const recentLogsMap = new Map<string, number>();

const logToChat10 = async (params: {
  isGame?: boolean;
  userId: number;
  fullName: string;
  targetId?: number;
  targetName?: string;
  bet?: string | number;
  duration?: string;
  reason?: string;
  action: string;
  cmdName: string;
  msgCmId?: string | number;
  peerId?: number;
  chatTitle?: string;
  forwardPeerId?: number;
  forwardCmId?: number;
  forwardMsgId?: number;
}) => {
  if (!params.userId || params.userId <= 0) return;

  const rawCmdClean = (params.cmdName || "cmd").replace(/^[\/+!\.,]/, "").toLowerCase();
  const actionClean = (params.action || "").trim();
  const targetClean = params.targetId || 0;
  const reasonClean = (params.reason || "").trim();
  const betClean = params.bet !== undefined && params.bet !== null ? String(params.bet).trim() : "";

  const logDedupKey = params.msgCmId
    ? `cm_${params.msgCmId}_${rawCmdClean}`
    : `${params.userId}_${rawCmdClean}_${params.forwardCmId || params.forwardMsgId || Date.now()}`;

  const now = Date.now();
  const lastLoggedAt = recentLogsMap.get(logDedupKey);

  if (lastLoggedAt && now - lastLoggedAt < 1000) {
    return;
  }
  recentLogsMap.set(logDedupKey, now);

  if (recentLogsMap.size > 5000) {
    const cutoff = now - 60000;
    for (const [k, v] of recentLogsMap.entries()) {
      if (v < cutoff) recentLogsMap.delete(k);
    }
  }

  const userLink = `${formatUserMention(params.userId, String(params.fullName), "nom")}`;

  let targetFullName = params.targetName;
  if (!targetFullName && params.targetId && params.targetId > 0) {
    const tu = await getOrCreateUser(params.targetId);
    targetFullName = tu.fullName || tu.nick || (await fetchVkFullName(params.targetId)) || `User${params.targetId}`;
  }

  const targetLink = params.targetId && params.targetId > 0 && targetFullName
    ? `${formatUserMention(params.targetId, String(targetFullName), "nom")}`
    : "None";

  const d = new Date(now + (3 * 3600 * 1000));
  const timeStr = `${String(d.getUTCHours()).padStart(2, "0")}:${String(d.getUTCMinutes()).padStart(2, "0")}:${String(d.getUTCSeconds()).padStart(2, "0")}`;
  const dateStr = `${String(d.getUTCDate()).padStart(2, "0")}.${String(d.getUTCMonth() + 1).padStart(2, "0")}.${d.getUTCFullYear()}`;
  const datePrefix = `[${timeStr} | ${dateStr}]`;

  const chatInfo = params.peerId ? `${params.chatTitle || "ЛС"} (id беседы: ${params.peerId})` : "Неизвестная беседа (ЛС)";

  let actionExt = maskBadWords(params.action);
  if (params.bet !== undefined && params.bet !== null && String(params.bet).trim() !== "") {
    actionExt += ` | Ставка: ${params.bet}`;
  }
  if (params.duration && String(params.duration).trim() !== "") {
    actionExt += ` | Срок: ${params.duration}`;
  }
  if (params.reason && String(params.reason).trim() !== "") {
    actionExt += ` | Причина: ${maskBadWords(params.reason)}`;
  }

  const targetTag = params.targetId && params.targetId > 0 ? ` #id${params.targetId}` : "";
  const msg = `${datePrefix} ${userLink} -> ${targetLink} | ${actionExt} | ${chatInfo} | #id${params.userId}${targetTag} #${rawCmdClean}`;

  const fwdPeerId = params.forwardPeerId || (params.peerId && params.peerId > 0 ? params.peerId : undefined);
  let fwdCmId = params.forwardCmId ? Number(params.forwardCmId) : 0;
  if (!fwdCmId && params.msgCmId) {
    const parts = String(params.msgCmId).split("_");
    if (parts.length >= 2 && !isNaN(Number(parts[1]))) {
      fwdCmId = Number(parts[1]);
    } else if (!isNaN(Number(params.msgCmId))) {
      fwdCmId = Number(params.msgCmId);
    }
  }

  let forwardParam: string | undefined = undefined;
  if (fwdPeerId && fwdCmId > 0) {
    forwardParam = JSON.stringify({
      peer_id: fwdPeerId,
      conversation_message_ids: [fwdCmId],
      is_reply: false
    });
  } else if (fwdPeerId && params.forwardMsgId && params.forwardMsgId > 0) {
    forwardParam = JSON.stringify({
      peer_id: fwdPeerId,
      message_ids: [params.forwardMsgId],
      is_reply: false
    });
  } else if (params.forwardMsgId && params.forwardMsgId > 0) {
    forwardParam = JSON.stringify({
      message_ids: [params.forwardMsgId],
      is_reply: false
    });
  }

  sendVkMessage(VK_TOKEN, 2000000010, msg, {
    dedup_key: logDedupKey,
    ...(forwardParam ? { forward: forwardParam } : {})
  }).catch(() => {
    // If sending with forward fails for any reason, send without forward as fallback
    if (forwardParam) {
      sendVkMessage(VK_TOKEN, 2000000010, msg, { dedup_key: `${logDedupKey}_fallback` }).catch(() => {});
    }
  });
};

const logAdminAction = logToChat10;

const logButtonAction = async (params: {
  userId: number;
  fullName?: string;
  targetId?: number;
  targetName?: string;
  action: string;
  buttonName: string;
  eventId?: string;
  peerId?: number;
  chatTitle?: string;
}) => {
  if (!params.userId || params.userId <= 0) return;

  const cleanBtn = (params.buttonName || "button").replace(/^[\/+!\.,#]/, "").toLowerCase().trim() || "button";

  const logDedupKey = params.eventId
    ? `btn_evt_${params.eventId}`
    : `btn_${params.userId}_${cleanBtn}_${params.targetId || 0}`;

  const now = Date.now();
  const lastLoggedAt = recentLogsMap.get(logDedupKey);
  if (lastLoggedAt && now - lastLoggedAt < 10000) return;
  recentLogsMap.set(logDedupKey, now);

  let userFullName = params.fullName;
  if (!userFullName) {
    const u = await getOrCreateUser(params.userId);
    userFullName = u.fullName || u.nick || (await fetchVkFullName(params.userId)) || `User${params.userId}`;
  }

  const userLink = `${formatUserMention(params.userId, String(userFullName), "nom")}`;

  let targetLink = "None";
  if (params.targetId && params.targetId > 0 && params.targetId !== params.userId) {
    let targetFullName = params.targetName;
    if (!targetFullName) {
      const tu = await getOrCreateUser(params.targetId);
      targetFullName = tu.fullName || tu.nick || (await fetchVkFullName(params.targetId)) || `User${params.targetId}`;
    }
    if (targetFullName) {
      targetLink = `${formatUserMention(params.targetId, String(targetFullName), "nom")}`;
    }
  }

  const d = new Date(now + (3 * 3600 * 1000));
  const timeStr = `${String(d.getUTCHours()).padStart(2, "0")}:${String(d.getUTCMinutes()).padStart(2, "0")}:${String(d.getUTCSeconds()).padStart(2, "0")}`;
  const dateStr = `${String(d.getUTCDate()).padStart(2, "0")}.${String(d.getUTCMonth() + 1).padStart(2, "0")}.${d.getUTCFullYear()}`;
  const datePrefix = `[${timeStr} | ${dateStr}]`;

  const chatInfo = params.peerId ? `${params.chatTitle || "ЛС"} (id беседы: ${params.peerId})` : "Неизвестная беседа (ЛС)";
  const maskedAction = maskBadWords(params.action || "Нажал кнопку");
  const targetTag = params.targetId && params.targetId > 0 ? ` #id${params.targetId}` : "";
  const msg = `${datePrefix} ${userLink} -> ${targetLink} | ${maskedAction} | ${chatInfo} | #id${params.userId}${targetTag} #${cleanBtn}`;

  sendVkMessage(VK_TOKEN, 2000000010, msg, { dedup_key: logDedupKey }).catch(() => {});
};

