  // Title: ...::Статистика Беседы::...
  ctx.fillStyle = "rgba(255, 255, 255, 0.85)";
  ctx.font = "bold 16px NotoSans, sans-serif";
  ctx.fillText("...::Статистика Беседы::...", leftX, currentY);
  
  currentY += 45;

  // Name
