// Blackjack Helpers
interface BJCard {
  suit: string;
  val: string;
  num: number;
  str: string;
}

function createBJDeck(): BJCard[] {
  const suits = ["♠️", "♥️", "♦️", "♣️"];
  const values = [
    { val: "2", num: 2 }, { val: "3", num: 3 }, { val: "4", num: 4 },
    { val: "5", num: 5 }, { val: "6", num: 6 }, { val: "7", num: 7 },
    { val: "8", num: 8 }, { val: "9", num: 9 }, { val: "10", num: 10 },
    { val: "J", num: 10 }, { val: "Q", num: 10 }, { val: "K", num: 10 },
    { val: "A", num: 11 }
  ];
  const deck: BJCard[] = [];
  for (const s of suits) {
    for (const v of values) {
      deck.push({ suit: s, val: v.val, num: v.num, str: `${v.val}${s}` });
    }
  }
  // Shuffle
  for (let i = deck.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  return deck;
}

function calculateBJScore(cards: BJCard[]): number {
  let score = 0;
  let aces = 0;
  for (const c of cards) {
    score += c.num;
    if (c.val === "A") aces++;
  }
  while (score > 21 && aces > 0) {
    score -= 10;
    aces--;
  }
  return score;
}

function drawBJCardOnCanvas(ctx: any, x: number, y: number, w: number, h: number, card: BJCard) {
  ctx.save();
  ctx.shadowColor = "rgba(0, 0, 0, 0.4)";
  ctx.shadowBlur = 8;
  ctx.shadowOffsetX = 3;
  ctx.shadowOffsetY = 4;

  ctx.fillStyle = "#ffffff";
  if (typeof ctx.roundRect === "function") {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, 8);
    ctx.fill();
  } else {
    ctx.fillRect(x, y, w, h);
  }
  ctx.restore();

  ctx.strokeStyle = "#d1d5db";
  ctx.lineWidth = 2;
  if (typeof ctx.roundRect === "function") {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, 8);
    ctx.stroke();
  } else {
    ctx.strokeRect(x, y, w, h);
  }

  const isRed = card.suit === "♥️" || card.suit === "♦️";
  ctx.fillStyle = isRed ? "#dc2626" : "#111827";
  
  ctx.font = "bold 16px sans-serif";
  ctx.textAlign = "left";
  ctx.textBaseline = "top";
  ctx.fillText(card.val, x + 6, y + 6);
  ctx.font = "14px sans-serif";
  ctx.fillText(card.suit, x + 6, y + 24);

  ctx.font = "26px sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(card.suit, x + w / 2, y + h / 2);

  ctx.font = "bold 16px sans-serif";
  ctx.textAlign = "right";
  ctx.textBaseline = "bottom";
  ctx.fillText(card.val, x + w - 6, y + h - 6);
}

function generateBlackjackImageBuffer(playerName: string, dealerCards: BJCard[], playerCards: BJCard[], outcomeText?: string): Buffer | null {
  try {
    if (!createCanvas) return null;
    const width = 640;
    const height = 400;
    const canvas = createCanvas(width, height);
    const ctx = canvas.getContext("2d");

    const grad = ctx.createRadialGradient(width / 2, height / 2, 50, width / 2, height / 2, width * 0.7);
    grad.addColorStop(0, "#1b6d3f");
    grad.addColorStop(1, "#0d3b20");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);

    ctx.strokeStyle = "#082815";
    ctx.lineWidth = 14;
    ctx.strokeRect(0, 0, width, height);

    ctx.strokeStyle = "#d4af37";
    ctx.lineWidth = 2;
    ctx.strokeRect(14, 14, width - 28, height - 28);

    ctx.fillStyle = "#ffffff";
    ctx.font = "bold 16px sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    const dScore = calculateBJScore(dealerCards);
    ctx.fillText(`ДИЛЕР (Сумма: ${dScore})`, 30, 26);

    const cardW = 60;
    const cardH = 88;
    const cardSpacing = 14;

    dealerCards.forEach((c, idx) => {
      drawBJCardOnCanvas(ctx, 30 + idx * (cardW + cardSpacing), 50, cardW, cardH, c);
    });

    if (outcomeText) {
      ctx.fillStyle = "rgba(0, 0, 0, 0.65)";
      ctx.fillRect(16, 155, width - 32, 44);
      ctx.strokeStyle = "#d4af37";
      ctx.lineWidth = 1;
      ctx.strokeRect(16, 155, width - 32, 44);

      ctx.fillStyle = "#fef08a";
      ctx.font = "bold 17px sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(outcomeText, width / 2, 177);
    }

    ctx.fillStyle = "#ffffff";
    ctx.font = "bold 16px sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    const cleanPName = (playerName || "Игрок").slice(0, 22);
    const pScore = calculateBJScore(playerCards);
    ctx.fillText(`ИГРОК: ${cleanPName.toUpperCase()} (Сумма: ${pScore})`, 30, 215);

    playerCards.forEach((c, idx) => {
      drawBJCardOnCanvas(ctx, 30 + idx * (cardW + cardSpacing), 240, cardW, cardH, c);
    });

    return canvas.toBuffer("image/jpeg", { quality: 0.9 });
  } catch (err) {
    console.error("Error generating blackjack image:", err);
    return null;
  }
}

async function getBlackjackPhotoAttachment(peerId: number, playerName: string, dealerCards: BJCard[], playerCards: BJCard[], outcomeText?: string): Promise<string | null> {
  try {
    const buf = generateBlackjackImageBuffer(playerName, dealerCards, playerCards, outcomeText);
    if (!buf) return null;
    const up = await uploadPhoto(peerId, buf);
    if (up && up.attachment) {
      return up.attachment;
    }
  } catch (e) {
    console.error("Error uploading blackjack photo:", e);
  }
  return null;
}

// -------------------------------------------------------------
// Level, Job, and Quest Systems
// -------------------------------------------------------------
function isUserPremium(u: any): boolean {
  if (!u) return false;
  const now = Date.now();
  return Boolean((u.vipExpires && u.vipExpires > now) || u.isVip || (u.role && u.role >= 10));
}

function getWorkCooldownSec(user: any): number {
  return isUserPremium(user) ? 900 : 1800; // 15 мин для Premium/VIP, 30 мин для остальных
}

function getExpForLevel(lvl: number): number {
  if (lvl <= 1) return 1000;
  return Math.floor(1000 * Math.pow(lvl, 2.2));
}

function calculateLevelFromExp(exp: number): { level: number; currentExp: number; expForNext: number; totalExp: number } {
  let lvl = 1;
  let accumulated = 0;
  while (true) {
    const required = getExpForLevel(lvl);
    if (exp < accumulated + required) {
      return {
        level: lvl,
        currentExp: exp - accumulated,
        expForNext: required,
        totalExp: exp
      };
    }
    accumulated += required;
    lvl++;
  }
}

