function hashStringToSeed(str: string): number {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash |= 0;
  }
  return Math.abs(hash);
}

function getUserQuestsForToday(user: any): { date: string; quests: { id: string; progress: number; completed: boolean; claimed: boolean }[] } {
  if (!user) return { date: getMskDateStr(), quests: [] };
  const todayStr = getMskDateStr();
  const isPrem = isUserPremium(user);
  const targetQuestCount = isPrem ? 5 : 3;

  let needsSave = false;

  if (user.dailyQuestsState && user.dailyQuestsState.date === todayStr && Array.isArray(user.dailyQuestsState.quests)) {
    const existing = user.dailyQuestsState.quests;
    if (existing.length < targetQuestCount) {
      // If user got premium today, expand quests up to 5 without resetting progress
      const existingIds = new Set(existing.map((q: any) => q.id));
      const available = DAILY_QUESTS_POOL.filter(p => !existingIds.has(p.id));
      let seed = hashStringToSeed(`${user.userId || 0}_${todayStr}_extra`);
      while (existing.length < targetQuestCount && available.length > 0) {
        const idx = seed % available.length;
        const picked = available.splice(idx, 1)[0];
        existing.push({
          id: picked.id,
          progress: 0,
          completed: false,
          claimed: false
        });
        seed = (seed * 9301 + 49297) % 233280;
      }
      user.dailyQuestsState.quests = existing;
      needsSave = true;
    }
    if (needsSave && user.userId) {
      updateUser(user.userId, { dailyQuestsState: user.dailyQuestsState }).catch(() => {});
    }
    return user.dailyQuestsState;
  }

  // Generate diverse deterministic randomized quests for this user & day
  const poolCopy = [...DAILY_QUESTS_POOL];
  let seed = hashStringToSeed(`${user.userId || 0}_${todayStr}`);
  const selected: { id: string; progress: number; completed: boolean; claimed: boolean }[] = [];

  for (let i = 0; i < targetQuestCount && poolCopy.length > 0; i++) {
    const idx = seed % poolCopy.length;
    const picked = poolCopy.splice(idx, 1)[0];
    selected.push({
      id: picked.id,
      progress: 0,
      completed: false,
      claimed: false
    });
    seed = (seed * 1664525 + 1013904223) % 4294967296;
  }

  const newState = {
    date: todayStr,
    quests: selected
  };
  user.dailyQuestsState = newState;
  if (user.userId) {
    updateUser(user.userId, { dailyQuestsState: newState }).catch(() => {});
  }
  return newState;
}

async function triggerQuestProgress(userId: number, type: "work" | "msg" | "beer" | "game" | "biz" | "roulette" | "bj" | "coin", amount: number = 1) {
  try {
    if (!userId || isNaN(userId)) return;
    const user = await getOrCreateUser(userId);
    if (!user) return;
    const questsState = getUserQuestsForToday(user);
    let changed = false;
    for (const qItem of questsState.quests) {
      if (qItem.completed) continue;
      const def = DAILY_QUESTS_POOL.find(p => p.id === qItem.id);
      if (!def) continue;
      const isMatch = def.type === type || (def.type === "game" && (type === "roulette" || type === "bj" || type === "coin" || type === "game"));
      if (isMatch) {
        qItem.progress = (qItem.progress || 0) + amount;
        if (qItem.progress >= def.targetCount) {
          qItem.progress = def.targetCount;
          qItem.completed = true;
        }
        changed = true;
      }
    }
    if (changed) {
      user.dailyQuestsState = questsState;
      await updateUser(userId, { dailyQuestsState: questsState });
    }
  } catch (e) {
    console.error("Error triggering quest progress:", e);
  }
}

function getJobsCatalogView(user: any, page: number = 1) {
  const userExp = user.totalExp || 0;
  const lvlInfo = calculateLevelFromExp(userExp);
  const pageSize = 5;
  const totalPages = Math.ceil(JOBS_LIST.length / pageSize);
  const curPage = Math.max(1, Math.min(totalPages, page));
  const startIdx = (curPage - 1) * pageSize;
  const pageJobs = JOBS_LIST.slice(startIdx, startIdx + pageSize);

  const curJob = JOBS_LIST.find(j => j.id === user.jobId);
  const curJobStr = curJob ? `${curJob.emoji} ${curJob.title}` : "Безработный";
  const cdSec = getWorkCooldownSec(user);
  const cdMin = Math.floor(cdSec / 60);

  let text = `...::Доступные работы::...

` +
    `| Страница: ${curPage}/${totalPages}
` +
    `| Ваш уровень: ${lvlInfo.level} | Должность: ${curJobStr}
` +
    `| Кулдаун смены: ${cdMin} мин.${isUserPremium(user) ? " (⭐ Premium)" : ""}

`;

  const buttons: any[] = [];

  pageJobs.forEach((j, idx) => {
    const globalIdx = startIdx + idx + 1;
    const isCurrent = user.jobId === j.id;
    const isAvailable = lvlInfo.level >= j.minLevel;
    const statusTag = isCurrent ? " [✅ Ваша работа]" : isAvailable ? " [Доступна]" : ` [🔒 Требуется ${j.minLevel} ур.]`;

    text += `${globalIdx}. ${j.emoji} ${j.title}${statusTag}
` +
      `   • Зарплата: ${j.minSalary.toLocaleString()}$ - ${j.maxSalary.toLocaleString()}$
` +
      `   • Опыт: +${j.expReward} EXP за смену
` +
      `   • ${j.description}

`;

    if (!isCurrent) {
      const shortTitle = j.title.length > 22 ? j.title.substring(0, 20) + "..." : j.title;
      buttons.push([{
        action: {
          type: "callback",
          label: `💼 Устроиться: ${shortTitle}`,
          payload: JSON.stringify({ cmd: "job_apply", jobId: j.id, authorId: user.userId })
        },
        color: isAvailable ? "primary" : "secondary"
      }]);
    }
  });

  const navRow: any[] = [];
  if (curPage > 1) {
    navRow.push({
      action: {
        type: "callback",
        label: "⬅️ Стр. " + (curPage - 1),
        payload: JSON.stringify({ cmd: "jobs_page", page: curPage - 1, authorId: user.userId })
      },
      color: "secondary"
    });
  }
  if (curPage < totalPages) {
    navRow.push({
      action: {
        type: "callback",
        label: "Стр. " + (curPage + 1) + " ➡️",
        payload: JSON.stringify({ cmd: "jobs_page", page: curPage + 1, authorId: user.userId })
      },
      color: "secondary"
    });
  }
  if (user.jobId) {
    navRow.push({
      action: {
        type: "callback",
        label: "Уволиться ❌",
        payload: JSON.stringify({ cmd: "job_quit", authorId: user.userId })
      },
      color: "negative"
    });
  }
  if (navRow.length > 0) {
    buttons.push(navRow);
  }

  text += `💡 Нажмите кнопку под выбранной профессией, чтобы устроиться.
` +
    `👉 Чтобы отработать смену и получить зарплату: /работа`;

  return { text, keyboard: { inline: true, buttons } };
}

function getQuestsView(user: any) {
  const questsState = getUserQuestsForToday(user);
  const isPrem = isUserPremium(user);
  const userMention = formatUserMention(user.userId, "пользователя", "gen");
  let text = `...::Ежедневные квесты ${userMention}::...

`;

  const claimButtons: any[] = [];
  let allCompleted = true;
  let allClaimed = true;

  questsState.quests.forEach((qItem, idx) => {
    const def = DAILY_QUESTS_POOL.find(p => p.id === qItem.id);
    if (!def) return;
    const isDone = qItem.completed;
    const isClaimed = qItem.claimed;
    if (!isDone) allCompleted = false;
    if (!isClaimed) allClaimed = false;

    const statusIcon = isClaimed ? "✅ (Получено)" : isDone ? "✨ (Готово!)" : `⏳ (${qItem.progress}/${def.targetCount})`;

    text += `${idx + 1}. ${def.emoji} ${def.title} ${statusIcon}
` +
      `   • Задание: ${def.description}
` +
      `   • Награда: +${def.moneyReward.toLocaleString()}$ и +${def.expReward} EXP

`;

    if (isDone && !isClaimed) {
      const shortTitle = def.title.length > 22 ? def.title.substring(0, 20) + "..." : def.title;
      claimButtons.push([{
        action: {
          type: "callback",
          label: `🎁 Забрать награду: ${shortTitle}`,
          payload: JSON.stringify({ cmd: "quest_claim", qId: def.id, authorId: user.userId })
        },
        color: "positive"
      }]);
    }
  });

  if (allClaimed) {
    text += `🎉 Все ежедневные квесты выполнены и награды получены!
Возвращайтесь завтра за новыми заданиями.

`;
  } else if (claimButtons.length > 0) {
    text += `👉 Нажмите зелёную кнопку «Забрать награду» под выполненным квестом!

`;
  } else {
    text += `👉 Выполняйте задания, чтобы открыть кнопки получения наград!

`;
  }

  if (!isPrem) {
    text += `⭐ У владельцев Premium доступно 5 квестов в день и КД на работу всего 15 минут!`;
  }

  const keyboard = {
    inline: true,
    buttons: claimButtons
  };

  return { text, keyboard };
}

const vkNameCache = new Map<number, any>();
const processedEventIds = new Set<string>();
const buttonActionCooldownMap = new Map<string, number>();
const inFlightButtonClicks = new Set<string>();

function getEventDeduplicationKeys(event: any): string[] {
  const keys: string[] = [];
  if (!event) return keys;

  const msg = event.object?.message || event.object || event;
  const peerId = msg.peer_id || event.peer_id || event.object?.peer_id || 0;
  const cmId = msg.conversation_message_id || event.conversation_message_id || event.object?.conversation_message_id;
  const msgId = msg.id || event.id || event.object?.id;
  const evtId = event.event_id || event.object?.event_id;

  if (evtId) keys.push(`evt_${evtId}`);
  if (peerId && cmId) keys.push(`cmid_${peerId}_${cmId}`);
  if (msgId && msgId > 0) keys.push(`msgid_${msgId}`);

  return keys;
}

function deduplicateEventGlobally(keys: string | string[], ttlMs: number = 10000): boolean {
  const keyList = Array.isArray(keys) ? keys : [keys];
  if (keyList.length === 0) return false;
  
  const isDuplicate = keyList.some(k => processedEventIds.has(k));
  if (isDuplicate) return true;

  for (const k of keyList) {
    processedEventIds.add(k);
    setTimeout(() => processedEventIds.delete(k), ttlMs);
  }
  return false;
}

async function kickUserFromChat(peerId: number, memberId: number): Promise<boolean> {
  if (peerId <= 2000000000 || !memberId) return false;
  const chatId = peerId - 2000000000;
  try {
    const res = await axios.post("https://api.vk.com/method/messages.removeChatUser", null, {
      params: {
        chat_id: chatId,
        member_id: memberId,
        access_token: VK_TOKEN,
        v: "5.199"
      }
    });
    return res.data && !res.data.error;
  } catch (e) {
    return false;
  }
}

function calculateEffectiveRole(user: any, peerId: number): number {
  if (!user) return 0;
  const userChatRole = (user.chatRoles && (user.chatRoles[peerId] || user.chatRoles[String(peerId)])) || 0;
  return user.role >= 8 ? user.role : Math.max(user.role || 0, userChatRole);
}

async function getNextTicketId(): Promise<number> {
  try {
    const snap = await firestoreDb.collection("tickets").orderBy("id", "desc").limit(1).get();
    if (snap.empty) return 1;
    return (snap.docs[0].data().id || 0) + 1;
  } catch (e) {
    return Date.now();
  }
}

async function deleteRecentUserMessages(peerId: number, targetId: number, count: number = 5) {
  try {
    await deleteMessagesForUser(peerId, targetId, count);
  } catch (e) {}
}

function pluralizeMinutes(n: number): string {
  const abs = Math.abs(Math.floor(n));
  const mod10 = abs % 10;
  const mod100 = abs % 100;
  if (mod100 >= 11 && mod100 <= 19) return `${n} минут`;
  if (mod10 === 1) return `${n} минуту`;
  if (mod10 >= 2 && mod10 <= 4) return `${n} минуты`;
  return `${n} минут`;
}

function pluralizeSeconds(n: number): string {
  const abs = Math.abs(Math.floor(n));
  const mod10 = abs % 10;
  const mod100 = abs % 100;
  if (mod100 >= 11 && mod100 <= 19) return `${n} секунд`;
  if (mod10 === 1) return `${n} секунду`;
  if (mod10 >= 2 && mod10 <= 4) return `${n} секунды`;
  return `${n} секунд`;
}

function pluralizeDays(n: number): string {
  const abs = Math.abs(Math.floor(n));
  const mod10 = abs % 10;
  const mod100 = abs % 100;
  if (mod100 >= 11 && mod100 <= 19) return `${n} дней`;
  if (mod10 === 1) return `${n} день`;
  if (mod10 >= 2 && mod10 <= 4) return `${n} дня`;
  return `${n} дней`;
}

async function getResolvedFullName(uid: number): Promise<string> {
  if (!uid || isNaN(Number(uid))) return "Пользователь";
  const numId = Number(uid);
  if (numId < 0) return formatCommunityMention(numId, "nom");
  const cached = userCache.get(numId);
  if (cached?.fullName && !cached.fullName.startsWith("User")) return cached.fullName;
  if (cached?.nick && !cached.nick.startsWith("User")) return cached.nick;
  const fetched = await fetchVkFullName(numId);
  if (fetched && !fetched.startsWith("User")) return fetched;
  return "Пользователь";
}

async function renderListsResponse(peerId: number, category: "main" | "warns" | "mutes" | "bans", page: number, authorId: number, userRole: number): Promise<{ text: string; keyboard: any }> {
  const safeAuthorId = authorId || 0;
  const keyboard = { inline: true, buttons: [] as any[] };

  if (category === "main") {
    const text = `...::Список пользователей с наказаниями::...

Укажите категорию:`;
    const buttons: any[] = [
      [{ action: { type: "callback", label: "С предупреждениями", payload: JSON.stringify({ cmd: "lists_view", cat: "warns", p: 1, authorId: safeAuthorId }) }, color: "secondary" }],
      [{ action: { type: "callback", label: "С блокировкой чата", payload: JSON.stringify({ cmd: "lists_view", cat: "mutes", p: 1, authorId: safeAuthorId }) }, color: "secondary" }]
    ];
    if (userRole > 2) {
      buttons.push([{ action: { type: "callback", label: "С блокировкой", payload: JSON.stringify({ cmd: "lists_view", cat: "bans", p: 1, authorId: safeAuthorId }) }, color: "secondary" }]);
    }
    keyboard.buttons = buttons;
    return { text, keyboard };
  }

  if (category === "warns") {
    let text = `...::Список пользователей с наказаниями::...

| Категория: С предупреждениями

`;
    const { profiles } = await getChatMembers(peerId);
    const warnedUsers: any[] = [];
    for (const p of profiles) {
      if (p.id > 0) {
        const u = await getOrCreateUser(p.id);
        const chatWarns = (u.chatWarnings && u.chatWarnings[peerId]) || 0;
        const warnsCount = chatWarns || u.warnings || 0;
        if (warnsCount > 0) {
          const list = u.activeWarningsList || [];
          const lastWarn = list.length > 0 ? list[list.length - 1] : { by: u.warnedBy || 1, date: u.warnDate || Date.now() };
          warnedUsers.push({
            id: p.id,
            warnsCount,
            by: lastWarn.by || u.warnedBy || 1,
            date: lastWarn.date || u.warnDate || Date.now()
          });
        }
      }
    }

    if (warnedUsers.length === 0) {
      text += `В этой беседе нет пользователей с предупреждениями.`;
      keyboard.buttons = [
        [{ action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "lists_main", authorId: safeAuthorId }) }, color: "negative" }]
      ];
      return { text, keyboard };
    }

    const pageSize = 15;
    const totalPages = Math.max(1, Math.ceil(warnedUsers.length / pageSize));
    const curPage = Math.min(Math.max(1, page), totalPages);
    const startIndex = (curPage - 1) * pageSize;
    const pageItems = warnedUsers.slice(startIndex, startIndex + pageSize);

    for (let i = 0; i < pageItems.length; i++) {
      const item = pageItems[i];
      const targetName = await getResolvedFullName(item.id);
      const modName = await getResolvedFullName(item.by);
      const dateStr = formatAmPmCustomDate(item.date);
      text += `${startIndex + i + 1}) [id${item.id}|${targetName}] | (${item.warnsCount}/3) | Последнее предупреждение выдал(-а) - [id${item.by}|${modName}] | ${dateStr}
`;
    }

    const navRow: any[] = [];
    if (totalPages > 1) {
      navRow.push({ action: { type: "callback", label: "««", payload: JSON.stringify({ cmd: "lists_view", cat: "warns", p: 1, authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "◀", payload: JSON.stringify({ cmd: "lists_view", cat: "warns", p: Math.max(1, curPage - 1), authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "▶", payload: JSON.stringify({ cmd: "lists_view", cat: "warns", p: Math.min(totalPages, curPage + 1), authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "»»", payload: JSON.stringify({ cmd: "lists_view", cat: "warns", p: totalPages, authorId: safeAuthorId }) }, color: "primary" });
      keyboard.buttons.push(navRow);
    }
    keyboard.buttons.push([
      { action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "lists_main", authorId: safeAuthorId }) }, color: "negative" }
    ]);
    return { text: text.trim(), keyboard };
  }

  if (category === "mutes") {
    let text = `...::Список пользователей с наказаниями::...

| Категория: С блокировкой чата

`;
    const { profiles } = await getChatMembers(peerId);
    const now = Date.now();
    const mutedUsers: any[] = [];
    for (const p of profiles) {
      if (p.id > 0) {
        const u = await getOrCreateUser(p.id);
        if (u.muteUntil && u.muteUntil > now) {
          const issueDate = u.muteDate || (u.muteUntil - 3600000);
          const totalMinutes = Math.max(1, Math.round((u.muteUntil - issueDate) / 60000));
          const remMinutes = Math.max(1, Math.ceil((u.muteUntil - now) / 60000));
          mutedUsers.push({
            id: p.id,
            by: u.mutedBy || 1,
            totalMinutes,
            remMinutes,
            date: issueDate
          });
        }
      }
    }

    if (mutedUsers.length === 0) {
      text += `В этой беседе нет пользователей с активной блокировкой чата.`;
      keyboard.buttons = [
        [{ action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "lists_main", authorId: safeAuthorId }) }, color: "negative" }]
      ];
      return { text, keyboard };
    }

    const pageSize = 15;
    const totalPages = Math.max(1, Math.ceil(mutedUsers.length / pageSize));
    const curPage = Math.min(Math.max(1, page), totalPages);
    const startIndex = (curPage - 1) * pageSize;
    const pageItems = mutedUsers.slice(startIndex, startIndex + pageSize);

    for (let i = 0; i < pageItems.length; i++) {
      const item = pageItems[i];
      const targetName = await getResolvedFullName(item.id);
      const modName = await getResolvedFullName(item.by);
      const dateStr = formatAmPmCustomDate(item.date);
      text += `${startIndex + i + 1}) [id${item.id}|${targetName}] | Модератор - [id${item.by}|${modName}] | Срок: ${pluralizeMinutes(item.totalMinutes)} | До конца: ${pluralizeMinutes(item.remMinutes)} | ${dateStr}
`;
    }

    const navRow: any[] = [];
    if (totalPages > 1) {
      navRow.push({ action: { type: "callback", label: "««", payload: JSON.stringify({ cmd: "lists_view", cat: "mutes", p: 1, authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "◀", payload: JSON.stringify({ cmd: "lists_view", cat: "mutes", p: Math.max(1, curPage - 1), authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "▶", payload: JSON.stringify({ cmd: "lists_view", cat: "mutes", p: Math.min(totalPages, curPage + 1), authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "»»", payload: JSON.stringify({ cmd: "lists_view", cat: "mutes", p: totalPages, authorId: safeAuthorId }) }, color: "primary" });
      keyboard.buttons.push(navRow);
    }
    keyboard.buttons.push([
      { action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "lists_main", authorId: safeAuthorId }) }, color: "negative" }
    ]);
    return { text: text.trim(), keyboard };
  }

  if (category === "bans") {
    let text = `...::Список пользователей с наказаниями::...

| Категория: С блокировкой

`;
    const allUsers = await getAllUsers();
    const now = Date.now();
    const bannedUsers: any[] = [];

    for (const u of allUsers) {
      const uid = u.userId || u.id;
      if (!uid) continue;
      const chatBans = u.chatBans || {};
      const banInfo = chatBans[peerId] || (u.isBanned && (!u.banPeerId || u.banPeerId === peerId) ? { by: u.bannedBy, reason: u.banReason, date: u.banDate, expiresAt: u.banExpiresAt } : null);
      if (banInfo && (!banInfo.expiresAt || banInfo.expiresAt > now)) {
        const issueDate = banInfo.date || (Date.now() - 3600000);
        let termStr = "Навсегда";
        let remStr = "Навсегда";
        if (banInfo.expiresAt) {
          const totalDays = Math.max(1, Math.round((banInfo.expiresAt - issueDate) / 86400000));
          const remDays = Math.max(1, Math.ceil((banInfo.expiresAt - now) / 86400000));
          termStr = pluralizeDays(totalDays);
          remStr = pluralizeDays(remDays);
        }
        bannedUsers.push({
          id: uid,
          by: banInfo.by || 1,
          termStr,
          remStr,
          date: issueDate
        });
      }
    }

    if (bannedUsers.length === 0) {
      text += `В этой беседе нет заблокированных пользователей.`;
      keyboard.buttons = [
        [{ action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "lists_main", authorId: safeAuthorId }) }, color: "negative" }]
      ];
      return { text, keyboard };
    }

    const pageSize = 15;
    const totalPages = Math.max(1, Math.ceil(bannedUsers.length / pageSize));
    const curPage = Math.min(Math.max(1, page), totalPages);
    const startIndex = (curPage - 1) * pageSize;
    const pageItems = bannedUsers.slice(startIndex, startIndex + pageSize);

    for (let i = 0; i < pageItems.length; i++) {
      const item = pageItems[i];
      const targetName = await getResolvedFullName(item.id);
      const modName = await getResolvedFullName(item.by);
      const dateStr = formatAmPmCustomDate(item.date);
      text += `${startIndex + i + 1}) [id${item.id}|${targetName}] | Модератор - [id${item.by}|${modName}] | Срок: ${item.termStr} | До конца: ${item.remStr} | ${dateStr}
`;
    }

    const navRow: any[] = [];
    if (totalPages > 1) {
      navRow.push({ action: { type: "callback", label: "««", payload: JSON.stringify({ cmd: "lists_view", cat: "bans", p: 1, authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "◀", payload: JSON.stringify({ cmd: "lists_view", cat: "bans", p: Math.max(1, curPage - 1), authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "▶", payload: JSON.stringify({ cmd: "lists_view", cat: "bans", p: Math.min(totalPages, curPage + 1), authorId: safeAuthorId }) }, color: "primary" });
      navRow.push({ action: { type: "callback", label: "»»", payload: JSON.stringify({ cmd: "lists_view", cat: "bans", p: totalPages, authorId: safeAuthorId }) }, color: "primary" });
      keyboard.buttons.push(navRow);
    }
    keyboard.buttons.push([
      { action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "lists_main", authorId: safeAuthorId }) }, color: "negative" }
    ]);
    return { text: text.trim(), keyboard };
  }

  return { text: "Ошибка получения списка.", keyboard: { inline: true, buttons: [] } };
}

function formatMarriageDate(ts: number): string {
  const mskMs = ts + 3 * 3600 * 1000;
  const d = new Date(mskMs);
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mm = String(d.getUTCMinutes()).padStart(2, "0");
  const ss = String(d.getUTCSeconds()).padStart(2, "0");
  
  const days = ["воскресенье", "понедельник", "вторник", "среда", "четверг", "пятница", "суббота"];
  const months = ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"];
  
  const dayName = days[d.getUTCDay()];
  const dayNum = d.getUTCDate();
  const monthName = months[d.getUTCMonth()];
  const yearNum = d.getUTCFullYear();

  return `${hh} ч. ${mm} м. ${ss} с. (МСК) | ${dayName}, ${dayNum} ${monthName}, ${yearNum} года`;
}

