let cachedStakanPhoto: string | null = null;
async function getStakanPhotoAttachment(peerId: number, outcomeInfo?: { choice: number; winningCup: number; isWin: boolean; stake?: number }): Promise<string | null> {
  if (!outcomeInfo && cachedStakanPhoto) return cachedStakanPhoto;
  try {
    if (createCanvas) {
      const width = 600;
      const height = 300;
      const canvas = createCanvas(width, height);
      const ctx = canvas.getContext("2d");

      // Table background gradient
      const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
      bgGrad.addColorStop(0, "#1a2a1a");
      bgGrad.addColorStop(1, "#0d150d");
      ctx.fillStyle = bgGrad;
      ctx.fillRect(0, 0, width, height);

      // Green gaming felt table border
      ctx.fillStyle = "#2d5a27";
      ctx.fillRect(20, 20, width - 40, height - 40);
      ctx.strokeStyle = "#408538";
      ctx.lineWidth = 6;
      ctx.strokeRect(20, 20, width - 40, height - 40);

      // Header text in Russian
      ctx.fillStyle = "#ffffff";
      ctx.font = "bold 24px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("ИГРА «НАПЁРСТКИ / СТАКАНИЩА»", width / 2, 55);

      ctx.fillStyle = "#a0e89b";
      ctx.font = "16px sans-serif";
      if (outcomeInfo) {
        if (outcomeInfo.isWin) {
          ctx.fillStyle = "#69f0ae";
          ctx.fillText(`ПОБЕДА! Шарик найден под стаканом #${outcomeInfo.winningCup + 1}!`, width / 2, 85);
        } else {
          ctx.fillStyle = "#ff8a80";
          ctx.fillText(`ПРОИГРЫШ! Шарик был под стаканом #${outcomeInfo.winningCup + 1}!`, width / 2, 85);
        }
      } else {
        ctx.fillText("Угадайте, под каким из 3 зеленых стаканов находится шарик!", width / 2, 85);
      }

      // Draw 3 Green Cups
      const cupsX = [130, 300, 470];
      const baseCupY = 150;

      cupsX.forEach((cx, i) => {
        const isSelected = outcomeInfo && outcomeInfo.choice === i;
        const isWinning = outcomeInfo && outcomeInfo.winningCup === i;
        const isLifted = outcomeInfo && (isSelected || isWinning);
        const cupY = isLifted ? baseCupY - 35 : baseCupY;

        // If outcome and winning cup, draw the winning golden/white ball under it
        if (outcomeInfo && isWinning) {
          // Ball shadow
          ctx.fillStyle = "rgba(0,0,0,0.5)";
          ctx.beginPath();
          ctx.ellipse(cx, baseCupY + 70, 14, 6, 0, 0, Math.PI * 2);
          ctx.fill();

          // Shiny golden ball
          const ballGrad = ctx.createRadialGradient(cx - 3, baseCupY + 58, 2, cx, baseCupY + 60, 14);
          ballGrad.addColorStop(0, "#ffffff");
          ballGrad.addColorStop(0.3, "#fff59d");
          ballGrad.addColorStop(0.8, "#fbc02d");
          ballGrad.addColorStop(1, "#f57f17");
          ctx.fillStyle = ballGrad;
          ctx.beginPath();
          ctx.arc(cx, baseCupY + 60, 14, 0, Math.PI * 2);
          ctx.fill();
          ctx.strokeStyle = "#fff9c4";
          ctx.lineWidth = 1.5;
          ctx.stroke();
        }

        // Cup shadow
        ctx.fillStyle = "rgba(0,0,0,0.4)";
        ctx.beginPath();
        ctx.ellipse(cx, baseCupY + 80, 45, 12, 0, 0, Math.PI * 2);
        ctx.fill();

        // Cup body gradient (Vibrant Emerald Green)
        const cupGrad = ctx.createLinearGradient(cx - 35, cupY, cx + 35, cupY + 75);
        if (outcomeInfo) {
          if (isWinning) {
            cupGrad.addColorStop(0, "#66bb6a");
            cupGrad.addColorStop(0.5, "#43a047");
            cupGrad.addColorStop(1, "#2e7d32");
          } else if (isSelected && !outcomeInfo.isWin) {
            cupGrad.addColorStop(0, "#ef5350");
            cupGrad.addColorStop(0.5, "#c62828");
            cupGrad.addColorStop(1, "#8e0000");
          } else {
            cupGrad.addColorStop(0, "#4caf50");
            cupGrad.addColorStop(0.5, "#2e7d32");
            cupGrad.addColorStop(1, "#1b5e20");
          }
        } else {
          cupGrad.addColorStop(0, "#4caf50");
          cupGrad.addColorStop(0.5, "#2e7d32");
          cupGrad.addColorStop(1, "#1b5e20");
        }

        ctx.fillStyle = cupGrad;
        ctx.beginPath();
        ctx.moveTo(cx - 25, cupY);
        ctx.lineTo(cx + 25, cupY);
        ctx.lineTo(cx + 40, cupY + 75);
        ctx.lineTo(cx - 40, cupY + 75);
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = (outcomeInfo && isWinning) ? "#b9f6ca" : (outcomeInfo && isSelected && !outcomeInfo.isWin ? "#ff8a80" : "#81c784");
        ctx.lineWidth = 3;
        ctx.stroke();

        // Cup rim highlight
        ctx.fillStyle = (outcomeInfo && isWinning) ? "#a5d6a7" : (outcomeInfo && isSelected && !outcomeInfo.isWin ? "#e57373" : "#66bb6a");
        ctx.beginPath();
        ctx.ellipse(cx, cupY, 25, 6, 0, 0, Math.PI * 2);
        ctx.fill();

        // Cup number badge
        ctx.fillStyle = "#ffffff";
        ctx.font = "bold 22px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText(`#${i + 1}`, cx, cupY + 48);
      });

      const buffer = canvas.toBuffer("image/jpeg");
      const up = await uploadPhoto(peerId, buffer);
      if (up && up.attachment) {
        if (!outcomeInfo) {
          cachedStakanPhoto = up.attachment;
        }
        return up.attachment;
      }
    }
  } catch (e) {
    console.error("Error generating stakan photo:", e);
  }
  return null;
}

