// Chat caching
const chatCache = new LRUCache<number, any>({ max: 1000, ttl: 1000 * 60 * 20 });
const staffCallCooldown = new LRUCache<number, number>({ max: 2000, ttl: 1000 * 60 * 5 });
const clanCache = new LRUCache<string, any>({ max: 1000, ttl: 1000 * 60 * 30 });

const chatFetchPromises = new Map<number, Promise<any>>();

async function getOrCreateChat(peerId: number) {
  if (chatCache.has(peerId)) {
    return chatCache.get(peerId);
  }

  if (chatFetchPromises.has(peerId)) {
    return await chatFetchPromises.get(peerId)!;
  }

  const defaultChat: any = {
    id: peerId,
    title: `Беседа №${peerId}`,
    ownerId: 0,
    membersCount: 0,
    af: false,
    antisliv: false,
    raid: false,
    group: false,
    welcometext: null,
    welcometext_enabled: false
  };

  const fetchPromise = (async () => {
    try {
      const chatRef = firestoreDb.collection("chats").doc(peerId.toString());
      const chatDoc = await chatRef.get().catch(() => null);
      if (chatDoc && chatDoc.exists) {
        const data = chatDoc.data() || {};
        Object.assign(defaultChat, data);
      } else {
        await chatRef.set(defaultChat).catch(() => {});
      }
      if ((!defaultChat.title || defaultChat.title.startsWith("Беседа №")) && peerId > 2000000000) {
        const convRes = await fastVkCall("messages.getConversationsById", { peer_ids: String(peerId) }).catch(() => null);
        const settings = convRes?.response?.items?.[0]?.chat_settings;
        if (settings) {
          if (settings.title) defaultChat.title = settings.title;
          if (settings.owner_id) defaultChat.ownerId = settings.owner_id;
          if (settings.members_count) defaultChat.membersCount = settings.members_count;
          chatRef.set({ title: defaultChat.title, ownerId: defaultChat.ownerId, membersCount: defaultChat.membersCount }, { merge: true }).catch(() => {});
        }
      }
    } catch (e) {} finally {
      chatFetchPromises.delete(peerId);
    }
    chatCache.set(peerId, defaultChat);
    return defaultChat;
  })();

  chatFetchPromises.set(peerId, fetchPromise);
  chatCache.set(peerId, defaultChat);
  return await fetchPromise;
}

const dirtyChats = new Set<number>();
const dirtyUsers = new Set<number>();

async function updateChat(peerId: number, data: any) {
  let cached = chatCache.get(peerId);
  if (!cached) {
    cached = await getOrCreateChat(peerId);
  }
  Object.assign(cached, data);
  chatCache.set(peerId, cached);
  dirtyChats.add(peerId);

  // Прямое сохранение в БД без коммита сразу после каждого действия
  try {
    firestoreDb.collection("chats").doc(peerId.toString()).set(data, { merge: true }).catch((err: any) => {
      console.error(`[DB Direct Save Error] Chat ${peerId}:`, err?.message || err);
    });
  } catch (e: any) {
    console.error(`[DB Direct Save Exception] Chat ${peerId}:`, e);
  }
}

async function syncAllChatTitles(): Promise<number> {
  let updatedCount = 0;
  try {
    const chatsSnap = await firestoreDb.collection("chats").get();
    const peerIds: number[] = [];
    for (const doc of chatsSnap.docs) {
      const pId = Number(doc.id);
      if (pId && pId > 2000000000) {
        peerIds.push(pId);
      }
    }

    if (peerIds.length === 0) return 0;

    const batches = [];
    for (let i = 0; i < peerIds.length; i += 100) {
      batches.push(peerIds.slice(i, i + 100));
    }

    await Promise.all(batches.map(async (batchIds) => {
      try {
        const res = await fastVkCall("messages.getConversationsById", { peer_ids: batchIds.join(",") });
        const items = res.response?.items || [];
        for (const item of items) {
          const pId = item?.peer?.id;
          const newTitle = item?.chat_settings?.title;
          if (pId && newTitle) {
            await updateChat(pId, { title: newTitle });
            updatedCount++;
          }
        }
      } catch (e) {}
    }));
  } catch (e) {
    console.error("Error in syncAllChatTitles:", e);
  }
  return updatedCount;
}

async function syncAllUserNames(): Promise<number> {
  let updatedCount = 0;
  try {
    const usersSnap = await firestoreDb.collection("users").get();
    const userIds: number[] = [];
    for (const doc of usersSnap.docs) {
      const uId = Number(doc.id);
      if (uId && uId > 0 && uId < 2000000000) {
        userIds.push(uId);
      }
    }
    if (userIds.length === 0) return 0;
    
    const batches = [];
    for (let i = 0; i < userIds.length; i += 500) {
      batches.push(userIds.slice(i, i + 500));
    }
    
    for (const batch of batches) {
      try {
        const res = await fastVkCall("users.get", { user_ids: batch.join(","), name_case: "nom" });
        const items = res.response || [];
        for (const item of items) {
          if (item?.id && item?.first_name && item?.last_name) {
            const fullName = `${item.first_name} ${item.last_name}`;
            await updateUser(item.id, { fullName, nick: item.first_name });
            updatedCount++;
          }
        }
      } catch (e) {
        console.error("Batch sync users error:", e);
      }
      await new Promise(r => setTimeout(r, 1000));
    }
  } catch (e) {
    console.error("Error in syncAllUserNames:", e);
  }
  return updatedCount;
}

