export function formatSecondsPlural(n: number): string {
  const rem10 = n % 10;
  const rem100 = n % 100;
  if (rem100 >= 11 && rem100 <= 19) return "секунд";
  if (rem10 === 1) return "секунду";
  if (rem10 >= 2 && rem10 <= 4) return "секунды";
  return "секунд";
}

const chatMembersCache = new LRUCache<number, { members: any[], profiles: any[], expiry: number }>({ max: 500, ttl: 1000 * 60 * 10 });
const chatAdminsSetCache = new LRUCache<number, { adminIds: Set<number>, ownerId: number, expiry: number }>({ max: 500, ttl: 1000 * 60 * 10 });
const botAdminInChatCache = new LRUCache<number, { isAdmin: boolean, expiry: number }>({ max: 500, ttl: 1000 * 60 * 10 });
const adminCache = new LRUCache<string, { isAdmin: boolean, expiry: number }>({ max: 1000, ttl: 1000 * 60 * 5 });
const lastPickedInChat = new LRUCache<number, number>({ max: 500, ttl: 1000 * 60 * 60 });
const chatRecentMessages = new LRUCache<number, { cmId: number, fromId: number, text?: string }[]>({ max: 500, ttl: 1000 * 60 * 5 });
const noAdminThrottle = new LRUCache<number, number>({ max: 500, ttl: 1000 * 60 * 5 });
