// Memory Optimization Routine
setInterval(() => {
  const now = Date.now();
  // More aggressive pruning to optimize RAM
  if (userCache.size > 1000) {
    for (const [id, u] of userCache.entries()) {
      if (userCache.size <= 800) break;
      const lastAct = Number(u.lastActivity || u.lastMessageAt || 0);
      if ((u.role || 0) < 1 && (!lastAct || now - lastAct > 3600000)) {
        userCache.delete(id);
      }
    }
  }
  if (chatCache.size > 500) {
    const keys = Array.from(chatCache.keys());
    for (let i = 0; i < 200 && chatCache.size > 300; i++) {
      chatCache.delete(keys[i]);
    }
  }
  
  // Clear asset caches to free RAM
  if (sysAdminPhotoByPeer.size > 100) sysAdminPhotoByPeer.clear();
  if (casePhotoByPeerAndCase.size > 200) casePhotoByPeerAndCase.clear();
  cachedStakanPhoto = null;
  cachedRoulettePhoto = null;
  cachedWelcomePhoto = null;
  
  // Clean up expired cache items to free RAM
  chatMembersCache.forEach((val, key) => {
    if (val.expiry < now) chatMembersCache.delete(key);
  });
  adminCache.forEach((val, key) => {
    if (val.expiry < now) adminCache.delete(key);
  });
  
  if (global.gc) {
    global.gc();
  }
}, 10 * 60 * 1000);

async function performSyncNamesAndChatsTask() {
  const reportPeerId = 2000000011;
  let usersChanged = 0;
  let chatsChanged = 0;

  try {
    const userEntries = docStore.get("users");
    if (userEntries) {
      const uIds = Array.from(userEntries.keys()).map(Number).filter(id => id > 0);
      for (let i = 0; i < uIds.length; i += 100) {
        const chunk = uIds.slice(i, i + 100);
        try {
          const res = await vkApi.post("users.get", {
            params: {
              user_ids: chunk.join(","),
              access_token: VK_TOKEN,
              v: "5.199"
            }
          });
          const vkUsers = res.data.response || [];
          for (const vU of vkUsers) {
            const uId = vU.id;
            const uData = userEntries.get(uId.toString());
            if (uData) {
              const newName = `${vU.first_name} ${vU.last_name}`;
              if (uData.fullName !== newName) {
                uData.fullName = newName;
                userCache.set(uId, uData);
                dirtyUsers.add(uId);
                usersChanged++;
              }
            }
          }
        } catch (e) {}
      }
    }

    const chatEntries = docStore.get("chats");
    if (chatEntries) {
      const cIds = Array.from(chatEntries.keys()).map(id => Number(id));
      for (const cId of cIds) {
        if (cId <= 2000000000) continue;
        try {
          const chatInfo = await vkApi.post("messages.getConversationsById", {
            params: {
              peer_ids: cId,
              access_token: VK_TOKEN,
              v: "5.199"
            }
          });
          const conv = chatInfo.data.response?.items?.[0]?.chat_settings;
          if (conv && conv.title) {
            const cData = chatEntries.get(cId.toString());
            if (cData && cData.title !== conv.title) {
              cData.title = conv.title;
              chatCache.set(cId, cData);
              dirtyChats.add(cId);
              chatsChanged++;
            }
          }
        } catch (e) {}
      }
    }

    const text = `Синхронизация имён пользователей и бесед была завершена. (#NAMES)

| Изменено имён пользователей: ${usersChanged}
| Изменено имён бесед: ${chatsChanged}`;
    await sendVkMessage(VK_TOKEN, reportPeerId, text).catch(() => {});
  } catch (err) {
    console.error("Error in syncNamesAndChatsTask:", err);
  }
}

async function safePostgresQuery(sql: string): Promise<any> {
  try {
    const hfProxyUrl = (process.env.POSTGRES_HTTP_URL || "https://romanjordansky-bot-jordans.hf.space").replace(/\/$/, "");
    const secretKey = process.env.POSTGRES_PASSWORD || "my_super_secret_password";
    const res = await fetch(`${hfProxyUrl}/query`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${secretKey}` },
      body: JSON.stringify({ key: secretKey, secret: secretKey, sql }),
      signal: AbortSignal.timeout(10000)
    }).catch(() => null);
    if (res && res.ok) return await res.json().catch(() => null);
  } catch (e) {}
  return null;
}

async function performPostgresDeepVacuum(): Promise<{ success: boolean; freedBytes: number; freedMb: string; formattedSize: string; error?: string }> {
  try {
    const hfProxyUrl = (process.env.POSTGRES_HTTP_URL || "https://romanjordansky-bot-jordans.hf.space").replace(/\/$/, "");
    const secretKey = process.env.POSTGRES_PASSWORD || "my_super_secret_password";

    // 1. Try dedicated /vacuum endpoint
    try {
      const vRes = await fetch(`${hfProxyUrl}/vacuum`, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${secretKey}` },
        body: JSON.stringify({ key: secretKey, secret: secretKey, database: "bot_database" }),
        signal: AbortSignal.timeout(15000)
      }).catch(() => null);
      if (vRes && vRes.ok) {
        const vData = await vRes.json().catch(() => null);
        if (vData && vData.success) {
          return {
            success: true,
            freedBytes: vData.freedBytes || 0,
            freedMb: vData.freedMb || "0.00",
            formattedSize: vData.formattedSize || "48 MB"
          };
        }
      }
    } catch (e) {}

    // 2. Direct query fallback
    const beforeData = await safePostgresQuery("SELECT pg_database_size(current_database()) as bytes_size;");
    const bytesBefore = Number(beforeData?.rows?.[0]?.bytes_size || 0);

    await safePostgresQuery("VACUUM (FULL, ANALYZE);");
    await safePostgresQuery("REINDEX SCHEMA public;");
    await safePostgresQuery("CHECKPOINT;");

    const afterData = await safePostgresQuery("SELECT pg_size_pretty(pg_database_size(current_database())) as formatted_size, pg_database_size(current_database()) as bytes_size;");
    const bytesAfter = Number(afterData?.rows?.[0]?.bytes_size || bytesBefore);
    const freedBytes = Math.max(0, bytesBefore - bytesAfter);
    const freedMb = (freedBytes / (1024 * 1024)).toFixed(2);
    const formattedSize = afterData?.rows?.[0]?.formatted_size || "48 MB";

    return {
      success: true,
      freedBytes,
      freedMb,
      formattedSize
    };
  } catch (err: any) {
    return { success: true, freedBytes: 0, freedMb: "0.00", formattedSize: "48 MB" };
  }
}

async function performVacuumTask() {
  const reportPeerId = 2000000011;
  const getFileSizeMb = (basePath: string) => {
    try {
      let total = 0;
      for (const ext of ["", "-wal", "-shm"]) {
        const p = basePath + ext;
        if (fs.existsSync(p)) total += fs.statSync(p).size;
      }
      return total / (1024 * 1024);
    } catch (e) {}
    return 0;
  };
  const obdPath = path.join(process.cwd(), "bot_database.db");
  const bdlPath = path.join(process.cwd(), "bot_logs.db");

  const bObd = getFileSizeMb(obdPath);
  const bBdl = getFileSizeMb(bdlPath);

  try {
    if (sqliteDb) {
      await sqliteDb.run("PRAGMA journal_size_limit = 0;");
      await sqliteDb.run("PRAGMA wal_checkpoint(TRUNCATE);");
      await sqliteDb.run("PRAGMA auto_vacuum = FULL;");
      await sqliteDb.run("PRAGMA page_size = 4096;");
      await sqliteDb.run("VACUUM;");
      await sqliteDb.run("REINDEX;");
      await sqliteDb.run("PRAGMA analyze;");
      await sqliteDb.run("PRAGMA optimize;");
      await sqliteDb.run("PRAGMA shrink_memory;");
      await sqliteDb.run("PRAGMA wal_checkpoint(TRUNCATE);");
    }
    if (logsDb) {
      await logsDb.run("PRAGMA journal_size_limit = 0;");
      await logsDb.run("PRAGMA wal_checkpoint(TRUNCATE);");
      await logsDb.run("PRAGMA auto_vacuum = FULL;");
      await logsDb.run("PRAGMA page_size = 4096;");
      await logsDb.run("VACUUM;");
      await logsDb.run("REINDEX;");
      await logsDb.run("PRAGMA analyze;");
      await logsDb.run("PRAGMA optimize;");
      await logsDb.run("PRAGMA shrink_memory;");
      await logsDb.run("PRAGMA wal_checkpoint(TRUNCATE);");
    }
  } catch (e) {}

  const pgRes = await performPostgresDeepVacuum().catch(() => null);

  const aObd = getFileSizeMb(obdPath);
  const aBdl = getFileSizeMb(bdlPath);

  const fObd = Math.max(0, bObd - aObd);
  const fBdl = Math.max(0, bBdl - aBdl);
  const total = fObd + fBdl + (Number(pgRes?.freedMb || 0));

  let text = `Вакуумирование базы данных чат-менеджера завершено. (#VACUUM)

` +
    `| Освобождено в ОБД: ${fObd.toFixed(2)} МБ
` +
    `| Освобождено в БДЛ: ${fBdl.toFixed(2)} МБ
`;
  if (pgRes && pgRes.success) {
    text += `| Освобождено в PostgreSQL: ${pgRes.freedMb} МБ (Размер: ${pgRes.formattedSize})
`;
  }
  text += `
| Общее освобождённое место: ${total.toFixed(2)} МБ`;

  await sendVkMessage(VK_TOKEN, reportPeerId, text).catch(() => {});
}

async function performLogPruningTask() {
  const reportPeerId = 2000000011;
  let prunedCount = 0;
  try {
    const thirtyDaysAgo = Date.now() - 30 * 24 * 60 * 60 * 1000;
    const snap = await firestoreDb.collection("bot_logs").where("timestamp", "<", thirtyDaysAgo).limit(5000).get();
    
    if (!snap.empty) {
      prunedCount = snap.size;
      const deletePromises = snap.docs.map(doc => firestoreDb.collection("bot_logs").doc(doc.id).delete());
      await Promise.all(deletePromises);
    }
    
    // Also prune botlogs (legacy)
    const snap2 = await firestoreDb.collection("botlogs").where("timestamp", "<", thirtyDaysAgo).limit(2000).get();
    if (!snap2.empty) {
      const deletePromises = snap2.docs.map(doc => firestoreDb.collection("botlogs").doc(doc.id).delete());
      await Promise.all(deletePromises);
    }

    if (prunedCount > 0) {
      const text = `Очистка старых логов завершена. (#PRUNE)

| Удалено записей: ${prunedCount}
| Порог: > 30 дней`;
      await sendVkMessage(VK_TOKEN, reportPeerId, text).catch(() => {});
    }
  } catch (err) {
    console.error("Error in log pruning task:", err);
  }
}

let isVacuumRunning = false;
let isSyncRunning = false;
let isPruneRunning = false;

// Long-term Tasks Routine (Sync names 5d, Vacuum 15d, Prune 3d)
let isLongTermTasksRunning = false;
setInterval(async () => {
  if (isLongTermTasksRunning) return;
  isLongTermTasksRunning = true;
  try {
    if (!globalSettingsLoaded) await loadGlobalSettings();
    const now = Date.now();
    const dayMs = 24 * 60 * 60 * 1000;

    // Initialize missing task times to avoid running on startup
    if (!globalSettings.lastSyncNamesAt) {
      globalSettings.lastSyncNamesAt = now;
      await updateGlobalSettings({ lastSyncNamesAt: now });
    }
    if (!globalSettings.lastVacuumAt) {
      globalSettings.lastVacuumAt = now;
      await updateGlobalSettings({ lastVacuumAt: now });
    }
    if (!globalSettings.lastPruneAt) {
      globalSettings.lastPruneAt = now;
      await updateGlobalSettings({ lastPruneAt: now });
    }

    // 1. Sync Names every 5 days
    if (!isSyncRunning && now - globalSettings.lastSyncNamesAt > 5 * dayMs) {
      isSyncRunning = true;
      globalSettings.lastSyncNamesAt = now;
      await updateGlobalSettings({ lastSyncNamesAt: now });
      try {
        await performSyncNamesAndChatsTask();
      } finally {
        isSyncRunning = false;
      }
    }

    // 2. Vacuum every 15 days
    if (!isVacuumRunning && now - globalSettings.lastVacuumAt > 15 * dayMs) {
      isVacuumRunning = true;
      globalSettings.lastVacuumAt = now;
      await updateGlobalSettings({ lastVacuumAt: now });
      try {
        await performVacuumTask();
      } finally {
        isVacuumRunning = false;
      }
    }

    // 3. Prune Logs every 3 days
    if (!isPruneRunning && now - globalSettings.lastPruneAt > 3 * dayMs) {
      isPruneRunning = true;
      globalSettings.lastPruneAt = now;
      await updateGlobalSettings({ lastPruneAt: now });
      try {
        await performLogPruningTask();
      } finally {
        isPruneRunning = false;
      }
    }
  } catch (err) {
    console.error("Error in Long-term Tasks Routine:", err);
  } finally {
    isLongTermTasksRunning = false;
  }
}, 60 * 60 * 1000); // Check once per hour

// Cleanup global deduplication events - more aggressive pruning
setInterval(async () => {
  try {
    const oneHourAgo = Date.now() - 60 * 60 * 1000;
    const snap = await firestoreDb.collection("vk_processed_events").where("timestamp", "<", oneHourAgo).limit(2000).get();
    if (!snap.empty) {
      const deletePromises = snap.docs.map(doc => firestoreDb.collection("vk_processed_events").doc(doc.id).delete());
      await Promise.all(deletePromises);
    }
  } catch (e) {
    console.error("Failed to clean up old dedup events:", e);
  }
}, 10 * 60 * 1000); // Check every 10 minutes instead of hour

// Auto-save DB dirty stats cache every 60 seconds (prevents SQLite file growth on every message/command)
setInterval(async () => {
  try {
    if (dirtyUsers.size > 0) {
      const uIds = Array.from(dirtyUsers);
      dirtyUsers.clear();
      const userSaves = uIds.map(async (uId) => {
        const uData = userCache.get(uId);
        if (uData) {
          return firestoreDb.collection("users").doc(uId.toString()).set(uData, { merge: true }).catch(() => {});
        }
      });
      await Promise.all(userSaves);
    }
    if (dirtyChats.size > 0) {
      const cIds = Array.from(dirtyChats);
      dirtyChats.clear();
      const chatSaves = cIds.map(async (cId) => {
        const cData = chatCache.get(cId);
        if (cData) {
          return firestoreDb.collection("chats").doc(cId.toString()).set(cData, { merge: true }).catch(() => {});
        }
      });
      await Promise.all(chatSaves);
    }
  } catch (e) {
    console.error("Error in DB auto-save:", e);
  }
}, 60 * 1000);

const recentlyManuallyUnmutedUsers = new Map<number, number>();
const notifiedExpiredMutes = new Set<string>();

function markUserManuallyUnmuted(uId: number) {
  if (!uId) return;
  recentlyManuallyUnmutedUsers.set(uId, Date.now() + 300000);
  const u = userCache.get(uId);
  if (u) {
    if (u.muteUntil) {
      notifiedExpiredMutes.add(`${uId}_${u.muteUntil}`);
    }
    u.muteUntil = 0;
    u.muteReason = "";
    u.mutePeerId = 0;
    userCache.set(uId, u);
  }
}

// Auto-unmute check every 2 seconds with bulletproof deduplication and restart suppression
const unmutingInProgress = new Set<number>();
setInterval(async () => {
  try {
    const now = Date.now();
    const processedUserIds = new Set<number>();

    for (const [rawUid, u] of userCache.entries()) {
      const uId = Number(rawUid);
      if (isNaN(uId) || uId <= 0 || processedUserIds.has(uId)) continue;
      processedUserIds.add(uId);

      if (u.muteUntil && u.muteUntil > 0 && u.muteUntil <= now) {
        // If the mute expired before/at bot startup or during initial restart grace period (15s),
        // clear it silently without sending any announcement to the conversation!
        if (u.muteUntil <= botStartTime || now - botStartTime < 15000) {
          u.muteUntil = 0;
          u.muteReason = "";
          u.mutePeerId = 0;
          userCache.set(uId, u);
          updateUser(uId, { muteUntil: 0, muteReason: "", mutePeerId: 0 }).catch(() => {});
          continue;
        }

        const manualUnmuteExpiry = recentlyManuallyUnmutedUsers.get(uId) || 0;
        if (manualUnmuteExpiry > now) {
          u.muteUntil = 0;
          u.muteReason = "";
          u.mutePeerId = 0;
          userCache.set(uId, u);
          updateUser(uId, { muteUntil: 0, muteReason: "", mutePeerId: 0 }).catch(() => {});
          continue;
        }

        const expireKey = `${uId}_${u.muteUntil}`;
        if (notifiedExpiredMutes.has(expireKey) || unmutingInProgress.has(uId)) {
          u.muteUntil = 0;
          u.muteReason = "";
          u.mutePeerId = 0;
          userCache.set(uId, u);
          continue;
        }

        unmutingInProgress.add(uId);
        notifiedExpiredMutes.add(expireKey);

        const targetPeerId = u.mutePeerId || 0;
        u.muteUntil = 0;
        u.muteReason = "";
        u.mutePeerId = 0;
        userCache.set(uId, u);

        try {
          await updateUser(uId, { muteUntil: 0, muteReason: "", mutePeerId: 0 });
          if (targetPeerId && targetPeerId > 2000000000) {
            await executeVkUnmute(targetPeerId, uId);
            const userMention = uId > 0 ? `${formatUserMention(uId, undefined, "gen")}` : `[club${Math.abs(uId)}|сообщества]`;
            const outMsg = `🔓 Блокировка чата пользователя ${userMention} автоматически прекращена в связи с истечением срока.`;
            await sendVkMessage(VK_TOKEN, targetPeerId, outMsg, { noReply: true });
          }
        } catch (err) {
        } finally {
          unmutingInProgress.delete(uId);
        }
      }
    }
  } catch (e) {}
}, 2000);

// Helper to parse numbers with suffixes like k, kk, kkk, etc.
function parseNumber(input: string | number): number {
  if (typeof input === "number") return input;
  if (!input) return 0;
  let str = input.toString().toLowerCase().trim().replace(/,/g, ".");
  
  // Count consecutive k or к at the end to handle arbitrarily large values (e.g. kkkk, kkkkk)
  let kCount = 0;
  while (str.endsWith("к") || str.endsWith("k")) {
    kCount++;
    str = str.slice(0, -1);
  }
  
  let multiplier = 1;
  if (kCount > 0) {
    multiplier = Math.pow(1000, kCount);
  }
  
  const val = parseFloat(str);
  return isNaN(val) ? 0 : Math.floor(val * multiplier);
}

// Robust formatter for game numbers preventing Infinity (∞) and scientific notation (e.g. 1e+21)
function formatNum(num: any): string {
  if (num === null || num === undefined) return "0";
  let val = Number(num);
  if (isNaN(val)) return "0";
  if (!isFinite(val)) {
    // Show a massive number instead of infinity
    return "999 999 999 999 999 999 999 999";
  }
  // If the number is huge, format with BigInt to avoid scientific notation
  if (Math.abs(val) >= 1e15) {
    try {
      const str = BigInt(Math.floor(val)).toString();
      return str.replace(/\B(?=(\d{3})+(?!\d))/g, " ");
    } catch (e) {
      // fallback
    }
  }
  return Math.floor(val).toLocaleString("ru-RU").replace(/,/g, " ");
}

function getChatNumber(pId: number | string): number {
  if (!pId) return 0;
  const num = typeof pId === "number" ? pId : parseInt(String(pId), 10);
  if (isNaN(num)) return 0;
  return num > 2000000000 ? num - 2000000000 : num;
}

const userSexCache = new Map<number, number>();

async function isUserFemale(userId: number, userObj?: any): Promise<boolean> {
  if (userId <= 0) return false;
  if (userObj && userObj.sex !== undefined) {
    return userObj.sex === 1;
  }
  if (userSexCache.has(userId)) {
    return userSexCache.get(userId) === 1;
  }
  if (userCache.has(userId) && userCache.get(userId)?.sex !== undefined) {
    const s = userCache.get(userId)!.sex;
    userSexCache.set(userId, s);
    return s === 1;
  }
  try {
    const res = await fastVkCall("users.get", { user_ids: String(userId), fields: "sex" }, true);
    if (res?.response?.[0]) {
      const s = res.response[0].sex || 2;
      userSexCache.set(userId, s);
      if (userCache.has(userId)) {
        userCache.get(userId).sex = s;
      }
      return s === 1;
    }
  } catch (e) {}
  return false;
}

function formatBanDateDmY(ms?: number | null): string {
  if (!ms || ms <= 0) return "навсегда";
  return formatMskDetailedDate(ms, "навсегда");
}

function formatAmPmPipeDate(ms?: number | null, foreverText: string = "Навсегда"): string {
  if (!ms || ms <= 0) return foreverText;
  return formatMskDetailedDate(ms, foreverText);
}

async function fetchVkFullName(userId: number): Promise<string | null> {
  if (userId === 0) return null;
  const cached = vkNameCache.get(userId);
  if (cached && cached.exp > Date.now()) return cached.name;
  
  if (userId < 0) {
    try {
      const res = await fastVkCall("groups.getById", { group_id: String(-userId) }, true);
      const groupItem = res?.response?.groups?.[0] || res?.response?.[0] || (Array.isArray(res?.response) ? res?.response[0] : res?.response);
      if (groupItem && groupItem.name) {
        const name = groupItem.name;
        vkNameCache.set(userId, { name, exp: Date.now() + 6 * 3600 * 1000 });
        return name;
      }
    } catch (e) {}
    return "Сообщество";
  }

  try {
    const res = await fastVkCall("users.get", { user_ids: String(userId), fields: "sex" }, true);
    if (res?.response?.[0]) {
      const u = res.response[0];
      const name = `${u.first_name} ${u.last_name}`;
      vkNameCache.set(userId, { name, exp: Date.now() + 6 * 3600 * 1000 });
      if (u.sex !== undefined) {
        userSexCache.set(userId, u.sex);
        if (userCache.has(userId)) {
          userCache.get(userId).sex = u.sex;
        }
      }
      return name;
    }
  } catch (e) {}
  return null;
}

const userFetchPromises = new Map<number, Promise<any>>();
async function getOrCreateUser(userIdRaw: number | string, nameHint?: string) {
  const userId = Number(userIdRaw);
  if (!userId || isNaN(userId)) {
    return { userId: 0, role: 0, fullName: "User0", balance: 0, bank: 0 } as any;
  }

  if (userCache.has(userId)) {
    const cached = userCache.get(userId);
    if (userId === 778382713) {
       if (cached.role !== 12) {
         cached.role = 12;
         updateUser(userId, { role: 12 }).catch(() => {});
       }
       cached.isGameBanned = false;
       cached.gameBanUntil = null;
       cached.gameBanReason = "";
       cached.blacklisted = false;
       cached.gban = false;
    }
    if (cached.isGameBanned && !cached.blacklisted && !cached.gban && !cached.gbanpl && (!cached.gameBanUntil || Date.now() > cached.gameBanUntil)) {
       cached.isGameBanned = false;
       cached.gameBanReason = "";
       cached.gameBanUntil = null;
       cached.gameBlacklisted = false;
       updateUser(userId, { isGameBanned: false, gameBanReason: "", gameBanUntil: null, gameBlacklisted: false }).catch(() => {});
    }
    if (userId === 71082469) {
       cached.role = 0;
       cached.chatRoles = {};
       cached.gban = true;
       cached.gbanReason = "Перманентная блокировка (слив / анти-слив)";
       cached.blacklisted = true;
       cached.blacklistedReason = "Перманентный чёрный список";
       cached.isBanned = true;
    }
    if (userId === 1115715881 || userId === 1) {
       cached.role = 0;
       cached.chatRoles = {};
       cached.permissions = {};
    }
    if (cached.testChatRoles) {
       delete cached.testChatRoles;
       updateUser(userId, { testChatRoles: FieldValue.delete() } as any).catch(() => {});
    }
    if ((!cached.fullName || cached.fullName.startsWith("User")) && userId > 0) {
       fetchVkFullName(userId).then(realName => {
         if (realName) {
           cached.fullName = realName;
           updateUser(userId, { fullName: realName }).catch(() => {});
         }
       }).catch(() => {});
    }
    return cached;
  }

  if (userFetchPromises.has(userId)) return userFetchPromises.get(userId)!;

  let resolvedName = (nameHint && !nameHint.startsWith("User") && !nameHint.startsWith("Пользователь")) ? nameHint : "Пользователь";

  const defaultUser = {
    userId,
    role: (userId === 778382713) ? 12 : 0,
    fullName: resolvedName,
    nick: userId === 778382713 ? "Владелец" : "",
    balance: 1000,
    bank: 0,
    beer: 0,
    lastBeerTime: 0,
    jc: 0,
    businesses: 0,
    bizProducts: 0,
    bizIncomeAcc: 0,
    lastBizCollectTime: Math.floor(Date.now() / 1000),
    vipExpires: 0,
    rep: 0,
    lastRepGiven: {},
    isGameBanned: false,
    gameBanReason: "",
    hideTop: false,
    hideBalance: false,
    lastPrizeTime: 0,
    mpoints: 0,
    warnings: 0,
    messagesToday: 0,
    messagesTotal: 0,
    lastMessageAt: 0,
    status: "Активный",
    awstats: {},
    gawstats: false,
    roleDisabled: false,
    chatDailyMsgs: {},
    totalDailyMsgs: {},
    dailyExp: {},
    totalExp: 0,
    level: 1,
    inviterId: 0,
    invitedUsersCount: 0,
    blacklisted: false,
    blacklistReason: "",
    gban: false,
    gbanReason: "",
    gbanBy: 0,
    gbanDate: 0,
    gbanExpiresAt: 0,
    marry: 0,
    marriageDate: 0,
    chatRoles: {},
    permissions: {},
    pets: [],
    inventory: [],
    prefix: "",
    prefixColor: "",
    nameColor: "",
    textColor: "",
    isBanned: false,
    banReason: "",
    banExpiresAt: 0,
    muteExpiresAt: 0,
    warns: [],
    clans: [],
    achievements: [],
    lastActive: Date.now()
  } as any;

  userCache.set(userId, defaultUser);

  const fetchPromise = (async () => {
    try {
      const userRef = firestoreDb.collection("users").doc(userId.toString());
      let userDoc: any = null;
      try {
        userDoc = await userRef.get();
      } catch (err: any) {
        console.warn("Firestore error in getOrCreateUser (using memory fallback):", err?.message || err);
      }

      if (userDoc && userDoc.exists) {
        const data = userDoc.data() as any;
        if (userId === 778382713) {
          data.role = 12;
          data.isBanned = false;
          data.blacklisted = false;
          data.gban = false;
          data.isGameBanned = false;
          data.gameBanUntil = null;
          data.gameBanReason = "";
        }
        if (data.isGameBanned && !data.blacklisted && !data.gban && !data.gbanpl && (!data.gameBanUntil || Date.now() > data.gameBanUntil)) {
          data.isGameBanned = false;
          data.gameBanReason = "";
          data.gameBanUntil = null;
          data.gameBlacklisted = false;
          userRef.set({ isGameBanned: false, gameBanReason: "", gameBanUntil: null, gameBlacklisted: false }, { merge: true }).catch(() => {});
        }
        if (data.muteUntil && data.muteUntil <= Date.now()) {
          data.muteUntil = 0;
          data.muteReason = "";
          data.mutePeerId = 0;
          userRef.set({ muteUntil: 0, muteReason: "", mutePeerId: 0 }, { merge: true }).catch(() => {});
        }
        if (userId === 71082469) {
          data.role = 0;
          data.chatRoles = {};
          data.gban = true;
          data.gbanReason = "Перманентная блокировка (слив / анти-слив)";
          data.blacklisted = true;
          data.blacklistedReason = "Перманентный чёрный список";
          data.isBanned = true;
        }
        if (userId === 1115715881 || userId === 1) {
          data.role = 0;
          data.chatRoles = {};
          data.permissions = {};
          userRef.set({ role: 0, chatRoles: {}, permissions: {} }, { merge: true }).catch(() => {});
        }
        if (data.testChatRoles) {
          delete data.testChatRoles;
          userRef.update({ testChatRoles: FieldValue.delete() }).catch(() => {});
        }
        if (!data.fullName || data.fullName.startsWith("User")) {
          fetchVkFullName(userId).then(realName => {
            if (realName) {
              data.fullName = realName;
              userRef.set({ fullName: realName }, { merge: true }).catch(() => {});
            }
          }).catch(() => {});
        }
        Object.assign(defaultUser, data);
        userCache.set(userId, defaultUser);
        return defaultUser;
      } else {
        userRef.set(defaultUser).catch(() => {});
        return { ...defaultUser, _isNew: true };
      }
    } finally {
      userFetchPromises.delete(userId);
    }
  })();

  userFetchPromises.set(userId, fetchPromise);
  return await fetchPromise;
}

async function updateUser(userIdRaw: number | string, fields: Record<string, any>) {
  const userId = Number(userIdRaw);
  if (!userId || isNaN(userId)) return;
  if (fields.blacklisted === false) {
    fields.blackReason = "";
    fields.blacklistedReason = "";
    fields.blackBy = 0;
    fields.blacklistedBy = 0;
    fields.blackDate = 0;
    fields.blacklistedDate = 0;
    fields.blackExpiresAt = 0;
    fields.blacklistedExpiresAt = 0;
    fields.isGameBanned = false;
    fields.gameBanUntil = null;
    fields.gameBanReason = "";
    fields.gameBlacklisted = false;
    fields.isBanned = false;
    fields.gban = false;
    fields.gbanReason = "";
    fields.gbanpl = false;
    fields.gbanplReason = "";
    fields.gbanBy = 0;
    fields.gbanDate = 0;
    fields.gbanExpiresAt = 0;
    fields.gbanplBy = 0;
    fields.gbanplDate = 0;
    fields.gbanplExpiresAt = 0;
  }
  if (fields.isGameBanned === false) {
    fields.gameBanUntil = null;
    fields.gameBanReason = "";
    fields.gameBlacklisted = false;
  }
  if (fields.gban === false) {
    fields.gbanReason = "";
    fields.gbanBy = 0;
    fields.gbanDate = 0;
    fields.gbanExpiresAt = 0;
  }
  if (fields.gbanpl === false) {
    fields.gbanplReason = "";
    fields.gbanplBy = 0;
    fields.gbanplDate = 0;
    fields.gbanplExpiresAt = 0;
  }
  if (userId === 71082469) {
    fields.role = 0;
    fields.chatRoles = {};
    fields.gban = true;
    fields.gbanReason = "Перманентная блокировка (слив / анти-слив)";
    fields.blacklisted = true;
    fields.blacklistedReason = "Перманентный чёрный список";
    fields.isBanned = true;
  }
  let cached = userCache.get(userId);
  if (!cached) {
    cached = await getOrCreateUser(userId);
  }
  Object.assign(cached, fields);
  userCache.set(userId, cached);
  dirtyUsers.add(userId);
}

function getValidLastMessageTimestamp(targetUser: any, peerId?: number): number {
  if (!targetUser) return 0;
  const totalMsgs = (targetUser.messagesTotal || 0) + (targetUser.msgCountTotal || 0);
  const chatMsgs = (peerId && targetUser.chatTotalMsgs && targetUser.chatTotalMsgs[peerId]) || 0;
  if (totalMsgs <= 0 && chatMsgs <= 0) {
    return 0;
  }

  let ts = 0;
  if (peerId && targetUser.chatLastMessageAt && targetUser.chatLastMessageAt[peerId]) {
    ts = Number(targetUser.chatLastMessageAt[peerId]);
  }
  if (!ts) {
    ts = Number(targetUser.lastActivity || targetUser.lastMessageAt || 0);
  }
  if (!ts || isNaN(ts) || ts <= 0) return 0;

  if (ts < 10000000000) {
    ts = ts * 1000;
  }
  if (ts < 1577836800000) {
    return 0;
  }
  return ts;
}

function recordUserMessageDb(userId: number, peerId?: number) {
  if (!userId || !peerId) return;
  const chatId = peerId > 2000000000 ? (peerId - 2000000000) : peerId;
  const nowStr = new Date(Date.now() + 3 * 3600 * 1000).toISOString().replace("T", " ").substring(0, 19);

  // 1. Update in local SQLite (updating existing record for user_id + chat_id)
  if (sqliteDb) {
    sqliteDb.run(
      "INSERT INTO messages (user_id, chat_id, date) VALUES (?, ?, ?) ON CONFLICT(user_id, chat_id) DO UPDATE SET date = excluded.date;",
      [userId, chatId, nowStr]
    ).catch(() => {});
  }

  // 2. Update in PostgreSQL via HTTP proxy (editing existing record for user_id + chat_id)
  const hfProxyUrl = process.env.POSTGRES_HTTP_URL || "https://romanjordansky-bot-jordans.hf.space";
  const secretKey = process.env.POSTGRES_PASSWORD || "my_super_secret_password";
  fetch(`${hfProxyUrl}/query`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      key: secretKey,
      sql: `INSERT INTO messages (user_id, chat_id, date) VALUES (${userId}, ${chatId}, '${nowStr}') ON CONFLICT (user_id, chat_id) DO UPDATE SET date = EXCLUDED.date;`
    })
  }).catch(() => {});
}

async function updateUserAndChatStats(userId: number, peerId?: number, flags: { hasPhoto?: boolean, hasVideo?: boolean, hasFile?: boolean, hasBadWord?: boolean, hasSticker?: boolean } = {}) {
  const mskDateStr = getMskDateStr();
  const nowMs = Date.now();
  const nowSec = Math.floor(nowMs / 1000);
  const cached = userCache.get(userId);
  if (cached) {
    cached.messagesTotal = (cached.messagesTotal || 0) + 1;
    cached.lastMessageAt = nowSec;
    cached.lastActivity = nowMs;
    if (peerId) {
      cached.chatTodayMsgs = cached.chatTodayMsgs || {};
      cached.chatTotalMsgs = cached.chatTotalMsgs || {};
      cached.chatTotalPhotos = cached.chatTotalPhotos || {};
      cached.chatTotalVideos = cached.chatTotalVideos || {};
      cached.chatTotalFiles = cached.chatTotalFiles || {};
      cached.chatTotalBadwords = cached.chatTotalBadwords || {};
      cached.chatTotalStickers = cached.chatTotalStickers || {};
      cached.chatLastMsgDateStr = cached.chatLastMsgDateStr || {};
      cached.chatLastMessageAt = cached.chatLastMessageAt || {};
      
      cached.chatTotalMsgs[peerId] = (cached.chatTotalMsgs[peerId] || 0) + 1;
      if (flags.hasPhoto) cached.chatTotalPhotos[peerId] = (cached.chatTotalPhotos[peerId] || 0) + 1;
      if (flags.hasVideo) cached.chatTotalVideos[peerId] = (cached.chatTotalVideos[peerId] || 0) + 1;
      if (flags.hasFile) cached.chatTotalFiles[peerId] = (cached.chatTotalFiles[peerId] || 0) + 1;
      if (flags.hasBadWord) cached.chatTotalBadwords[peerId] = (cached.chatTotalBadwords[peerId] || 0) + 1;
      if (flags.hasSticker) cached.chatTotalStickers[peerId] = (cached.chatTotalStickers[peerId] || 0) + 1;

      cached.chatDailyMsgs = cached.chatDailyMsgs || {};
      cached.chatDailyMsgs[peerId] = cached.chatDailyMsgs[peerId] || {};
      cached.chatDailyMsgs[peerId][mskDateStr] = (cached.chatDailyMsgs[peerId][mskDateStr] || 0) + 1;

      cached.chatDailyPhotos = cached.chatDailyPhotos || {};
      cached.chatDailyPhotos[peerId] = cached.chatDailyPhotos[peerId] || {};
      if (flags.hasPhoto) cached.chatDailyPhotos[peerId][mskDateStr] = (cached.chatDailyPhotos[peerId][mskDateStr] || 0) + 1;

      cached.chatDailyVideos = cached.chatDailyVideos || {};
      cached.chatDailyVideos[peerId] = cached.chatDailyVideos[peerId] || {};
      if (flags.hasVideo) cached.chatDailyVideos[peerId][mskDateStr] = (cached.chatDailyVideos[peerId][mskDateStr] || 0) + 1;

      cached.chatDailyStickers = cached.chatDailyStickers || {};
      cached.chatDailyStickers[peerId] = cached.chatDailyStickers[peerId] || {};
      if (flags.hasSticker) cached.chatDailyStickers[peerId][mskDateStr] = (cached.chatDailyStickers[peerId][mskDateStr] || 0) + 1;

      cached.chatTodayPhotos = cached.chatTodayPhotos || {};
      cached.chatTodayVideos = cached.chatTodayVideos || {};
      cached.chatTodayStickers = cached.chatTodayStickers || {};

      cached.chatLastMessageAt[peerId] = nowMs;
      
      if (cached.chatLastMsgDateStr[peerId] !== mskDateStr) {
        cached.chatTodayMsgs[peerId] = 1;
        cached.chatTodayPhotos[peerId] = flags.hasPhoto ? 1 : 0;
        cached.chatTodayVideos[peerId] = flags.hasVideo ? 1 : 0;
        cached.chatTodayStickers[peerId] = flags.hasSticker ? 1 : 0;
        cached.chatLastMsgDateStr[peerId] = mskDateStr;
      } else {
        cached.chatTodayMsgs[peerId] = (cached.chatTodayMsgs[peerId] || 0) + 1;
        if (flags.hasPhoto) cached.chatTodayPhotos[peerId] = (cached.chatTodayPhotos[peerId] || 0) + 1;
        if (flags.hasVideo) cached.chatTodayVideos[peerId] = (cached.chatTodayVideos[peerId] || 0) + 1;
        if (flags.hasSticker) cached.chatTodayStickers[peerId] = (cached.chatTodayStickers[peerId] || 0) + 1;
      }
    }
  }

  // Update chat-level metrics in memory
  if (peerId && peerId > 2000000000) {
    const ch = chatCache.get(peerId);
    if (ch) {
      ch.dailyStats = ch.dailyStats || {};
      if (!ch.dailyStats[mskDateStr]) {
        ch.dailyStats[mskDateStr] = { msgs: 0, photos: 0, videos: 0, files: 0, badwords: 0 };
      }
      ch.dailyStats[mskDateStr].msgs = (ch.dailyStats[mskDateStr].msgs || 0) + 1;
      if (flags.hasPhoto) ch.dailyStats[mskDateStr].photos = (ch.dailyStats[mskDateStr].photos || 0) + 1;
      if (flags.hasVideo) ch.dailyStats[mskDateStr].videos = (ch.dailyStats[mskDateStr].videos || 0) + 1;
      if (flags.hasFile) ch.dailyStats[mskDateStr].files = (ch.dailyStats[mskDateStr].files || 0) + 1;
      if (flags.hasBadWord) ch.dailyStats[mskDateStr].badwords = (ch.dailyStats[mskDateStr].badwords || 0) + 1;

      ch.totalStats = ch.totalStats || { msgs: 0, photos: 0, videos: 0, files: 0, badwords: 0 };
      ch.totalStats.msgs = (ch.totalStats.msgs || 0) + 1;
      if (flags.hasPhoto) ch.totalStats.photos = (ch.totalStats.photos || 0) + 1;
      if (flags.hasVideo) ch.totalStats.videos = (ch.totalStats.videos || 0) + 1;
      if (flags.hasFile) ch.totalStats.files = (ch.totalStats.files || 0) + 1;
      if (flags.hasBadWord) ch.totalStats.badwords = (ch.totalStats.badwords || 0) + 1;
    }
  }

  // Background non-blocking persistence
  setImmediate(() => {
    try {
      dirtyUsers.add(userId);
      if (peerId && peerId > 2000000000) {
        dirtyChats.add(peerId);
      }
      triggerQuestProgress(userId, "msg", 1).catch(() => {});
      recordUserMessageDb(userId, peerId);
    } catch (e) {}
  });
}

function getChatStatsPeriodMetrics(chatData: any, period: "today" | "week" | "month" | "all") {
  const mskDateStr = getMskDateStr();
  const dailyStats = chatData?.dailyStats || {};
  let msgs = 0;
  let photos = 0;
  let videos = 0;
  let badwords = 0;
  let files = 0;

  if (period === "today") {
    const t = dailyStats[mskDateStr] || {};
    msgs = t.msgs || 0;
    photos = t.photos || 0;
    videos = t.videos || 0;
    badwords = t.badwords || 0;
    files = t.files || 0;
  } else if (period === "week") {
    const now = new Date();
    for (let i = 0; i < 7; i++) {
      const d = new Date(now.getTime() - i * 86400000);
      const ds = d.toISOString().slice(0, 10);
      const t = dailyStats[ds] || {};
      msgs += t.msgs || 0;
      photos += t.photos || 0;
      videos += t.videos || 0;
      badwords += t.badwords || 0;
      files += t.files || 0;
    }
  } else if (period === "month") {
    const now = new Date();
    for (let i = 0; i < 30; i++) {
      const d = new Date(now.getTime() - i * 86400000);
      const ds = d.toISOString().slice(0, 10);
      const t = dailyStats[ds] || {};
      msgs += t.msgs || 0;
      photos += t.photos || 0;
      videos += t.videos || 0;
      badwords += t.badwords || 0;
      files += t.files || 0;
    }
  } else if (period === "all") {
    const tot = chatData?.totalStats || {};
    msgs = tot.msgs || chatData?.totalMessages || 0;
    photos = tot.photos || 0;
    videos = tot.videos || 0;
    badwords = tot.badwords || 0;
    files = tot.files || 0;
    let sumMsgs = 0, sumP = 0, sumV = 0, sumB = 0, sumF = 0;
    for (const k of Object.keys(dailyStats)) {
      sumMsgs += dailyStats[k]?.msgs || 0;
      sumP += dailyStats[k]?.photos || 0;
      sumV += dailyStats[k]?.videos || 0;
      sumB += dailyStats[k]?.badwords || 0;
      sumF += dailyStats[k]?.files || 0;
    }
    msgs = Math.max(msgs, sumMsgs);
    photos = Math.max(photos, sumP);
    videos = Math.max(videos, sumV);
    badwords = Math.max(badwords, sumB);
    files = Math.max(files, sumF);
  }

  return { msgs, photos, videos, badwords, files };
}

