function parseDurationString(str: string): { ms: number; text: string } {
  if (!str) return { ms: 7 * 86400 * 1000, text: "7 дней" };
  const lower = str.trim().toLowerCase();
  
  const numMatch = lower.match(/^(\d+)\s*([a-zа-яё]+)?$/);
  if (numMatch) {
    const val = parseInt(numMatch[1]);
    const unit = (numMatch[2] || "").toLowerCase();
    if (!unit || ["d", "д", "дн", "день", "дня", "дней"].includes(unit)) {
      return { ms: val * 86400 * 1000, text: `${val} ${pluralizeRu(val, "день", "дня", "дней")}` };
    } else if (["w", "нед", "неделя", "недели", "недель", "неделю"].includes(unit)) {
      return { ms: val * 7 * 86400 * 1000, text: `${val} ${pluralizeRu(val, "неделю", "недели", "недель")}` };
    } else if (["h", "ч", "час", "часа", "часов"].includes(unit)) {
      return { ms: val * 3600 * 1000, text: `${val} ${pluralizeRu(val, "час", "часа", "часов")}` };
    } else if (["m", "мин", "минут", "минуты"].includes(unit)) {
      return { ms: val * 60 * 1000, text: `${val} ${pluralizeRu(val, "минуту", "минуты", "минут")}` };
    }
  }
  return { ms: 7 * 86400 * 1000, text: "7 дней" };
}

async function buildNeactivelistData(peerId: number, durationStr: string, page: number = 1, authorId: number = 0) {
  const { ms: durationMs, text: durationText } = parseDurationString(durationStr);
  const nowMs = Date.now();
  const membersRes = await getChatMembers(peerId).catch(() => ({ items: [], profiles: [] }));
  const items = membersRes.items || [];
  const profilesMap = new Map<number, any>();
  (membersRes.profiles || []).forEach((p: any) => profilesMap.set(p.id, p));

  const inactiveUsers: { id: number; name: string; lastMsgTs: number }[] = [];

  for (const item of items) {
    const uId = item.member_id || item.id;
    if (!uId || uId <= 0) continue;
    const u = userCache.get(uId) || {};
    let lastMsgTs = 0;
    if (u.chatLastMessageAt && u.chatLastMessageAt[peerId]) {
      lastMsgTs = u.chatLastMessageAt[peerId];
    } else if (u.lastActivity) {
      lastMsgTs = u.lastActivity;
    } else if (u.lastMessageAt) {
      lastMsgTs = u.lastMessageAt * 1000;
    }

    const elapsed = lastMsgTs > 0 ? (nowMs - lastMsgTs) : Infinity;
    if (elapsed >= durationMs) {
      let name = "Участник";
      const prof = profilesMap.get(uId);
      if (prof) {
        name = `${prof.first_name} ${prof.last_name}`;
      } else if (u.first_name) {
        name = `${u.first_name} ${u.last_name || ""}`.trim();
      }
      inactiveUsers.push({ id: uId, name, lastMsgTs });
    }
  }

  inactiveUsers.sort((a, b) => a.lastMsgTs - b.lastMsgTs);

  const total = inactiveUsers.length;
  const pageSize = 15;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const curPage = Math.min(Math.max(1, page), totalPages);
  const startIdx = (curPage - 1) * pageSize;
  const pageUsers = inactiveUsers.slice(startIdx, startIdx + pageSize);

  let text = `Список пользователей которые не писали в беседу больше ${durationText} (Всего: ${total}):

`;
  if (pageUsers.length === 0) {
    text += "Неактивных пользователей за данный период не найдено.";
  } else {
    pageUsers.forEach((u, idx) => {
      const num = startIdx + idx + 1;
      const mention = formatUserMention(u.id, String(u.name), "nom");
      let dateStr = "Никогда";
      if (u.lastMsgTs > 0) {
        dateStr = formatMskDate(u.lastMsgTs);
      }
      text += `${num}. ${mention} | Последнее сообщение - ${dateStr}
`;
    });
  }

  const buttons: any[] = [];
  if (totalPages > 1) {
    const prevPage = curPage > 1 ? curPage - 1 : totalPages;
    const nextPage = curPage < totalPages ? curPage + 1 : 1;
    buttons.push([
      {
        action: {
          type: "callback",
          label: "◀ Назад",
          payload: JSON.stringify({ cmd: "neactive_page", page: prevPage, dur: durationStr, peerId, authorId })
        },
        color: "secondary"
      },
      {
        action: {
          type: "callback",
          label: `Стр. ${curPage}/${totalPages}`,
          payload: JSON.stringify({ cmd: "neactive_page", page: curPage, dur: durationStr, peerId, authorId })
        },
        color: "secondary"
      },
      {
        action: {
          type: "callback",
          label: "Вперёд ▶",
          payload: JSON.stringify({ cmd: "neactive_page", page: nextPage, dur: durationStr, peerId, authorId })
        },
        color: "secondary"
      }
    ]);
  }

  return { text, keyboard: { inline: true, buttons } };
}

async function getChatTopResponseData(peerId: number, category: string, authorId: number, page: number = 1) {
  const usersWithActivity: { id: number; name: string; count: number }[] = [];
  
  const membersRes = await getChatMembers(peerId).catch(() => ({ items: [], profiles: [] }));
  const profileMap = new Map<number, string>();
  for (const p of (membersRes.profiles || [])) {
    profileMap.set(p.id, `${p.first_name || ''} ${p.last_name || ''}`.trim());
  }

  const memberIdsSet = new Set<number>();
  for (const m of (membersRes.items || [])) {
    if (m.member_id > 0) memberIdsSet.add(m.member_id);
  }

  for (const [uId, u] of userCache.entries()) {
    if (uId <= 0) continue;
    const hasChatActivity = (u.chatTotalMsgs && u.chatTotalMsgs[peerId]) || (u.chatTodayMsgs && u.chatTodayMsgs[peerId]) || memberIdsSet.has(uId);
    if (!hasChatActivity) continue;

    let cnt = 0;
    if (category === "msgs") {
      cnt = (u.chatTotalMsgs && u.chatTotalMsgs[peerId]) || (u.chatTodayMsgs && u.chatTodayMsgs[peerId]) || 0;
    } else if (category === "photos") {
      cnt = (u.chatTotalPhotos && u.chatTotalPhotos[peerId]) || 0;
    } else if (category === "videos") {
      cnt = (u.chatTotalVideos && u.chatTotalVideos[peerId]) || 0;
    } else if (category === "files") {
      cnt = (u.chatTotalFiles && u.chatTotalFiles[peerId]) || 0;
    } else if (category === "badwords") {
      cnt = (u.chatTotalBadwords && u.chatTotalBadwords[peerId]) || 0;
    } else if (category === "voice") {
      cnt = (u.chatTotalVoice && u.chatTotalVoice[peerId]) || 0;
    } else if (category === "stickers") {
      cnt = (u.chatTotalStickers && u.chatTotalStickers[peerId]) || 0;
    } else if (category === "balance") {
      cnt = u.balance || 0;
    } else if (category === "rep") {
      cnt = u.reputation || 0;
    }

    if (cnt > 0) {
      const name = profileMap.get(uId) || u.fullName || u.nick || `User${uId}`;
      usersWithActivity.push({ id: uId, name, count: cnt });
    }
  }

  usersWithActivity.sort((a, b) => b.count - a.count);
  const top10 = usersWithActivity.slice(0, 10);

  const categoryTitles: Record<string, { title: string; unit: string }> = {
    msgs: { title: "сообщениям", unit: "сообщ." },
    photos: { title: "фотографиям", unit: "фото" },
    videos: { title: "видео", unit: "видео" },
    files: { title: "файлам", unit: "файлов" },
    badwords: { title: "запретным словам", unit: "слов" },
    voice: { title: "голосовым сообщениям", unit: "ГС" },
    stickers: { title: "стикерам", unit: "стикеров" },
    balance: { title: "балансу", unit: "$" },
    rep: { title: "репутации", unit: "ед." }
  };

  const catInfo = categoryTitles[category] || categoryTitles.msgs;
  let text = `🏆 Топ беседы по ${catInfo.title}:

`;

  if (top10.length === 0) {
    text += `В этой категории пока нет активности. Будьте первыми!`;
  } else {
    top10.forEach((item, idx) => {
      text += `${idx + 1}. ${formatUserMention(item.id, String(item.name), "nom", false, true)} — ${formatNum(item.count)} ${catInfo.unit}
`;
    });
  }

  const allCats = [
    { label: "💬 Сообщения", cat: "msgs" },
    { label: "📷 Фото", cat: "photos" },
    { label: "🎥 Видео", cat: "videos" },
    { label: "📁 Файлы", cat: "files" },
    { label: "🎙️ Голосовые", cat: "voice" },
    { label: "😄 Стикеры", cat: "stickers" },
    { label: "🤬 Запрет. слова", cat: "badwords" },
    { label: "💰 Баланс", cat: "balance" },
    { label: "👑 Репутация", cat: "rep" },
    { label: "🤝 Благотворительность", cmd: "charity_top" }
  ];

  const pageSize = 8;
  const totalPages = Math.ceil(allCats.length / pageSize);
  const currentCats = allCats.slice((page - 1) * pageSize, page * pageSize);

  const buttons: any[][] = [];
  for (let i = 0; i < currentCats.length; i += 2) {
    const row: any[] = [];
    const item1 = currentCats[i];
    row.push({
      action: { 
        type: "callback", 
        label: item1.label, 
        payload: item1.cmd ? JSON.stringify({ cmd: item1.cmd, peerId, authorId }) : JSON.stringify({ cmd: "chat_top_cat", cat: item1.cat, peerId, authorId, page }) 
      },
      color: "secondary"
    });
    if (i + 1 < currentCats.length) {
      const item2 = currentCats[i + 1];
      row.push({
        action: { 
          type: "callback", 
          label: item2.label, 
          payload: item2.cmd ? JSON.stringify({ cmd: item2.cmd, peerId, authorId }) : JSON.stringify({ cmd: "chat_top_cat", cat: item2.cat, peerId, authorId, page }) 
        },
        color: "secondary"
      });
    }
    buttons.push(row);
  }

  if (totalPages > 1) {
    const navRow: any[] = [];
    if (page > 1) navRow.push({ action: { type: "callback", label: "⬅️", payload: JSON.stringify({ cmd: "chat_top_cat", cat: category, peerId, authorId, page: page - 1 }) }, color: "secondary" });
    if (page < totalPages) navRow.push({ action: { type: "callback", label: "➡️", payload: JSON.stringify({ cmd: "chat_top_cat", cat: category, peerId, authorId, page: page + 1 }) }, color: "secondary" });
    buttons.push(navRow);
  }

  return { text, keyboard: { inline: true, buttons } };
}

