app.post("/api/panel/broadcasts/send", async (req, res) => {
  const { title, text, target } = req.body || {};
  if (!text) return res.status(400).json({ error: "Текст обязателен" });
  try {
    let sentCount = 0;
    const msg = `🔔 РАССЫЛКА: ${title || 'Уведомление'}

${text}`;
    if (target === 'all_chats') {
      const broadcastKb = {
        inline: true,
        buttons: [[
          { action: { type: "callback", label: "Выключить рассылки", payload: JSON.stringify({ cmd: "toggle_broadcasts", action: "off" }) }, color: "negative" }
        ]]
      };
      for (const [peerId, cData] of chatCache.entries()) {
        try {
          if (cData && (cData.disableBroadcasts || cData.broadcastsEnabled === false)) continue;
          await sendVkMessage(VK_TOKEN, peerId, msg, { keyboard: JSON.stringify(broadcastKb) });
          sentCount++;
          await new Promise(r => setTimeout(r, 60));
        } catch(e) {}
      }
    } else {
      for (const [userId] of userCache.entries()) {
        try {
          await sendVkMessage(VK_TOKEN, userId, msg);
          sentCount++;
          await new Promise(r => setTimeout(r, 60));
        } catch(e) {}
      }
    }
    res.json({ success: true, sentCount });
  } catch(e: any) {
    res.status(500).json({ error: e.message });
  }
});

