function getRoleDisplayName(role: number): string {
  if (role >= 12) return "Владелец чат-менеджера";
  if (role === 11) return "Зам. Владельца чат-менеджера";
  if (role === 10.5) return "Главный Руководитель";
  if (role === 10) return "Руководитель чат-менеджера";
  if (role === 9) return "Осн. Зам. Руководителя";
  if (role === 8) return "Зам. Руководителя";
  if (role === 7.6) return "Главный Агент Поддержки Чат-менеджера";
  if (role === 7.5) return "Зам. Главного Агента Поддержки Чат-менеджера";
  if (role === 7.4) return "Агент Поддержки Чат-менеджера";
  if (role === 7.3) return "Главный тех. специалист";
  if (role === 7.2) return "Куратор тех. специалистов";
  if (role === 7.1) return "Тех. Специалист";
  if (role >= 6) return "Владелец беседы";
  if (role === 5) return "Руководитель беседы";
  if (role === 4) return "Главный Администратор";
  if (role === 3) return "Администратор";
  if (role === 2) return "Старший Модератор";
  if (role === 1) return "Модератор";
  return "Пользователь";
}

async function logBotAction(entry: {
  type: "adm" | "mute" | "ban" | "warn" | "kick" | "game" | "general";
  peerId?: number;
  userId: number;
  targetId?: number;
  text: string;
  details?: any;
}) {
  try {
    const d = getMskDate();
    const day = String(d.getDate()).padStart(2, "0");
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const year = d.getFullYear();
    const hours = String(d.getHours()).padStart(2, "0");
    const mins = String(d.getMinutes()).padStart(2, "0");
    const secs = String(d.getSeconds()).padStart(2, "0");
    const dateStr = `${day}.${month}.${year} ${hours}:${mins}:${secs}`;

    const logItem: BotLogEntry = {
      ...entry,
      timestamp: Date.now(),
      dateStr,
    };
    recentLogsMemory.unshift(logItem);
    if (recentLogsMemory.length > 2000) {
      recentLogsMemory.pop();
    }
    const isCritical = ["gban", "blacklisted", "gbanpl", "role_change"].includes((entry as any).action || entry.type);
    if (isCritical) {
      firestoreDb.collection("bot_logs").add(logItem).catch(() => {});
    }
  } catch (e) {}
}

function parseLogTimeFilter(args: string[]): { sinceMs?: number; label: string } | null {
  if (!args || args.length === 0) return null;
  const fullStr = args.join(" ").trim().toLowerCase();
  
  if (fullStr === "все" || fullStr === "всё" || fullStr === "все время" || fullStr === "всё время" || fullStr === "весь" || fullStr === "all") {
    return { sinceMs: 0, label: "за всё время" };
  }

  // Check matching like "1 неделя", "2 недели", "1 день", "3 дня", "5 часов", "30 минут", "1 месяц", "1 год"
  // or "1н", "1д", "1ч", "1w", "1d", "1h", "1m", "1y"
  const m1 = fullStr.match(/^(\d+)\s*([a-zа-яё]+)$/i);
  if (m1) {
    const count = parseInt(m1[1], 10);
    const unit = m1[2].toLowerCase();
    let ms = 0;
    let label = "";

    if (unit.startsWith("сек") || unit === "s" || unit === "с") {
      ms = count * 1000;
      label = `${count} ${pluralizeRu(count, "секунду", "секунды", "секунд")}`;
    } else if (unit.startsWith("мин") || unit === "m" || unit === "м") {
      ms = count * 60 * 1000;
      label = `${count} ${pluralizeRu(count, "минуту", "минуты", "минут")}`;
    } else if (unit.startsWith("час") || unit === "h" || unit === "ч") {
      ms = count * 3600 * 1000;
      label = `${count} ${pluralizeRu(count, "час", "часа", "часов")}`;
    } else if (unit.startsWith("ден") || unit.startsWith("дня") || unit.startsWith("дне") || unit === "d" || unit === "д") {
      ms = count * 24 * 3600 * 1000;
      label = `${count} ${pluralizeRu(count, "день", "дня", "дней")}`;
    } else if (unit.startsWith("нед") || unit === "w" || unit === "н") {
      ms = count * 7 * 24 * 3600 * 1000;
      label = `${count} ${pluralizeRu(count, "неделю", "недели", "недель")}`;
    } else if (unit.startsWith("мес") || unit === "mon") {
      ms = count * 30 * 24 * 3600 * 1000;
      label = `${count} ${pluralizeRu(count, "месяц", "месяца", "месяцев")}`;
    } else if (unit.startsWith("год") || unit.startsWith("лет") || unit.startsWith("года") || unit === "y" || unit === "г") {
      ms = count * 365 * 24 * 3600 * 1000;
      label = `${count} ${pluralizeRu(count, "год", "года", "лет")}`;
    }

    if (ms > 0) {
      return { sinceMs: Date.now() - ms, label: `за ${label}` };
    }
  }

  // Check standalone units like "неделя" (1 неделя), "день" (1 день), "месяц", "год", "час"
  if (fullStr === "неделя" || fullStr === "неделю" || fullStr === "week") {
    return { sinceMs: Date.now() - 7 * 24 * 3600 * 1000, label: "за 1 неделю" };
  }
  if (fullStr === "день" || fullStr === "day" || fullStr === "сутки") {
    return { sinceMs: Date.now() - 24 * 3600 * 1000, label: "за 1 день" };
  }
  if (fullStr === "час" || fullStr === "hour") {
    return { sinceMs: Date.now() - 3600 * 1000, label: "за 1 час" };
  }
  if (fullStr === "месяц" || fullStr === "month") {
    return { sinceMs: Date.now() - 30 * 24 * 3600 * 1000, label: "за 1 месяц" };
  }
  if (fullStr === "год" || fullStr === "year") {
    return { sinceMs: Date.now() - 365 * 24 * 3600 * 1000, label: "за 1 год" };
  }

  return null;
}

async function getFilteredLogs(filter: {
  type?: string;
  peerId?: number;
  userId?: number;
  targetId?: number;
  isGlobal?: boolean;
  sinceMs?: number;
}): Promise<BotLogEntry[]> {
  const minTs = typeof filter.sinceMs === "number" ? filter.sinceMs : 0;
  const allLogs: BotLogEntry[] = [];
  const seenIds = new Set<string>();

  const modTypes = ["mute", "ban", "warn", "kick"];

  try {
    const snap = await firestoreDb.collection("bot_logs").get();
    for (const doc of snap.docs) {
      const data = doc.data() as BotLogEntry;
      if (!data) continue;
      const ts = data.timestamp || 0;
      if (minTs > 0 && ts < minTs) continue;

      if (!filter.isGlobal && filter.peerId && filter.peerId > 0 && data.peerId !== filter.peerId) continue;
      if (filter.userId && filter.userId > 0 && data.userId !== filter.userId && data.targetId !== filter.userId) continue;
      if (filter.targetId && filter.targetId > 0 && data.targetId !== filter.targetId && data.userId !== filter.targetId) continue;
      
      if (filter.type === "moderation") {
        if (!modTypes.includes(data.type)) continue;
      } else if (filter.type && filter.type !== "all" && data.type !== filter.type) {
        continue;
      }

      const id = doc.id || `${ts}_${data.userId}_${data.text}`;
      if (!seenIds.has(id)) {
        seenIds.add(id);
        allLogs.push({ id, ...data });
      }
    }
  } catch (e) {}

  for (const l of recentLogsMemory) {
    if (minTs > 0 && l.timestamp < minTs) continue;
    if (!filter.isGlobal && filter.peerId && filter.peerId > 0 && l.peerId !== filter.peerId) continue;
    if (filter.userId && filter.userId > 0 && l.userId !== filter.userId && l.targetId !== filter.userId) continue;
    if (filter.targetId && filter.targetId > 0 && l.targetId !== filter.targetId && l.userId !== filter.targetId) continue;
    
    if (filter.type === "moderation") {
      if (!modTypes.includes(l.type)) continue;
    } else if (filter.type && filter.type !== "all" && l.type !== filter.type) {
      continue;
    }

    const id = `${l.timestamp}_${l.userId}_${l.text}`;
    if (!seenIds.has(id)) {
      seenIds.add(id);
      allLogs.push(l);
    }
  }

  allLogs.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
  return allLogs;
}

function formatLogTimeAMPM(timestamp: number): string {
  const d = new Date(timestamp + 3 * 3600000); // MSK
  let hours = d.getUTCHours();
  const mins = String(d.getUTCMinutes()).padStart(2, "0");
  const secs = String(d.getUTCSeconds()).padStart(2, "0");
  const ampm = hours >= 12 ? "PM" : "AM";
  hours = hours % 12;
  hours = hours ? hours : 12; // the hour '0' should be '12'
  const hStr = String(hours).padStart(2, "0");
  return `${hStr}:${mins}:${secs} ${ampm}`;
}

function formatLogDate(timestamp: number): string {
  const d = new Date(timestamp + 3 * 3600000); // MSK
  const day = String(d.getUTCDate()).padStart(2, "0");
  const month = String(d.getUTCMonth() + 1).padStart(2, "0");
  const year = d.getUTCFullYear();
  return `${day}.${month}.${year}`;
}

function cleanLogAction(rawText: string): string {
  if (!rawText) return "";
  let s = rawText.trim();
  // Remove leading user mention: [id123|Name] or [club123|Name] or @id123
  s = s.replace(/^\[(?:id|club)\d+\|[^\]]+\]\s*/i, "");
  s = s.replace(/^@(?:id|club)\d+\s*/i, "");

  // Remove prepositions with target mentions like "с [id...|...]" or "у [id...|...]" or "от [id...|...]"
  s = s.replace(/\b(?:с|со|у|от|к|для)\s+\[(?:id|club)\d+\|[^\]]+\]\s*/gi, "");
  // Remove any remaining mentions [id...|...] or [club...|...]
  s = s.replace(/\[(?:id|club)\d+\|[^\]]+\]\s*/gi, "");

  // Remove standalone target words like "пользователю", "пользователя", "пользователь"
  s = s.replace(/\b(?:с|со|у|от|к|для)\s+пользовател[яеюи]\b\s*/gi, "");
  s = s.replace(/\s+пользовател[яеюи]\b/gi, "");

  // Clean multiple spaces and trim
  s = s.replace(/\s{2,}/g, " ").trim();

  // Capitalize first letter
  if (s.length > 0) {
    s = s.charAt(0).toUpperCase() + s.slice(1);
  }
  return s;
}

