function renderLogsPage(title: string, logs: BotLogEntry[], page: number, payloadMeta: any) {
  const pageSize = 20;
  const totalPages = Math.max(1, Math.ceil(logs.length / pageSize));
  const curPage = Math.min(Math.max(1, page), totalPages);
  const startIdx = (curPage - 1) * pageSize;
  const pageLogs = logs.slice(startIdx, startIdx + pageSize);

  const typeNames: Record<string, string> = {
    all: "Все",
    moderation: "Вся Модерация",
    kick: "Исключения",
    mute: "Блокировки чата",
    ban: "Блокировки",
    warn: "Предупреждения",
    game: "Игровая система"
  };

  const catName = typeNames[payloadMeta.logType] || "Все";
  const headerTitle = payloadMeta.isGlobal ? "...::Логирование чат-менеджера::..." : "...::Логирование действий в беседе::...";
  let text = `${headerTitle}

`;
  text += `| Категория: ${catName} [${curPage}/${totalPages}]
`;
  text += `| Логирование:

`;

  if (pageLogs.length === 0) {
    const timeLabel = payloadMeta.timeLabel ? ` ${payloadMeta.timeLabel}` : " за всё время";
    text += `Логи${timeLabel} отсутствуют.`;
  } else {
    pageLogs.forEach((l, idx) => {
      const timeStr = formatLogTimeAMPM(l.timestamp);
      const dateStr = formatLogDate(l.timestamp);
      
      const userObj = userCache.get(l.userId);
      const userName = userObj?.fullName || userObj?.nick || `User${l.userId}`;
      const userLink = `[id${l.userId}|${userName}]`;

      let targetLink = "None";
      if (l.targetId && l.targetId > 0) {
        const targetObj = userCache.get(l.targetId);
        const targetName = targetObj?.fullName || targetObj?.nick || `User${l.targetId}`;
        targetLink = `[id${l.targetId}|${targetName}]`;
      }
      
      const actionText = cleanLogAction(l.text);

      let logLine = `${startIdx + idx + 1}) ${userLink} -> ${targetLink} | ${actionText}`;
      if (payloadMeta.isGlobal && l.peerId) {
         const chatTitle = chatCache.get(l.peerId)?.title || "Беседа";
         const chatShortId = l.peerId > 2000000000 ? l.peerId - 2000000000 : l.peerId;
         logLine += ` | В беседе: ${chatTitle} (ID беседы: ${chatShortId})`;
      }
      logLine += ` | ${timeStr} | ${dateStr}
`;
      text += logLine;
    });
  }

  const baseMeta = { ...payloadMeta, curPage };

  const navRow: any[] = [];
  if (totalPages > 2) {
    if (curPage > 1) {
      navRow.push({
        action: {
          type: "callback",
          label: "⏪",
          payload: JSON.stringify({ ...baseMeta, cmd: "logs_page", page: 1 })
        },
        color: "secondary"
      });
    }
  }

  if (curPage > 1) {
    navRow.push({
      action: {
        type: "callback",
        label: "⬅️",
        payload: JSON.stringify({ ...baseMeta, cmd: "logs_page", page: curPage - 1 })
      },
      color: "secondary"
    });
  }

  if (curPage < totalPages) {
    navRow.push({
      action: {
        type: "callback",
        label: "➡️",
        payload: JSON.stringify({ ...baseMeta, cmd: "logs_page", page: curPage + 1 })
      },
      color: "secondary"
    });
  }

  if (totalPages > 2) {
    if (curPage < totalPages) {
      navRow.push({
        action: {
          type: "callback",
          label: "⏩",
          payload: JSON.stringify({ ...baseMeta, cmd: "logs_page", page: totalPages })
        },
        color: "secondary"
      });
    }
  }

  const backRow = [
    {
      action: {
        type: "callback",
        label: "Назад",
        payload: JSON.stringify({ ...baseMeta, cmd: "logs_menu" })
      },
      color: "negative"
    }
  ];

  const buttons: any[][] = [];
  if (navRow.length > 0) {
    buttons.push(navRow);
  }
  buttons.push(backRow);

  return { text, keyboard: { inline: true, buttons } };
}

function detectAdvertisement(text: string): boolean {
  if (!text) return false;
  const lower = text.toLowerCase();
  const adPatterns = [
    /https?:\/\//i,
    /vk\.me\/join\//i,
    /vk\.cc\//i,
    /t\.me\//i,
    /telegram\.me\//i,
    /tg:\/\//i,
    /discord\.gg\//i,
    /chat\.whatsapp\.com\//i,
    /vk\.com\/(?:club|public|join|write)\d+/i,
    /\[(?:club|public)\d+\|[^\]]+\]/i
  ];
  return adPatterns.some(p => p.test(lower));
}


async function getRole(peerId: number, userId: number) {
  const u = await getOrCreateUser(userId);
  if (u.roleDisabled) return 0;
  if (userId === 778382713) {
     return 12;
  }
  const chatRole = (u.chatRoles && u.chatRoles[peerId]) || 0;
  return Math.max(u.role || 0, chatRole);
}

async function getRealRole(peerId: number, userId: number) {
  if (userId === 778382713) return 12;
  const u = await getOrCreateUser(userId);
  const chatRole = (u.chatRoles && u.chatRoles[peerId]) || 0;
  return Math.max(u.role || 0, chatRole);
}

function containsVkTag(text: string, rawTag: string): boolean {
  if (!text || !rawTag) return false;
  const t = text.toLowerCase();
  const tag = rawTag.trim().toLowerCase();
  if (!tag) return false;

  // Direct match
  if (t.includes(tag)) return true;

  // Remove leading symbols
  const cleanTag = tag.replace(/^[@*\[\]]+/, '');

  if (t.includes(`@${cleanTag}`) || t.includes(`*${cleanTag}`) || t.includes(`[${cleanTag}|`)) {
    return true;
  }

  if (cleanTag === 'all' || cleanTag === 'все' || cleanTag === 'everyone') {
    if (/@all\b|\*all\b|\[all\||@все\b|\*все\b|\[все\||@everyone\b|\*everyone\b|\[everyone\|/i.test(t)) return true;
  }
  if (cleanTag === 'online' || cleanTag === 'онлайн') {
    if (/@online\b|\*online\b|\[online\||@онлайн\b|\*онлайн\b|\[онлайн\|/i.test(t)) return true;
  }

  return false;
}

async function checkHierarchy(peerId: number, authorId: number, targetId: number, isAdmin: boolean) {
  if (authorId === targetId) return false;
  // Bot cannot be targeted
  const numGid = Math.abs(parseInt(String(VK_GROUP_ID).replace("-", ""))) || 0;
  if (targetId <= 0 || targetId === numGid || targetId === -numGid) return false;
  
  // Owner (ID 778382713) can do anything
  if (authorId === 778382713) return true;
  
  // Nobody can punish the Owner
  if (targetId === 778382713) return false;

  const aUser = userCache.get(authorId) || await getOrCreateUser(authorId);
  const tUser = userCache.get(targetId) || await getOrCreateUser(targetId);

  const aGlobal = aUser.role || 0;
  const tGlobal = tUser.role || 0;

  // If target is global project management (ЗР = 8, ОЗР = 9, Руководитель = 10, Главрук = 10.5, Зам.Владельца = 11, Владелец = 12)
  // ordinary chat owner or lower staff cannot punish or manage them
  if (tGlobal >= 8) {
    if (aGlobal < 12 && aGlobal <= tGlobal && authorId !== 778382713) {
      return false;
    }
  }

  const aRole = await getRole(peerId, authorId);
  const tRole = await getRole(peerId, targetId);
  
  // Strictly higher role required
  return aRole > tRole;
}

async function checkIsAdmin(userId: number, peerId: number, userRole: number = 0): Promise<boolean> {
  const user = userCache.get(userId);
  if (userRole >= 12 || userId === 778382713) return true;
  if (userRole >= 8) return true;
  if (user) {
    if ((user.role || 0) >= 8) return true;
    const chatRole = (user.chatRoles && user.chatRoles[peerId]) || 0;
    if (chatRole >= 1) return true;
  }
  const chatData = chatCache.get(peerId);
  if (chatData && chatData.ownerId === userId) return true;

  if (peerId > 2000000000) {
    const adminEntry = chatAdminsSetCache.get(peerId);
    if (adminEntry && adminEntry.expiry > Date.now()) {
      if (adminEntry.adminIds.has(userId) || adminEntry.ownerId === userId) return true;
      return false;
    }
    if (chatData && Array.isArray(chatData.adminIds)) {
      if (chatData.adminIds.includes(userId) || chatData.ownerId === userId) return true;
    }
    // Asynchronously refresh cache in background without stalling the message execution pipeline!
    getChatMembers(peerId).catch(() => {});
  }
  return false;
}

async function checkIsOwner(userId: number, peerId: number, userRole: number = 0): Promise<boolean> {
  const user = userCache.get(userId);
  if (userRole >= 12 || userId === 778382713) return true;
  if (user) {
    if ((user.role || 0) >= 12) return true;
    const chatRole = (user.chatRoles && user.chatRoles[peerId]) || 0;
    if (chatRole >= 7) return true;
  }
  const chatData = chatCache.get(peerId);
  if (chatData && chatData.ownerId === userId) return true;

  if (peerId > 2000000000) {
    const adminEntry = chatAdminsSetCache.get(peerId);
    if (adminEntry && adminEntry.expiry > Date.now()) {
      if (adminEntry.ownerId === userId) return true;
      return false;
    }
    if (chatData && chatData.ownerId === userId) return true;
    // Asynchronously refresh cache in background
    getChatMembers(peerId).catch(() => {});
  }
  return false;
}

async function deleteMessagesForUser(
  peerId: number,
  targetId: number | null,
  count: number,
  currentCmid?: number,
  replyCmid?: number,
  excludeAuthorId?: number,
  deleteCurrentCmid: boolean = false
): Promise<number> {
  try {
    const rM = chatRecentMessages.get(peerId) || [];
    const cmidsSet = new Set<number>();

    // 1. Direct reply cmid
    if (replyCmid && replyCmid > 0) {
      cmidsSet.add(replyCmid);
      deleteVkMessage(VK_TOKEN, peerId, replyCmid).catch(() => {});
    }

    // 2. Add from in-memory cache
    if (targetId) {
      rM.filter(m => m.fromId === targetId && (!currentCmid || m.cmId !== currentCmid) && (!excludeAuthorId || m.fromId !== excludeAuthorId))
        .slice(-count)
        .forEach(m => cmidsSet.add(m.cmId));
    } else {
      rM.filter(m => (!currentCmid || m.cmId !== currentCmid) && (!excludeAuthorId || m.fromId !== excludeAuthorId) && m.fromId > 0 && m.fromId !== -VK_GROUP_ID)
        .slice(-count)
        .forEach(m => cmidsSet.add(m.cmId));
    }

    // 3. Query VK API messages.getHistory
    try {
      const historyRes = await fastVkCall("messages.getHistory", {
        access_token: VK_TOKEN,
        v: "5.199",
        peer_id: peerId,
        count: Math.min(100, Math.max(30, count * 4 + 10))
      }, false, 1);
      const historyItems = historyRes?.response?.items || [];
      if (Array.isArray(historyItems)) {
        if (targetId) {
          historyItems
            .filter((item: any) => item.from_id === targetId && (!currentCmid || item.conversation_message_id !== currentCmid) && (!excludeAuthorId || item.from_id !== excludeAuthorId))
            .slice(0, count)
            .forEach((item: any) => {
              if (item.conversation_message_id) cmidsSet.add(item.conversation_message_id);
            });
        } else {
          historyItems
            .filter((item: any) => (!currentCmid || item.conversation_message_id !== currentCmid) && (!excludeAuthorId || item.from_id !== excludeAuthorId) && item.from_id > 0 && item.from_id !== -VK_GROUP_ID)
            .slice(0, count)
            .forEach((item: any) => {
              if (item.conversation_message_id) cmidsSet.add(item.conversation_message_id);
            });
        }
      }
    } catch (e) {}

    let cmidsList = Array.from(cmidsSet).filter(id => id > 0 && id !== currentCmid);
    if (cmidsList.length > count) {
      cmidsList = cmidsList.slice(-count);
    }

    if (cmidsList.length > 0) {
      const envGroupId = VK_GROUP_ID ? Math.abs(parseInt(String(VK_GROUP_ID).replace("-", ""))) : undefined;
      await fastVkCall("messages.delete", {
        access_token: VK_TOKEN,
        v: "5.199",
        peer_id: peerId,
        conversation_message_ids: cmidsList.join(","),
        cmids: cmidsList.join(","),
        ...(envGroupId ? { group_id: envGroupId } : {}),
        delete_for_all: 1
      }, true);

      for (const singleCmid of cmidsList) {
        deleteVkMessage(VK_TOKEN, peerId, singleCmid).catch(() => {});
      }

      if (deleteCurrentCmid && currentCmid) {
        deleteVkMessage(VK_TOKEN, peerId, currentCmid).catch(() => {});
      }

      chatRecentMessages.set(peerId, rM.filter(m => !cmidsList.includes(m.cmId)));
      return cmidsList.length;
    }

    if (deleteCurrentCmid && currentCmid) {
      deleteVkMessage(VK_TOKEN, peerId, currentCmid).catch(() => {});
    }

    return count;
  } catch (e) {
    console.error("Error in deleteMessagesForUser:", e);
    return count;
  }
}

function isModerationCommandMessage(text?: string, fromId?: number): boolean {
  // Do NOT delete bot responses (fromId < 0)
  if (fromId && fromId < 0) return false;
  if (!text) return false;
  const trimmed = text.trim();
  
  // Check if starts with bot prefix or mention
  let content = trimmed;
  if (/^\[(?:club|public|id)\d+\|[^\]]+\]\s*/i.test(content)) {
    content = content.replace(/^\[(?:club|public|id)\d+\|[^\]]+\]\s*/i, "");
  }
  
  if (/^орион(\s*[,:;]?\s*|$)/i.test(content)) {
    content = "/" + content.replace(/^орион\s*[,:;]?\s*/i, "").trim();
  }

  if (!/^[\/\!\.\+\~\?;:]/i.test(content)) return false;
  
  const firstWord = content.split(/[\s\n]+/)[0]?.toLowerCase().replace(/^[^\wа-яё]+/gi, "");
  
  // Moderation / Administrative command triggers only
  const moderationTriggers = new Set([
    "mute", "мут", "unmute", "размут",
    "warn", "варн", "unwarn", "разварн", "warns", "варны",
    "kick", "кик", "исключить", "выгнать", "к", "k",
    "ban", "бан", "unban", "разбан",
    "clear", "mclear", "очистить", "чистка",
    "purge", "пурдж",
    "pin", "пин", "unpin", "анпин", "открепить", "закрепить",
    "addmoder", "addsenmoder", "addadmin", "addsenadmin", "addzsa", "addsa",
    "removerole", "rrole", "delrole", "dellevel", "removeaccesslevel", "rlevel", "removelevel", "снятьроль", "снятьправа",
    "gban", "ungban", "addblack", "unblack",
    "banid", "unbanid", "addzsr", "addozsr", "addruk", "addzamowner",
    "setowner", "deleteowner", "giveowner", "dgiveowner",
    "arrole", "grrole", "кикнеактив",
    "smute"
  ]);
  
  return firstWord ? moderationTriggers.has(firstWord) : false;
}

async function purgeCommandMessages(peerId: number, maxCount: number = 200): Promise<number> {
  try {
    const historyRes = await axios.get("https://api.vk.com/method/messages.getHistory", {
      params: { access_token: VK_TOKEN, v: "5.199", peer_id: peerId, count: Math.min(200, Math.max(1, maxCount)) }
    });
    const historyItems = historyRes.data?.response?.items || [];
    
    const rM = chatRecentMessages.get(peerId) || [];
    const cmidsSet = new Set<number>();
    
    for (const item of historyItems) {
      if (item.conversation_message_id && isModerationCommandMessage(item.text, item.from_id)) {
        cmidsSet.add(item.conversation_message_id);
      }
    }
    
    for (const m of rM) {
      if (m.cmId && isModerationCommandMessage(m.text, m.fromId)) {
        cmidsSet.add(m.cmId);
      }
    }
    
    const cmidsList = Array.from(cmidsSet);
    if (cmidsList.length === 0) return 0;
    
    for (let i = 0; i < cmidsList.length; i += 100) {
      const chunk = cmidsList.slice(i, i + 100);
      try {
        await axios.get("https://api.vk.com/method/messages.delete", {
          params: {
            access_token: VK_TOKEN,
            v: "5.199",
            cmids: chunk.join(","),
            delete_for_all: 1,
            peer_id: peerId
          }
        });
      } catch (err) {
        console.error("Error deleting purge chunk:", err);
      }
    }
    
    chatRecentMessages.set(peerId, rM.filter(m => !cmidsSet.has(m.cmId)));
    return cmidsList.length;
  } catch (e) {
    console.error("Error in purgeCommandMessages:", e);
    return 0;
  }
}

function parseMuteDuration(args: string[]): { timeMin: number, argIndex: number } {
  for (let i = 1; i < args.length; i++) {
    const arg = args[i].trim().toLowerCase();
    if (arg.includes("id") || arg.startsWith("[") || arg.includes("|")) {
      continue;
    }
    const match = arg.match(/^(\d+)([a-zа-яё\.\s]+)?$/i);
    if (match) {
      const val = parseInt(match[1]);
      const suffix = (match[2] || "").replace(/\./g, "").trim().toLowerCase();
      if (!suffix && val > 100000) {
        continue;
      }
      let rawMin = val;
      if (!suffix) {
        rawMin = val;
      } else if (["m", "м", "мин", "минута", "минуты", "минут"].includes(suffix)) {
        rawMin = val;
      } else if (["h", "ч", "час", "часа", "часов"].includes(suffix)) {
        rawMin = val * 60;
      } else if (["d", "д", "дн", "день", "дня", "дней"].includes(suffix)) {
        rawMin = val * 24 * 60;
      } else if (["s", "с", "сек", "секунда", "секунды", "секунд"].includes(suffix)) {
        rawMin = Math.round(val / 60);
      }
      const clampedMin = Math.min(Math.max(1, rawMin), 1000);
      return { timeMin: clampedMin, argIndex: i };
    }
  }
  return { timeMin: 30, argIndex: -1 };
}

// Helper for photo upload with retry and high-speed dispatcher
// Helper for photo upload with retry using robust manual multipart upload
// Fast Upload Server cache to avoid duplicate network calls
const uploadServerCache = new Map<string, { url: string; exp: number }>();


async function uploadDocGif(peerId: number, buffer: Buffer, title = "stats.gif"): Promise<{ attachment: string | null; error: string | null }> {
  try {
    const serverRes = await fastVkCall("docs.getMessagesUploadServer", {
      peer_id: peerId,
      type: "doc",
      access_token: VK_TOKEN,
      v: "5.199"
    });
    if (serverRes?.response?.upload_url) {
      const uploadUrl = serverRes.response.upload_url;
      const form = new FormData();
      form.append("file", buffer, {
        filename: title,
        contentType: "image/gif"
      });
      const upRes = await axios.post(uploadUrl, form, {
        headers: form.getHeaders(),
        maxContentLength: 50 * 1024 * 1024,
        maxBodyLength: 50 * 1024 * 1024,
        timeout: 30000
      });
      const fileData = upRes.data?.file || upRes.data?.response?.file || upRes.data;
      if (fileData && (typeof fileData === "string" || typeof fileData === "object")) {
        const fileParam = typeof fileData === "string" ? fileData : JSON.stringify(fileData);
        const saveRes = await fastVkCall("docs.save", {
          file: fileParam,
          title: title,
          tags: "stats,gif",
          access_token: VK_TOKEN,
          v: "5.199"
        });
        const resp = saveRes?.response;
        let docObj = resp?.doc || (Array.isArray(resp) ? resp[0] : null) || (resp?.type === "doc" ? resp.doc : resp);
        if (docObj && docObj.doc) docObj = docObj.doc;
        if (docObj && docObj.owner_id && docObj.id) {
          return { attachment: `doc${docObj.owner_id}_${docObj.id}`, error: null };
        }
      }
    }
  } catch (e: any) {
    console.error("[uploadDocGif] doc upload failed:", e.message || e);
  }
  return { attachment: null, error: "Failed to upload animated doc" };
}

async function uploadPhoto(peerId: number, source: string | Buffer, retries = 2): Promise<{ attachment: string | null; error: string | null }> {
  let lastError = "";
  const envGroupId = VK_GROUP_ID ? Math.abs(parseInt(String(VK_GROUP_ID).replace("-", ""))) : null;

  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      let buffer: Buffer;
      if (typeof source === "string") {
        if (source.startsWith('http')) {
          console.log(`[uploadPhoto] Downloading URL (Attempt ${attempt}): ${source.substring(0, 100)}...`);
          const resp = await axios.get(source, { 
            responseType: 'arraybuffer', 
            timeout: 25000,
            httpsAgent: globalHttpsAgent,
            headers: { 'User-Agent': 'VKBot/1.0' }
          });
          buffer = Buffer.from(resp.data);
        } else {
          buffer = await fs.promises.readFile(source);
        }
      } else {
        buffer = source;
      }

      if (!buffer || buffer.length === 0) {
        lastError = "Empty buffer generated";
        continue;
      }

      console.log(`[uploadPhoto] Attempt ${attempt} for peer ${peerId}, buffer size: ${buffer.length} bytes`);

      // 1. Get upload server (with 60s memory caching for instant response)
      let serverParams: any = { v: "5.131", access_token: VK_TOKEN };
      if (attempt === 1) serverParams.peer_id = peerId;
      else if (attempt === 2 && envGroupId) serverParams.group_id = envGroupId;

      const cacheKey = `${peerId}_${attempt}`;
      const cached = uploadServerCache.get(cacheKey);
      let uploadUrl = "";

      if (cached && cached.exp > Date.now() && attempt === 1) {
        uploadUrl = cached.url;
      } else {
        const serverRes = await fastVkCall("photos.getMessagesUploadServer", serverParams);
        if (!serverRes?.response?.upload_url) {
          const fallbackServerRes = await fastVkCall("photos.getMessagesUploadServer", { v: "5.131", access_token: VK_TOKEN });
          if (!fallbackServerRes?.response?.upload_url) {
            lastError = `Failed to get upload server: ${JSON.stringify(serverRes?.error || serverRes)}`;
            continue;
          }
          uploadUrl = fallbackServerRes.response.upload_url;
        } else {
          uploadUrl = serverRes.response.upload_url;
        }
        if (uploadUrl) {
          uploadServerCache.set(cacheKey, { url: uploadUrl, exp: Date.now() + 60000 });
        }
      }

      // 2. Upload to VK using FormData
      const form = new FormData();
      form.append('photo', buffer, { 
        filename: 'image.png', 
        contentType: 'image/png',
        knownLength: buffer.length 
      });

      const upRes = await axios.post(uploadUrl, form, {
        headers: {
          ...form.getHeaders(),
          'Connection': 'keep-alive'
        },
        timeout: 40000,
        maxContentLength: Infinity,
        maxBodyLength: Infinity,
        httpsAgent: globalHttpsAgent
      });

      if (!upRes.data || !upRes.data.photo || upRes.data.photo === '[]') {
        lastError = `Upload to VK failed (empty photo array): ${JSON.stringify(upRes.data)}`;
        continue;
      }

      // 3. Save photo
      const saveParams: any = {
        photo: upRes.data.photo,
        server: upRes.data.server,
        hash: upRes.data.hash,
        v: "5.131",
        access_token: VK_TOKEN
      };
      
      // Use group_id if we got it from server params or it's needed
      if (serverParams.group_id) saveParams.group_id = serverParams.group_id;

      let saveRes = await fastVkCall("photos.saveMessagesPhoto", saveParams);
      
      // Fallback save with group_id if needed
      if ((!saveRes?.response?.[0]) && envGroupId && !saveParams.group_id) {
        saveParams.group_id = envGroupId;
        saveRes = await fastVkCall("photos.saveMessagesPhoto", saveParams);
      }

      if (!saveRes?.response?.[0]) {
        lastError = `Failed to save photo: ${JSON.stringify(saveRes?.error || saveRes)}`;
        continue;
      }

      const p = saveRes.response[0];
      const attachment = `photo${p.owner_id}_${p.id}${p.access_key ? '_' + p.access_key : ''}`;
      console.log(`[uploadPhoto] Success! Attachment: ${attachment} for peer ${peerId}`);
      return { attachment, error: null };

    } catch (e: any) {
      lastError = e.message || String(e);
      console.error(`[uploadPhoto] Exception on attempt ${attempt}:`, e.message || e);
      if (attempt < retries) {
        await new Promise(r => setTimeout(r, 1500 * attempt));
      }
    }
  }

  return { attachment: null, error: lastError || "Unknown error during photo upload process" };
}

