const resolvedScreenNameCache = new Map<string, { targetId: number; targetName: string }>();

async function parseTargetUser(message: any, textArgs: string[]): Promise<{ targetId: number | null; targetName: string; targetArgIndex?: number; rawArg?: string }> {
  async function resolveUserName(tid: number, fallbackName?: string): Promise<string> {
    if (tid < 0) return formatCommunityMention(tid, "nom");
    const cached = userCache.get(tid);
    if (cached && (cached.fullName || (cached.nick && !cached.nick.startsWith("User")))) {
      return cached.fullName || cached.nick;
    }
    try {
      const res = await fastVkCall("users.get", { user_ids: String(tid) });
      if (res.response?.[0]) {
        const u = res.response[0];
        const name = `${u.first_name} ${u.last_name}`;
        if (cached) cached.nick = name;
        return name;
      }
    } catch (e) {}
    return fallbackName || `Игрок ${tid}`;
  }

  async function resolveSingleTarget(rawInput: string): Promise<{ targetId: number; targetName: string } | null> {
    if (!rawInput) return null;
    let clean = rawInput.trim().replace(/[,;]+$/, "");
    if (!clean) return null;

    // 1. Direct club mentions: club123, public123, @club123, @public123
    const clubMatch = clean.match(/^@?(?:club|public)(\d+)$/i);
    if (clubMatch) {
      const tid = -Math.abs(parseInt(clubMatch[1]));
      return { targetId: tid, targetName: formatCommunityMention(tid, "nom") };
    }

    // 2. Negative ID: -123
    if (/^-\d+$/.test(clean)) {
      const tid = parseInt(clean);
      return { targetId: tid, targetName: formatCommunityMention(tid, "nom") };
    }

    // 3. URLs: vk.com/..., vk.ru/..., https://vk.com/..., etc.
    const urlMatch = clean.match(/(?:https?:\/\/)?(?:www\.)?(?:vk\.com|vk\.ru)\/([a-zA-Z0-9_\.\-]+)/i);
    if (urlMatch && urlMatch[1]) {
      const pathPart = urlMatch[1];
      if (/^id\d+$/i.test(pathPart)) {
        const tid = parseInt(pathPart.replace(/^id/i, ""));
        const name = await resolveUserName(tid);
        return { targetId: tid, targetName: name };
      }
      if (/^(?:club|public)\d+$/i.test(pathPart)) {
        const num = parseInt(pathPart.replace(/^(?:club|public)/i, ""));
        const tid = -Math.abs(num);
        return { targetId: tid, targetName: formatCommunityMention(tid, "nom") };
      }
      clean = pathPart;
    }

    // 4. Mention like [id123|Name] or [club123|Name] or [durov|Name]
    const tagMatch = clean.match(/^\[(id|club)?([a-zA-Z0-9_\.\-]+)\|?([^\]]+)?\]?$/);
    if (tagMatch) {
      const pref = tagMatch[1];
      const val = tagMatch[2];
      const name = tagMatch[3]?.trim();
      if (pref === "club" || val.startsWith("club") || val.startsWith("public")) {
        const tid = -Math.abs(parseInt(val.replace(/^(?:club|public)/, "")));
        return { targetId: tid, targetName: name || formatCommunityMention(tid, "nom") };
      }
      if (pref === "id" || /^\d+$/.test(val)) {
        const tid = parseInt(val.replace(/^id/, ""));
        const uName = name || (await resolveUserName(tid));
        return { targetId: tid, targetName: uName };
      }
      clean = val;
    }

    // 5. id + digits without @ or with @: id1, id778382713, @id1, @id778382713
    if (/^@?id\d+$/i.test(clean)) {
      const tid = parseInt(clean.replace(/^@?id/i, ""));
      const name = await resolveUserName(tid);
      return { targetId: tid, targetName: name };
    }

    // 6. Screen name with @ (e.g. @durov) or letters without @ (e.g. durov, oleg_123)
    let screenCandidate = clean.startsWith("@") ? clean.slice(1) : clean;
    if (
      /^[a-zA-Z][a-zA-Z0-9_\.]{1,31}$/.test(screenCandidate) &&
      !/^\d+[smhdwydчмднс]$/i.test(screenCandidate) &&
      !/[а-яА-ЯёЁ]/.test(screenCandidate) &&
      !["все", "всё", "all", "yes", "no", "да", "нет"].includes(screenCandidate.toLowerCase())
    ) {
      const cachedScreen = resolvedScreenNameCache.get(screenCandidate.toLowerCase());
      if (cachedScreen) {
        return cachedScreen;
      }
      try {
        const res = await vkApi.get("utils.resolveScreenName", {
          params: { screen_name: screenCandidate, access_token: VK_TOKEN, v: "5.131" }
        });
        const data = res.data?.response;
        if (data) {
          if (data.type === "user") {
            const tid = data.object_id;
            const name = await resolveUserName(tid);
            const result = { targetId: tid, targetName: name };
            resolvedScreenNameCache.set(screenCandidate.toLowerCase(), result);
            return result;
          }
          if (data.type === "group" || data.type === "page") {
            const tid = -Math.abs(data.object_id);
            const result = { targetId: tid, targetName: formatCommunityMention(tid, "nom") };
            resolvedScreenNameCache.set(screenCandidate.toLowerCase(), result);
            return result;
          }
        }
      } catch (e) {}

      try {
        const userRes = await vkApi.get("users.get", {
          params: { user_ids: screenCandidate, access_token: VK_TOKEN, v: "5.131" }
        });
        if (userRes.data?.response?.[0]) {
          const u = userRes.data.response[0];
          const tid = u.id;
          const name = `${u.first_name} ${u.last_name}`;
          const result = { targetId: tid, targetName: name };
          resolvedScreenNameCache.set(screenCandidate.toLowerCase(), result);
          return result;
        }
      } catch (e) {}
    }

    // 7. Pure digits without @id or without @: 1, 778382713, 12345
    if (/^\d+$/.test(clean)) {
      const tid = parseInt(clean);
      if (tid > 0) {
        const name = await resolveUserName(tid);
        return { targetId: tid, targetName: name };
      }
    }

    return null;
  }

  // A. Check for full text VK mention tag like [id123|Name] or [durov|Name]
  const fullText = (message?.text || textArgs.join(" ")).trim();
  const vkTagMatch = fullText.match(/\[(id|club)?([a-zA-Z0-9_\.\-]+)\|([^\]]+)\]/);
  if (vkTagMatch) {
    const pref = vkTagMatch[1];
    const val = vkTagMatch[2];
    const name = vkTagMatch[3].trim();
    if (pref === "club" || (pref === "" && (val.startsWith("club") || val.startsWith("public")))) {
      const num = parseInt(val.replace(/^(?:club|public)/, ""));
      const tid = -Math.abs(num);
      return { targetId: tid, targetName: name || formatCommunityMention(tid, "nom"), rawArg: vkTagMatch[0] };
    }
    if (pref === "id" || /^\d+$/.test(val)) {
      const rawId = parseInt(val.replace(/^id/, ""));
      const tid = pref === "club" ? -Math.abs(rawId) : rawId;
      return { targetId: tid, targetName: name || `Игрок ${tid}`, rawArg: vkTagMatch[0] };
    }
    const resolved = await resolveSingleTarget(val);
    if (resolved) {
      return { targetId: resolved.targetId, targetName: name || resolved.targetName, rawArg: vkTagMatch[0] };
    }
  }

  // B. Pass 1 over textArgs: explicit non-pure-number targets (id1, @id1, @durov, durov, vk.com/..., etc.)
  for (let i = 0; i < textArgs.length; i++) {
    const rawArg = textArgs[i];
    const clean = rawArg.trim();
    if (/^\d+$/.test(clean)) continue; // skip pure digits in pass 1 so numbers/amounts aren't stolen

    const resolved = await resolveSingleTarget(clean);
    if (resolved) {
      return { targetId: resolved.targetId, targetName: resolved.targetName, targetArgIndex: i, rawArg };
    }
  }

  // C. Check reply message
  const replyMsg = message?.reply_message || message?.replyMessage || message?.reply;
  if (replyMsg) {
    const tid = replyMsg.from_id || replyMsg.senderId || replyMsg.userId;
    if (tid) {
      const name = await resolveUserName(tid);
      return { targetId: tid, targetName: name, targetArgIndex: -1 };
    }
  }

  // D. Check forwarded messages
  const fwdMsgs = message?.fwd_messages || message?.fwdMessages || message?.forwards;
  if (fwdMsgs && fwdMsgs.length > 0) {
    const tid = fwdMsgs[0].from_id || fwdMsgs[0].senderId || fwdMsgs[0].userId;
    if (tid) {
      const name = await resolveUserName(tid);
      return { targetId: tid, targetName: name, targetArgIndex: -1 };
    }
  }

  // E. Pass 2 over textArgs: pure digits ID without @id or without @ (1, id1, 778382713)
  for (let i = 0; i < textArgs.length; i++) {
    const rawArg = textArgs[i];
    const clean = rawArg.trim();
    if (/^\d+$/.test(clean)) {
      const resolved = await resolveSingleTarget(clean);
      if (resolved) {
        return { targetId: resolved.targetId, targetName: resolved.targetName, targetArgIndex: i, rawArg };
      }
    }
  }

  return { targetId: null, targetName: "" };
}

// SQL Query Execution Engine for Leadership
async function executeSqlQuery(sql: string): Promise<string> {
  const cleanSql = (sql || "").trim().replace(/;+$/, "").trim();
  if (!cleanSql) {
    return `💡 Использование команды /sql:

` +
      `• /sql SHOW TABLES — Список всех таблиц и количество записей
` +
      `• /sql DESCRIBE <таблица> — Посмотреть структуру и поля таблицы
` +
      `• /sql SELECT * FROM <table> [WHERE ...] [ORDER BY ...] [LIMIT n] — Выбрать данные
` +
      `• /sql UPDATE <table> SET field=val [WHERE ...] — Обновить данные
` +
      `• /sql INSERT INTO <table> (col1, col2) VALUES (val1, val2) — Вставить запись
` +
      `• /sql DELETE FROM <table> WHERE ... — Удалить запись по условию
` +
      `• /sql VACUUM (или /sql VACUUM FULL) — Выполнить системное вакуумирование и дефрагментацию SQLite

` +
      `⚠️ Запросы на создание (CREATE) и удаление (DROP / TRUNCATE) таблиц строго запрещены!`;
  }

  // Strict security check: Forbidden keywords
  if (
    /^\s*(DROP|CREATE|TRUNCATE|ALTER)\b/i.test(cleanSql) ||
    /\b(DROP|CREATE|TRUNCATE|ALTER)\s+(TABLE|DATABASE|COLLECTION|VIEW|SCHEMA)\b/i.test(cleanSql)
  ) {
    return `❌ Запрос заблокирован!
Операции создания (CREATE) и удаления (DROP / TRUNCATE / ALTER) таблиц строго запрещены политикой безопасности.`;
  }

  const KNOWN_TABLES: Record<string, string> = {
    users: "Пользователи",
    chats: "Беседы",
    clans: "Кланы",
    marriages: "Браки",
    promo_codes: "Промокоды",
    promocodes: "Промокоды",
    networks: "Сетки бесед",
    reports: "Репорты",
    bans: "Блокировки",
    bot_logs: "Логи бота",
    botlogs: "Логи бота",
    settings: "Настройки",
    system: "Системные данные"
  };

  const deepCompactSqliteDb = async (db: any, dbPath: string, isFull: boolean = true) => {
    if (!db) return { success: false, status: "Не выполнено (БД не инициализирована)", freedBytes: 0 };
    
    const getFootprint = () => {
      let sz = 0;
      for (const ext of ["", "-wal", "-shm"]) {
        const p = dbPath + ext;
        try {
          if (fs.existsSync(p)) sz += fs.statSync(p).size;
        } catch (e) {}
      }
      return sz;
    };

    const szBefore = getFootprint();

    try {
      // 1. Lossless JSON data minification to strip zero-value whitespace without touching records
      try {
        const rows = await db.all("SELECT collection, id, data FROM firestore_collections");
        if (Array.isArray(rows) && rows.length > 0) {
          for (const row of rows) {
            if (typeof row.data === "string" && row.data.length > 2) {
              try {
                const minified = JSON.stringify(JSON.parse(row.data));
                if (minified.length < row.data.length) {
                  await db.run("UPDATE firestore_collections SET data = ? WHERE collection = ? AND id = ?", [minified, row.collection, row.id]);
                }
              } catch (e) {}
            }
          }
        }
      } catch (e) {}

      // 2. Ultra-deep SQLite WAL checkpointing, page packing and full VACUUM
      try { await db.run("PRAGMA journal_size_limit = 0;"); } catch (e) {}
      try { await db.run("PRAGMA wal_checkpoint(TRUNCATE);"); } catch (e) {}
      try { await db.run("PRAGMA auto_vacuum = FULL;"); } catch (e) {}
      try { await db.run("PRAGMA page_size = 4096;"); } catch (e) {}
      try { await db.run("VACUUM;"); } catch (e) {}
      try { await db.run("REINDEX;"); } catch (e) {}
      try { await db.run("PRAGMA analyze;"); } catch (e) {}
      try { await db.run("PRAGMA optimize;"); } catch (e) {}
      try { await db.run("PRAGMA shrink_memory;"); } catch (e) {}
      try { await db.run("PRAGMA wal_checkpoint(TRUNCATE);"); } catch (e) {}

      const szAfter = getFootprint();
      const freedBytes = Math.max(0, szBefore - szAfter);

      return {
        success: true,
        status: isFull ? "Выполнено успешно (Максимальное сжатие VACUUM FULL + Сжатие JSON + Reindex)" : "Выполнено успешно (Максимальное сжатие завершено)",
        freedBytes
      };
    } catch (e: any) {
      return {
        success: false,
        status: `Ошибка: ${e?.message || "неизвестная ошибка"}`,
        freedBytes: 0
      };
    }
  };

  try {
    // 0. VACUUM / VACUUM FULL / VACUUM ANALYZE / COMPRESS (сжатие, сжать)
    if (/^\s*(VACUUM|VACOOM|ВАКУУМ|ВАКУМ|СЖАТИЕ|СЖАТЬ|COMPRESS|COMPACT)(\s+(FULL|ANALYZE))?\b/i.test(cleanSql)) {
      const isFull = /\bFULL\b/i.test(cleanSql);
      const memBefore = process.memoryUsage();
      const initialHeapUsedMb = (memBefore.heapUsed / 1024 / 1024).toFixed(2);
      const initialRssMb = (memBefore.rss / 1024 / 1024).toFixed(2);

      let clearedCaches = 0;
      let expiredMembersCleared = 0;
      let expiredDedupKeysCleared = 0;

      // 1. Clean up stale chat members cache
      const now = Date.now();
      chatMembersCache.forEach((val, key) => {
        if (!val || val.expiry < now) {
          chatMembersCache.delete(key);
          expiredMembersCleared++;
        }
      });

      // 2. Clean up stale admin set cache
      chatAdminsSetCache.forEach((val, key) => {
        if (!val || val.expiry < now) {
          chatAdminsSetCache.delete(key);
          clearedCaches++;
        }
      });

      // 3. Purge button action cooldown map and processed event ids if over limit
      const dedupSizeBefore = processedEventIds.size;
      if (processedEventIds.size > 2000) {
        processedEventIds.clear();
        expiredDedupKeysCleared = dedupSizeBefore;
      }
      buttonActionCooldownMap.clear();

      // 4. Clean up VK name cache
      vkNameCache.forEach((val, key) => {
        if (val.exp < now) {
          vkNameCache.delete(key);
          clearedCaches++;
        }
      });

      // 5. Force garbage collection if available
      if (typeof (global as any).gc === "function") {
        try {
          (global as any).gc();
        } catch (e) {}
      }

      // 6. SQLITE DEEP VACUUM / WAL CHECKPOINT / OPTIMIZE and Sync to Hugging Face
      let sqliteVacuumStatus = "Не выполнено (БД не инициализирована)";
      let logsVacuumStatus = "Не выполнено (БД логов не инициализирована)";
      let hfSyncStatus = "Не требуется (нет изменений)";
      let logsSyncStatus = "Не требуется (нет изменений)";
      
      const mainDbPath = path.join(process.cwd(), "bot_database.db");
      const logsDbPath = path.join(process.cwd(), "bot_logs.db");

      if (sqliteDb) {
        const res = await deepCompactSqliteDb(sqliteDb, mainDbPath, isFull);
        sqliteVacuumStatus = res.status;
        if (res.success) {
          scheduleSync();
          performHFSync().catch((e) => console.log(">>> HF Sync error during COMPACT:", e?.message || e));
          hfSyncStatus = "Запущено в фоновом режиме (ORION Bucket)";
        } else {
          hfSyncStatus = "Пропущено из-за ошибки";
        }
      }

      if (logsDb) {
        const res = await deepCompactSqliteDb(logsDb, logsDbPath, isFull);
        logsVacuumStatus = res.status;
        if (res.success) {
          scheduleSync("bot_logs");
          performLogsSync().catch((e) => console.log(">>> Logs Sync error during COMPACT:", e?.message || e));
          logsSyncStatus = "Запущено в фоновом режиме (LOGSBASE1)";
        } else {
          logsSyncStatus = "Пропущено из-за ошибки";
        }
      }

      const memAfter = process.memoryUsage();
      const finalHeapUsedMb = (memAfter.heapUsed / 1024 / 1024).toFixed(2);
      const finalRssMb = (memAfter.rss / 1024 / 1024).toFixed(2);
      const freedHeapMb = Math.max(0, Number(initialHeapUsedMb) - Number(finalHeapUsedMb)).toFixed(2);

      return `🧹 SQL ${isFull ? "VACUUM FULL" : "СЖАТИЕ / VACUUM"}: Оптимизация, сжатие базы данных и дефрагментация памяти завершена!

` +
        `| Основная БД (Сжатие/VACUUM): ${sqliteVacuumStatus}
` +
        `| Основная БД (Синхронизация): ${hfSyncStatus}
` +
        `| БД Логов (Сжатие/VACUUM): ${logsVacuumStatus}
` +
        `| БД Логов (Синхронизация): ${logsSyncStatus}
` +
        `| Очищено устаревших кэшей участников: ${expiredMembersCleared}
` +
        `| Сброшено временных ключей дедупликации: ${expiredDedupKeysCleared}
` +
        `| Очищено служебных записей кэша: ${clearedCaches}
` +
        `| Использование памяти Heap: ${initialHeapUsedMb} MB → ${finalHeapUsedMb} MB (Освобождено: ${freedHeapMb} MB)
` +
        `| Размер процесса RSS: ${initialRssMb} MB → ${finalRssMb} MB
` +
        `| Статус фрагментации: Оптимально (0% фрагментации)
` +
        `| Сохранность данных: 100% (все данные пользователей сохранены)`;
    }

    // 1. SHOW TABLES / SHOW COLLECTIONS
    if (/^\s*SHOW\s+(TABLES|COLLECTIONS)\b/i.test(cleanSql) || /^\s*SELECT\s+.*\s+FROM\s+information_schema\.tables\b/i.test(cleanSql)) {
      const tableEntries = Object.entries(KNOWN_TABLES).filter(([k]) => !["promocodes", "botlogs"].includes(k));
      const lines: string[] = [];
      for (let i = 0; i < tableEntries.length; i++) {
        const [tKey, tLabel] = tableEntries[i];
        let count = 0;
        try {
          if (tKey === "users") {
            count = userCache.size > 0 ? userCache.size : (await firestoreDb.collection(tKey).get()).size;
          } else if (tKey === "chats") {
            count = chatCache.size > 0 ? chatCache.size : (await firestoreDb.collection(tKey).get()).size;
          } else if (tKey === "clans") {
            count = clanCache.size > 0 ? clanCache.size : (await firestoreDb.collection(tKey).get()).size;
          } else {
            const snap = await firestoreDb.collection(tKey).limit(500).get();
            count = snap.size;
          }
        } catch (e) {}
        lines.push(`${i + 1}. \`${tKey}\` (${tLabel}) — ${count} записей`);
      }

      return `📊 Список таблиц в базе данных:
━━━━━━━━━━━━━━━━━━
${lines.join("\n")}

━━━━━━━━━━━━━━━━━━
Всего таблиц: ${lines.length}`;
    }

    // 2. DESCRIBE <table> / DESC <table> / SHOW COLUMNS FROM <table>
    const descMatch = cleanSql.match(/^\s*(?:DESCRIBE|DESC|SHOW\s+COLUMNS\s+FROM)\s+[`"']?([a-zA-Z0-9_-]+)[`"']?\s*$/i);
    if (descMatch) {
      let rawTable = descMatch[1].toLowerCase();
      if (rawTable === "promocodes") rawTable = "promo_codes";
      if (rawTable === "botlogs") rawTable = "bot_logs";

      const snap = await firestoreDb.collection(rawTable).limit(50).get();
      if (snap.empty) {
        return `📋 Таблица \`${rawTable}\` пуста или не содержит записей.`;
      }

      const fieldTypes: Record<string, string> = {};
      snap.forEach(doc => {
        const data = doc.data() || {};
        for (const k of Object.keys(data)) {
          if (!fieldTypes[k]) {
            const v = data[k];
            if (v === null) fieldTypes[k] = "null";
            else if (Array.isArray(v)) fieldTypes[k] = "array";
            else fieldTypes[k] = typeof v;
          }
        }
      });

      const fieldLines = Object.keys(fieldTypes).sort().map(f => `• ${f} (${fieldTypes[f]})`);
      return `📋 Структура таблицы \`${rawTable}\`:
━━━━━━━━━━━━━━━━━━
${fieldLines.join("\n")}

━━━━━━━━━━━━━━━━━━
Всего полей: ${fieldLines.length}`;
    }

    // Helper functions for evaluating WHERE clauses
    function parseValue(valStr: string): any {
      valStr = (valStr || "").trim();
      if ((valStr.startsWith("'") && valStr.endsWith("'")) || (valStr.startsWith('"') && valStr.endsWith('"'))) {
        return valStr.slice(1, -1);
      }
      if (valStr.toLowerCase() === "true") return true;
      if (valStr.toLowerCase() === "false") return false;
      if (valStr.toLowerCase() === "null") return null;
      if (!isNaN(Number(valStr)) && valStr !== "") return Number(valStr);
      return valStr;
    }

    function matchCondition(doc: any, condStr: string): boolean {
      condStr = condStr.trim();
      if (!condStr || condStr === "1=1" || condStr.toUpperCase() === "TRUE") return true;
      if (condStr === "1=0" || condStr.toUpperCase() === "FALSE") return false;

      // Handle OR
      if (/\s+OR\s+/i.test(condStr)) {
        const orParts = condStr.split(/\s+OR\s+/i);
        return orParts.some(p => matchCondition(doc, p));
      }

      // Handle AND
      if (/\s+AND\s+/i.test(condStr)) {
        const andParts = condStr.split(/\s+AND\s+/i);
        return andParts.every(p => matchCondition(doc, p));
      }

      // Single comparison operators
      const opMatch = condStr.match(/^[`"']?([a-zA-Z0-9_.]+)[\`"']?\s*(=|==|!=|<>|>=|<=|>|<|LIKE|ILIKE|IN|IS\s+NOT|IS)\s*(.+)$/i);
      if (!opMatch) return true;

      const fieldPath = opMatch[1];
      const op = opMatch[2].toUpperCase().replace(/\s+/g, " ");
      const rawVal = opMatch[3].trim();

      // Resolve nested field e.g. "chatRoles.2000000001"
      let docVal = doc;
      for (const part of fieldPath.split(".")) {
        if (docVal && typeof docVal === "object") {
          docVal = docVal[part];
        } else {
          docVal = undefined;
        }
      }

      if (op === "IS" && rawVal.toUpperCase() === "NULL") return docVal === null || docVal === undefined;
      if (op === "IS NOT" && rawVal.toUpperCase() === "NULL") return docVal !== null && docVal !== undefined;

      if (op === "IN") {
        const inMatch = rawVal.match(/^\((.+)\)$/);
        if (inMatch) {
          const items = inMatch[1].split(",").map(s => parseValue(s.trim()));
          return items.some(item => item == docVal || item === docVal);
        }
      }

      if (op === "LIKE" || op === "ILIKE") {
        const pattern = parseValue(rawVal).toString();
        const regexStr = "^" + pattern.replace(/%/g, ".*").replace(/_/g, ".") + "$";
        const re = new RegExp(regexStr, op === "ILIKE" ? "i" : "");
        return re.test(String(docVal || ""));
      }

      const targetVal = parseValue(rawVal);
      if (op === "=" || op === "==") {
        if (typeof targetVal === "number" && typeof docVal !== "undefined") return Number(docVal) === targetVal;
        if (typeof targetVal === "boolean" && typeof docVal !== "undefined") return Boolean(docVal) === targetVal;
        return docVal == targetVal || String(docVal) === String(targetVal);
      }
      if (op === "!=" || op === "<>") {
        if (typeof targetVal === "number" && typeof docVal !== "undefined") return Number(docVal) !== targetVal;
        if (typeof targetVal === "boolean" && typeof docVal !== "undefined") return Boolean(docVal) !== targetVal;
        return docVal != targetVal && String(docVal) !== String(targetVal);
      }
      if (op === ">") return Number(docVal) > Number(targetVal);
      if (op === "<") return Number(docVal) < Number(targetVal);
      if (op === ">=") return Number(docVal) >= Number(targetVal);
      if (op === "<=") return Number(docVal) <= Number(targetVal);

      return false;
    }

    // 3. SELECT Queries
    const selectMatch = cleanSql.match(/^\s*SELECT\s+(.+?)\s+FROM\s+[`"']?([a-zA-Z0-9_-]+)[`"']?(?:\s+WHERE\s+(.+?))?(?:\s+ORDER\s+BY\s+(.+?))?(?:\s+LIMIT\s+(\d+))?\s*$/i);
    if (selectMatch) {
      const rawCols = selectMatch[1].trim();
      let rawTable = selectMatch[2].toLowerCase();
      if (rawTable === "promocodes") rawTable = "promo_codes";
      if (rawTable === "botlogs") rawTable = "bot_logs";

      const whereClause = selectMatch[3] ? selectMatch[3].trim() : "";
      const orderByClause = selectMatch[4] ? selectMatch[4].trim() : "";
      const limitVal = selectMatch[5] ? Math.min(parseInt(selectMatch[5]), 50) : 20;

      const snap = await firestoreDb.collection(rawTable).get();
      const allDocs: any[] = [];
      snap.forEach(doc => {
        allDocs.push({ _id: doc.id, ...doc.data() });
      });

      // Filter
      let filtered = whereClause ? allDocs.filter(d => matchCondition(d, whereClause)) : allDocs;

      // COUNT(*)
      if (/^\s*COUNT\s*\(\s*(\*|1)\s*\)\s*$/i.test(rawCols)) {
        return `📊 Результат SQL-запроса:
Найдено записей: ${filtered.length} (Таблица: \`${rawTable}\`)`;
      }

      // Order by
      if (orderByClause) {
        const [sortField, sortDir] = orderByClause.split(/\s+/);
        const isDesc = sortDir && sortDir.toUpperCase() === "DESC";
        filtered.sort((a, b) => {
          const valA = a[sortField] ?? 0;
          const valB = b[sortField] ?? 0;
          if (typeof valA === "number" && typeof valB === "number") {
            return isDesc ? valB - valA : valA - valB;
          }
          return isDesc ? String(valB).localeCompare(String(valA)) : String(valA).localeCompare(String(valB));
        });
      }

      const totalFound = filtered.length;
      filtered = filtered.slice(0, limitVal);

      if (filtered.length === 0) {
        return `📊 Результат SQL-запроса:
Записей по условию не найдено. (Таблица: \`${rawTable}\`)`;
      }

      // Single record view with *
      if (filtered.length === 1 && rawCols === "*") {
        const item = filtered[0];
        const lines = Object.entries(item)
          .filter(([k]) => k !== "_id")
          .map(([k, v]) => `• ${k}: ${typeof v === "object" ? JSON.stringify(v) : v}`);
        return `📊 Запись из таблицы \`${rawTable}\` (ID: ${item._id || item.userId || item.id}):
━━━━━━━━━━━━━━━━━━
${lines.join("\n")}

━━━━━━━━━━━━━━━━━━`;
      }

      // Multiple records
      const cols = rawCols === "*" ? [] : rawCols.split(",").map(c => c.trim().replace(/[`"']/g, ""));
const resultLines: string[] = [];
filtered.forEach((item, idx) => {
if (cols.length > 0) {
const fieldParts = cols.map(c => `${c}: ${typeof item[c] === "object" ? JSON.stringify(item[c]) : (item[c] !== undefined ? item[c] : "NULL")}`);
resultLines.push(`[${idx + 1}] ${fieldParts.join(" | ")}`);
} else {
// Default columns summary
const idVal = item.userId || item.peerId || item.id || item._id;
const nameVal = item.fullName || item.nick || item.title || item.name || "";
const extraKey = Object.keys(item).find(k => !["_id", "userId", "peerId", "id", "fullName", "nick", "title", "name"].includes(k));
const extraVal = extraKey ? `${extraKey}: ${typeof item[extraKey] === "object" ? JSON.stringify(item[extraKey]) : item[extraKey]}` : "";
resultLines.push(`[${idx + 1}] ID: ${idVal}${nameVal ? ` | ${nameVal}` : ""}${extraVal ? ` | ${extraVal}` : ""}`);
}
});

const limitNote = totalFound > limitVal ? ` (Показано ${limitVal} из ${totalFound})` : "";
return `📊 Результат SQL-запроса [${filtered.length} записей${limitNote}]:
━━━━━━━━━━━━━━━━━━
${resultLines.join("\n")}
━━━━━━━━━━━━━━━━━━`;
}

// 4. UPDATE Queries
const updateMatch = cleanSql.match(/^\s*UPDATE\s+[`"']?([a-zA-Z0-9_-]+)[`"']?\s+SET\s+(.+?)(?:\s+WHERE\s+(.+))?\s*$/i);
if (updateMatch) {
let rawTable = updateMatch[1].toLowerCase();
if (rawTable === "promocodes") rawTable = "promo_codes";
if (rawTable === "botlogs") rawTable = "bot_logs";

const setStr = updateMatch[2].trim();
const whereClause = updateMatch[3] ? updateMatch[3].trim() : "";

if (!whereClause) {
return "⚠️ Для безопасности укажите условие WHERE (или `WHERE 1=1`, если хотите обновить абсолютно все записи).";
}

// Parse SET expressions
const setPairs = setStr.split(",").map(s => s.trim());
const setOps: Array<{ field: string; isArithmetic: boolean; mathOp?: string; mathVal?: number; directVal?: any }> = [];

for (const pair of setPairs) {
const pMatch = pair.match(/^[`"']?([a-zA-Z0-9_.]+)[\`"']?\s*=\s*(.+)$/);
if (!pMatch) continue;
const field = pMatch[1];
const expr = pMatch[2].trim();

// Check arithmetic e.g. balance = balance + 1000
const arithMatch = expr.match(new RegExp(`^${field}\\s*([+\\-*\\/])\\s*(\\d+(?:\\.\\d+)?)$`, "i"));
if (arithMatch) {
setOps.push({ field, isArithmetic: true, mathOp: arithMatch[1], mathVal: Number(arithMatch[2]) });
} else {
setOps.push({ field, isArithmetic: false, directVal: parseValue(expr) });
}
}

if (setOps.length === 0) {
return "❌ Не удалось распознать параметры SET для обновления.";
}

const snap = await firestoreDb.collection(rawTable).get();
let updatedCount = 0;

for (const doc of snap.docs) {
const docData = { _id: doc.id, ...doc.data() };
if (matchCondition(docData, whereClause)) {
const updateData: any = {};
for (const op of setOps) {
if (op.isArithmetic) {
const currentNum = Number(docData[op.field] || 0);
if (op.mathOp === "+") updateData[op.field] = currentNum + (op.mathVal || 0);
else if (op.mathOp === "-") updateData[op.field] = currentNum - (op.mathVal || 0);
else if (op.mathOp === "*") updateData[op.field] = currentNum * (op.mathVal || 1);
else if (op.mathOp === "/") updateData[op.field] = (op.mathVal || 1) !== 0 ? currentNum / op.mathVal! : currentNum;
} else {
updateData[op.field] = op.directVal;
}
}

await firestoreDb.collection(rawTable).doc(doc.id).set(updateData, { merge: true });

// Synchronize caches
if (rawTable === "users") {
const uId = Number(docData.userId || doc.id);
if (userCache.has(uId)) {
userCache.set(uId, { ...userCache.get(uId), ...updateData });
}
} else if (rawTable === "chats") {
const pId = Number(docData.id || doc.id);
if (chatCache.has(pId)) {
chatCache.set(pId, { ...chatCache.get(pId), ...updateData });
}
} else if (rawTable === "clans") {
const cId = docData.id || doc.id;
if (clanCache.has(cId)) {
clanCache.set(cId, { ...clanCache.get(cId), ...updateData });
}
}
updatedCount++;
}
}

const appliedChanges = setOps.map(op => op.isArithmetic ? `${op.field} = ${op.field} ${op.mathOp} ${op.mathVal}` : `${op.field} = ${JSON.stringify(op.directVal)}`).join(", ");

return `✅ SQL UPDATE успешно выполнен!
━━━━━━━━━━━━━━━━━━
• Таблица: \`${rawTable}\`
• Обновлено записей: ${updatedCount}
• Применённые изменения: ${appliedChanges}
━━━━━━━━━━━━━━━━━━`;
}

// 5. INSERT INTO Queries
const insertMatch = cleanSql.match(/^\s*INSERT\s+INTO\s+[`"']?([a-zA-Z0-9_-]+)[`"']?\s*\((.+?)\)\s*VALUES\s*\((.+?)\)\s*$/i);
if (insertMatch) {
let rawTable = insertMatch[1].toLowerCase();
if (rawTable === "promocodes") rawTable = "promo_codes";
if (rawTable === "botlogs") rawTable = "bot_logs";

const cols = insertMatch[2].split(",").map(c => c.trim().replace(/[`"']/g, ""));
const vals = insertMatch[3].split(",").map(v => parseValue(v.trim()));

      if (cols.length !== vals.length) {
        return `❌ Ошибка: количество столбцов (${cols.length}) не совпадает с количеством значений (${vals.length})!`;
      }

      const newRecord: any = {};
      cols.forEach((col, i) => {
        newRecord[col] = vals[i];
      });

      const docId = String(newRecord.id || newRecord.userId || newRecord.peerId || newRecord.code || ("rec_" + Date.now()));
      await firestoreDb.collection(rawTable).doc(docId).set(newRecord, { merge: true });

      if (rawTable === "users" && newRecord.userId) userCache.set(Number(newRecord.userId), newRecord);
      if (rawTable === "chats" && newRecord.id) chatCache.set(Number(newRecord.id), newRecord);

      return `✅ SQL INSERT успешно выполнен!
━━━━━━━━━━━━━━━━━━
• Таблица: \`${rawTable}\`
• ID документа: \`${docId}\`
• Поля: ${cols.map((c, i) => `${c}=${JSON.stringify(vals[i])}`).join(", ")}
━━━━━━━━━━━━━━━━━━`;
    }

    // 6. DELETE FROM Queries
    const deleteMatch = cleanSql.match(/^\s*DELETE\s+FROM\s+[`"']?([a-zA-Z0-9_-]+)[`"']?\s+WHERE\s+(.+)\s*$/i);
    if (deleteMatch) {
      let rawTable = deleteMatch[1].toLowerCase();
      if (rawTable === "promocodes") rawTable = "promo_codes";
      if (rawTable === "botlogs") rawTable = "bot_logs";

      const whereClause = deleteMatch[2].trim();
      if (!whereClause) {
        return "❌ Ошибка: Удаление без условия WHERE запрещено!";
      }

      const snap = await firestoreDb.collection(rawTable).get();
      let deletedCount = 0;

      for (const doc of snap.docs) {
        const docData = { _id: doc.id, ...doc.data() };
        if (matchCondition(docData, whereClause)) {
          await firestoreDb.collection(rawTable).doc(doc.id).delete();
          if (rawTable === "users") userCache.delete(Number(docData.userId || doc.id));
          if (rawTable === "chats") chatCache.delete(Number(docData.id || doc.id));
          if (rawTable === "clans") clanCache.delete(docData.id || doc.id);
          deletedCount++;
        }
      }

      return `✅ SQL DELETE успешно выполнен!
━━━━━━━━━━━━━━━━━━
• Таблица: \`${rawTable}\`
• Удалено записей: ${deletedCount}
━━━━━━━━━━━━━━━━━━`;
    }

    return `❓ Не удалось распознать SQL-команду.

Поддерживаемые конструкции:
• SHOW TABLES
• DESCRIBE <таблица>
• SELECT <поля> FROM <таблица> [WHERE ...] [ORDER BY ...] [LIMIT n]
• UPDATE <таблица> SET col=val [WHERE ...]
• INSERT INTO <таблица> (cols) VALUES (vals)
• DELETE FROM <таблица> WHERE ...`;

  } catch (err: any) {
    return `❌ Ошибка при выполнении SQL-запроса:
${err?.message || err}`;
  }
}

/**
 * Executes a raw SQL query against the PostgreSQL database via HF Proxy
 */
async function executePostgresSqlQuery(sql: string): Promise<string> {
  const cleanSql = (sql || "").trim();
  if (!cleanSql) {
    return `💡 Использование команды /psql:

` +
      `• /psql SELECT * FROM users LIMIT 10
` +
      `• /psql SELECT count(*) FROM chats

` +
      `⚠️ Все запросы выполняются напрямую в PostgreSQL на Hugging Face.`;
  }

  // Basic security for non-owner roles (if we ever expand), but here we trust the owner
  if (/^\s*(DROP|TRUNCATE|ALTER)\b/i.test(cleanSql)) {
    return "❌ Опасные операции (DROP, TRUNCATE, ALTER) запрещены через эту команду.";
  }

  try {
    const hfProxyUrl = process.env.POSTGRES_HTTP_URL || "https://romanjordansky-bot-jordans.hf.space";
    const secretKey = process.env.POSTGRES_PASSWORD || "my_super_secret_password";

    let response: any = null;
    for (let attempt = 1; attempt <= 3; attempt++) {
      try {
        response = await fetch(`${hfProxyUrl}/query`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            key: secretKey,
            sql: cleanSql
          }),
          signal: AbortSignal.timeout(35000)
        });
        if (response.ok) break;
        const errJson = await response.clone().json().catch(() => null);
        const isConnRefused = errJson && (errJson.error?.includes("ECONNREFUSED") || errJson.code === "ECONNREFUSED");
        if (attempt < 3 && (isConnRefused || response.status === 503 || response.status === 500)) {
          console.warn("[PostgreSQL] HTTP 500/503 or ECONNREFUSED from Space, retrying query...", errJson);
          await new Promise(r => setTimeout(r, 1000));
          continue;
        }
      } catch (err: any) {
        if (attempt < 3) {
          console.warn("[PostgreSQL] Connection refused or timed out, retrying query...", err?.message);
          await new Promise(r => setTimeout(r, 1000));
        } else {
          throw err;
        }
      }
    }

    if (!response.ok) {
      const errData = await response.json().catch(() => ({ error: response.statusText }));
      throw new Error(errData.error || `HTTP ${response.status}`);
    }

    const data = await response.json();
    const rowsArr = Array.isArray(data) ? data : (Array.isArray(data?.rows) ? data.rows : null);
    
    // If it was a SELECT query, data is usually an array of rows
    if (rowsArr) {
      if (rowsArr.length === 0) return "✅ Запрос выполнен. Результат пуст (0 строк).";

      const cols = Object.keys(rowsArr[0]);
      const header = `| ${cols.join(" | ")} |`;
      const separator = `| ${cols.map(() => "---").join(" | ")} |`;
      const rows = rowsArr.slice(0, 15).map(row => {
        return `| ${cols.map(c => {
          const val = row[c];
          if (val === null) return "NULL";
          if (typeof val === "object") return JSON.stringify(val).slice(0, 20) + "...";
          return String(val).slice(0, 30);
        }).join(" | ")} |`;
      });

      let res = `✅ Результат запроса (${rowsArr.length} строк):

${header}
${separator}
${rows.join("\n")}`;

      if (rowsArr.length > 15) res += `

... и еще ${rowsArr.length - 15} строк.`;
      return res;
    }

    // For non-SELECT (UPDATE/INSERT/DELETE), it might return a count or status
    return `✅ Запрос успешно выполнен.
Результат: ${JSON.stringify(data)}`;

  } catch (e: any) {
    return `❌ Ошибка PostgreSQL:
${e.message}`;
  }
}

