          const curPage = Math.max(1, Math.min(p, totalPages));
          const startIndex = (curPage - 1) * pageSize;
          const pageItems = listArr.slice(startIndex, startIndex + pageSize);

          let out = `❄️ Удалённые/замороженные участники (${listArr.length}):

`;
