// Currency Exchange: /курс, /курс [валюта], /курс [валюта1] [валюта2], /курс [сумма] [валюта1] [валюта2], /rate, /курсы, /курсывалют
if (["/курс", "/rate", "/курсы", "/курсывалют", "/rates", "/exchange"].includes(rawCmd)) {
let baseInput = "";
let targetInput = "";
let amountInput = 1;

const filteredArgs = args.slice(1)
.map(a => a.trim())
.filter(a => a.length > 0 && !["в", "во", "к", "ко", "на", "to", "in", "into", "->", "=>"].includes(a.toLowerCase()));

if (filteredArgs.length === 1) {
const arg1 = filteredArgs[0].toLowerCase();
if (["коин", "коина", "коинов", "jc", "coin", "jordan"].includes(arg1)) {
return await sendResponse(`Курс JORDAN'S COIN
| Стоимость одного JORDAN'S COIN: ${globalSettings.jcRate.toLocaleString()}$`);
} else if (/^\d+([.,]\d+)?$/.test(arg1)) {
amountInput = parseFloat(arg1.replace(",", "."));
} else {
baseInput = arg1;
}
} else if (filteredArgs.length === 2) {
const arg1 = filteredArgs[0].toLowerCase();
const arg2 = filteredArgs[1].toLowerCase();

if (/^\d+([.,]\d+)?$/.test(arg1)) {
amountInput = parseFloat(arg1.replace(",", "."));
baseInput = arg2;
} else if (/^\d+([.,]\d+)?$/.test(arg2)) {
baseInput = arg1;
amountInput = parseFloat(arg2.replace(",", "."));
} else {
baseInput = arg1;
targetInput = arg2;
}
} else if (filteredArgs.length >= 3) {
const numIdx = filteredArgs.findIndex(a => /^\d+([.,]\d+)?$/.test(a));
if (numIdx !== -1) {
amountInput = parseFloat(filteredArgs[numIdx].replace(",", "."));
const currencyTokens = filteredArgs.filter((_, idx) => idx !== numIdx);
baseInput = currencyTokens[0] || "";
targetInput = currencyTokens[1] || "";
} else {
baseInput = filteredArgs[0];
targetInput = filteredArgs[1];
}
}

const { text, keyboard } = await getExchangeRatesResponse(baseInput, targetInput, amountInput);
return await sendResponse(text, { keyboard: JSON.stringify(keyboard) });
}

